window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G03"] = {"bang":[{"i":0,"tieu_de_bang":"Phan Thiết – Trường Dục Thanh","tieu_de":"Phan Thiết, mùa thu 1910: khi người thanh niên Nguyễn Tất Thành làm thầy giáo bên dòng Cà Ty","sapo":"Trên bản đồ hành trình của Chủ tịch Hồ Chí Minh, Phan Thiết chỉ là một chấm nhỏ, và thời gian Người ở đây chưa đầy nửa năm. Nhưng đó là chặng dừng chân dài cuối cùng trên đất Việt trước khi người thanh niên hai mươi tuổi xuống tàu ra đi. Vì sao anh dừng lại ở thị xã nước mắm bên dòng Cà Ty, và ở ngôi trường nhỏ ấy anh đã thấy những gì?","bia":{"src":"textures/bai/G03_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bước vào lớp học năm 1910","text":"Bước vào gian trưng bày, người xem gặp trước hết một lớp học. Hai mươi mốt bộ bàn ghế học trò xếp thành ba dãy ngay ngắn, cùng hướng về phía bảng. Phía trước là bàn thầy giáo với một ngọn đèn dầu, sau lưng là hai tấm bảng đen treo trên vách gỗ. Con số hai mươi mốt không phải ngẫu nhiên: trong lớp học ở khu di tích Trường Dục Thanh, Phan Thiết, hiện cũng kê đúng hai mươi mốt bộ bàn ghế học trò. Ở những góc khác của gian là chiếc phản gỗ, chiếc bàn nhỏ gợi nhớ nhà Ngọa Du Sào, và chiếc giếng gạch giữa sân.\n\nKhông gian ấy tái hiện một ngôi trường tư nhỏ bên sông Cà Ty trong niên học 1910 – 1911. Ngôi trường khi ấy có thêm một thầy giáo mới, hai mươi tuổi, quê Nghệ An, được học trò gọi là thầy Thành. Chưa đầy nửa năm sau, thầy rời trường vào Sài Gòn. Bốn tháng nữa, người thầy giáo ấy xuống tàu ra đi tìm đường cứu nước, mở đầu ba mươi năm bôn ba khắp năm châu. Gian trưng bày này kể về chặng dừng chân dài cuối cùng của Người trên đất Việt trước chuyến đi lịch sử đó.","doc":1},{"loai":"anh","src":"textures/bang_w/G03_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phan Thiết – Trường Dục Thanh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai mươi tuổi, giữa một đất nước chưa tìm ra lối","text":"Nguyễn Tất Thành sinh ngày 19/5/1890, tròn hai mươi tuổi vào năm 1910. Đó là những năm u ám của các phong trào yêu nước đầu thế kỷ XX. Ở Hà Nội, Đông Kinh Nghĩa Thục mở tháng 3/1907 thì cuối năm ấy đã bị thực dân đóng cửa. Phong trào Đông Du tan vỡ khi chính quyền Nhật Bản trục xuất du học sinh Việt Nam trong những năm 1908 – 1909, và Phan Bội Châu phải rời Nhật. Ở Trung Kỳ, phong trào chống sưu thuế năm 1908 lan từ Quảng Nam ra tận Huế rồi bị đàn áp đẫm máu. Chính người học trò Trường Quốc Học Nguyễn Tất Thành đã có mặt trong đoàn biểu tình ở kinh đô (xem gian Huế – Kinh thành và trường Quốc Học).\n\nSau năm 1908, nhiều nhà Duy Tân bị bắt, bị đày, có người bị xử tử. Trên núi rừng Yên Thế, nghĩa quân Hoàng Hoa Thám vẫn cầm cự nhưng ngày càng đơn độc. Con đường cứu nước của lớp cha anh, dù bằng gươm giáo hay bằng sách vở, đều đang gặp bế tắc. Câu hỏi phải đi con đường nào để cứu nước, cứu dân được đặt ra gay gắt trước người thanh niên hai mươi tuổi, đúng lúc gia đình anh cũng gặp biến cố lớn.","doc":2},{"loai":"ban_co_biet","text":"Năm 1905, ba nhà nho Quảng Nam đi vào các tỉnh phía Nam cổ động Duy Tân. Chỉ ba năm sau, trong năm 1908, cả ba đều gặp nạn: Trần Quý Cáp bị xử chém ở Khánh Hòa, còn Phan Châu Trinh và Huỳnh Thúc Kháng bị đày ra Côn Đảo.","nguon_ten":"Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục","doc":3},{"loai":"doan","tieu_de":"Thị xã nước mắm bên dòng Cà Ty","text":"Phan Thiết, nơi người thanh niên dừng chân, khi ấy là tỉnh lỵ của Bình Thuận, tỉnh cực nam của Trung Kỳ, giáp với xứ Nam Kỳ thuộc địa. Dòng Cà Ty, còn gọi là sông Phan Thiết, chảy qua lòng thị xã rồi đổ ra biển. Trên sông, thuyền nan, thuyền thúng của ngư dân ra vào theo con nước.\n\nPhan Thiết sống nhờ nghề cá. Vùng biển Bình Thuận nhiều cá, nghề đánh bắt và đội ghe thuyền khá phát triển, nghề làm nước mắm có truyền thống lâu đời. Nước mắm là mặt hàng làm nên tên tuổi của thị xã, và cũng là nguồn lợi mà các nhà nho yêu nước ở đây biết tận dụng để làm việc lớn. So với kinh đô Huế, nơi chính quyền bảo hộ và triều đình kiểm soát chặt chẽ, Phan Thiết là một thị xã nhỏ ở xa, gần Sài Gòn hơn, có nguồn hàng đi khắp các tỉnh. Đó là mảnh đất thuận lợi để tư tưởng Duy Tân bén rễ, và để một ngôi trường kiểu mới ra đời.","doc":4},{"loai":"ban_co_biet","text":"Khi thầy Thành đến dạy học năm 1910, thị xã Phan Thiết mới hơn mười năm tuổi: thị xã được lập theo đạo dụ của vua Thành Thái ban hành ngày 20/10/1898.","nguon_ten":"Báo Bình Thuận – 120 năm Phan Thiết được công nhận thị xã","doc":5},{"loai":"doan","tieu_de":"Khi tư tưởng Duy Tân về Phan Thiết","text":"Năm 1905, ba nhà nho Quảng Nam là Phan Châu Trinh, Huỳnh Thúc Kháng và Trần Quý Cáp làm một chuyến đi vào các tỉnh phía Nam Trung Kỳ để tìm hiểu dân tình, cổ động tư tưởng Duy Tân. Ở Phan Thiết, các ông gặp gỡ, bàn bạc tại nhà ông Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông. Tư tưởng của các ông gói trong ba vế: khai dân trí, chấn dân khí, hậu dân sinh. Nghĩa là mở mang hiểu biết cho dân, nâng cao tinh thần tự cường, và làm cho đời sống của dân khá lên.\n\nỞ nhiều nơi, những lời hiệu triệu ấy chỉ dừng lại trên giấy. Ở Phan Thiết, chúng thành việc làm cụ thể. Tháng 3/1906, các nhà nho địa phương lập hội buôn Liên Thành, làm nước mắm để có vốn. Tháng 5/1906, hội mở thư xã để phổ biến sách báo mới. Năm 1907, Trường Dục Thanh ra đời, mọi chi phí do Liên Thành gánh vác. Câu chuyện hội buôn nuôi trường được kể riêng ở chuyên đề Hội buôn nước mắm nuôi một ngôi trường. Ở đây chỉ cần nhớ rằng Dục Thanh là con đẻ của phong trào Duy Tân, và vì thế ngay từ đầu đã là một ngôi trường khác thường.","doc":6},{"loai":"doan","tieu_de":"Một ngôi trường khác thường","text":"Tên trường, Dục Thanh, có nghĩa là giáo dục lớp thanh thiếu niên. Trường dựng trên khu vườn của gia đình cụ Nguyễn Thông, bên bờ sông Cà Ty. Học trò khoảng năm, sáu mươi em, chia thành bốn lớp Tư, Ba, Nhì, Nhất. Chữ Quốc ngữ được dạy làm môn chính, bên cạnh chữ Hán, chữ Pháp và môn thể dục. Học trò ở xa được ở nội trú ngay trong khuôn viên.\n\nĐặt vào thời ấy, chương trình này rất mới. Phần đông con em vẫn theo lối học khoa cử, ngồi đọc kinh sử chữ Hán để chờ ngày đi thi. Các trường Pháp – Việt thì do chính quyền thuộc địa quản lý, dạy theo mục đích của người cai trị. Dục Thanh đứng giữa hai lối ấy: một trường tư của người Việt, lấy chữ Quốc ngữ làm gốc để mở mang hiểu biết cho số đông, coi trọng sức khỏe của học trò, và gửi vào từng bài học tình yêu quê hương. Đó là mô hình mà Đông Kinh Nghĩa Thục ở Hà Nội từng theo đuổi, nhưng ở Phan Thiết, nó còn tồn tại được sau khi ngôi trường nổi tiếng ngoài Bắc đã bị đóng cửa.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","chu_thich":"Bên trong lớp học Trường Dục Thanh ngày nay, được phục dựng theo dáng xưa trong những năm 1978 – 1980.","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Thầy giáo mới của lớp nhì","text":"Mùa thu năm 1910, ngôi trường ấy đón một thầy giáo mới. Người thanh niên đến từ Bình Định, qua Phan Rang, được một nhà nho yêu nước, bạn thân của cha, giới thiệu với các nhà Duy Tân Phan Thiết (xem chuyên đề Một mình đi về phương Nam). Thầy được giao lớp nhì, dạy chủ yếu chữ Quốc ngữ, chữ Hán, kiêm môn thể dục; khi trường cần, thầy dạy thay cả tiếng Pháp.\n\nThầy ở ngay nhà Ngư, dãy nhà nội trú trong khuôn viên, đọc sách và soạn bài ở thư viện Ngọa Du Sào. Ngoài giờ lên lớp, thầy dắt học trò đi thăm cảnh vật quê hương, ghé những xóm chài ven biển, vừa đi vừa kể chuyện Hai Bà Trưng, Bà Triệu. Học trò cũ, mấy chục năm sau, vẫn nhớ một người thầy giảng bài nhiệt tình, dễ hiểu, vừa nghiêm vừa gần gũi như một người bạn lớn. Từng mặt đời sống của thầy ở Dục Thanh được kể kỹ trong các chuyên đề về lớp học, thư viện, giếng nước và dòng sông của gian này.","doc":8},{"loai":"doan","tieu_de":"Những gì Phan Thiết trao cho người thanh niên","text":"Chưa đầy nửa năm là quãng thời gian ngắn trong cuộc đời bảy mươi chín năm của Chủ tịch Hồ Chí Minh. Nhưng đó là lần đầu tiên người thanh niên sống tự lập, xa cha, xa quê, tự lo cho mình bằng chính công việc của mình. Cũng là lần đầu anh không ngồi ở bàn học trò mà đứng trước lớp, chịu trách nhiệm với mấy chục đứa trẻ đang tuổi ăn tuổi lớn.\n\nỞ Phan Thiết, anh sống giữa những con người đang thử một cách yêu nước mới. Họ là nhà nho nhưng đi buôn, học chữ thánh hiền nhưng dạy chữ Quốc ngữ, làm ra tiền rồi đem tiền ấy mở trường, mở thư xã. Anh sống cạnh những người từng tiếp đón Phan Châu Trinh, được đọc sách báo mới trong thư viện của trường. Đồng thời, anh cũng chứng kiến giới hạn của con đường ấy: sau năm 1908, các nhà Duy Tân bị bắt, bị đày, bị theo dõi, và một ngôi trường nhỏ ở tỉnh lẻ không thể thay đổi số phận của cả dân tộc. Người thầy giáo trẻ không chọn ở lại. Anh đi tiếp, tìm đến những chân trời mà các bậc cha anh chưa đặt chân tới.","doc":9},{"loai":"anh","src":"textures/bang_w/G03_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phan Thiết – Trường Dục Thanh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ bục giảng đến bến tàu","text":"Tháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn. Ở thành phố cảng, anh ở tạm tại các cơ sở của hội Liên Thành, học nghề và tìm việc trên những con tàu viễn dương (xem gian Sài Gòn – Bến Nhà Rồng). Ngày 5/6/1911, với tên gọi Văn Ba, anh làm phụ bếp trên tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ra đi.\n\nNgười thầy giáo Dục Thanh năm ấy sẽ vượt qua nhiều đại dương, sống và hoạt động ở Pháp, Anh, Mỹ, Liên Xô, Trung Quốc, Thái Lan. Anh lấy tên Nguyễn Ái Quốc, tìm thấy con đường cứu nước, chủ trì hội nghị hợp nhất các tổ chức cộng sản đầu năm 1930 tại Cửu Long, Hương Cảng. Ngày 28/1/1941, Người về nước qua cột mốc 108, và từ tháng 8/1942 mang tên Hồ Chí Minh. Ngày 2/9/1945, Người đọc Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa. Hơn ba mươi tư năm sau ngày rời trường, người thầy giáo trẻ bên dòng Cà Ty đã đứng đầu một quốc gia độc lập.","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh_noi_bac_ho_day_o_truong_duc_tha.jpg","chu_thich":"Gian nhà nơi thầy Nguyễn Tất Thành dạy học ở Trường Dục Thanh, ảnh chụp năm 2016.","credit":"Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đọc gian trưng bày","text":"Gian trưng bày được bố trí để người xem đi từ tổng quát đến chi tiết. Câu chuyện 1, Một mình đi về phương Nam, theo chân người thanh niên từ huyện Bình Khê qua Phan Rang, làng Duồng tới Phan Thiết. Câu chuyện 2, Hội buôn nước mắm nuôi một ngôi trường, kể về hội Liên Thành, nơi những nhà nho làm kinh tế để lo cho việc học. Bảng Mốc thời gian nối lịch sử ngôi trường với hành trình của người thầy giáo, từ ngôi nhà của nhà thơ Nguyễn Thông năm 1880 đến khu di tích hôm nay.\n\nNăm bảng ảnh tư liệu dẫn người xem vào từng góc của di tích. Đó là những nếp nhà gỗ còn giữ dáng xưa, lớp học nơi thầy Thành dạy lớp nhì, gian nhà gợi nhớ sự nghiệp trồng người của Bác, chiếc giếng trong sân, dòng Cà Ty và những xóm chài. Ba bảng hiện vật đứng cạnh những gì được dựng lại trong không gian 3D: lớp học với bàn ghế, bảng đen; nhà Ngọa Du Sào của nhà thơ Nguyễn Thông; chiếc giếng gạch. Bấm vào bàn ghế, ngọn đèn dầu hay chiếc giếng, người xem sẽ nghe thêm những câu chuyện gắn với đời sống của thầy trò Dục Thanh.","doc":11},{"loai":"anh","src":"textures/bang_w/G03_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Phan Thiết – Trường Dục Thanh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Trường Dục Thanh ngày nay là khu di tích ở số 39 đường Trưng Nhị, bên bờ sông Cà Ty. Từ ngày 1/7/2025, sau khi sắp xếp địa giới hành chính, nơi này thuộc phường Phan Thiết, tỉnh Lâm Đồng. Các công trình được trùng tu theo dáng xưa từ tháng 11/1978 đến tháng 12/1980, dựa trên phần di tích còn lại và lời kể của những học trò cũ. Năm 1986, khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận được khánh thành ngay bên cạnh.\n\nNgười đến thăm hôm nay có thể ngồi vào bàn học trò trong lớp, đứng bên chiếc giếng gạch và cây khế cổ thụ, nhìn ngôi nhà nhỏ Ngọa Du Sào, rồi ra đứng bên bờ sông Cà Ty. Nhiều trường học, đoàn thanh niên chọn nơi đây làm điểm về nguồn, nhất là vào tháng Năm và dịp Ngày Nhà giáo Việt Nam. Hơn một thế kỷ đã qua, nhưng những bài học đầu tiên của người thầy giáo trẻ về chữ nghĩa, về sức khỏe và về lòng yêu quê hương vẫn được kể lại trong chính ngôi trường ấy.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","Báo Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành – https://tuoitre.vn/nld/hoi-nhap/bai-1-phong-trao-duy-tan-o-binh-thuan-da-khai-sinh-ra-lien-thanh-20090522104457589.htm","VUSTA – Công ty Liên Thành (1906–1975): Từ hội Duy Tân đến doanh nghiệp hiện đại – https://vusta.vn/cong-ty-lien-thanh-1906-1975-tu-hoi-duy-tan-den-doanh-nghiep-hien-dai-p77095.html","Báo Bình Thuận – 120 năm Phan Thiết được công nhận thị xã","Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục"],"doc":[{"t":"Phan Thiết, mùa thu 1910: khi người thanh niên Nguyễn Tất Thành làm thầy giáo bên dòng Cà Ty. Trên bản đồ hành trình của Chủ tịch Hồ Chí Minh, Phan Thiết chỉ là một chấm nhỏ, và thời gian Người ở đây chưa đầy nửa năm. Nhưng đó là chặng dừng chân dài cuối cùng trên đất Việt trước khi người thanh niên hai mươi tuổi xuống tàu ra đi. Vì sao anh dừng lại ở thị xã nước mắm bên dòng Cà Ty, và ở ngôi trường nhỏ ấy anh đã thấy những gì?"},{"t":"Bước vào lớp học năm 1910. Bước vào gian trưng bày, người xem gặp trước hết một lớp học. Hai mươi mốt bộ bàn ghế học trò xếp thành ba dãy ngay ngắn, cùng hướng về phía bảng. Phía trước là bàn thầy giáo với một ngọn đèn dầu, sau lưng là hai tấm bảng đen treo trên vách gỗ. Con số hai mươi mốt không phải ngẫu nhiên: trong lớp học ở khu di tích Trường Dục Thanh, Phan Thiết, hiện cũng kê đúng hai mươi mốt bộ bàn ghế học trò. Ở những góc khác của gian là chiếc phản gỗ, chiếc bàn nhỏ gợi nhớ nhà Ngọa Du Sào, và chiếc giếng gạch giữa sân. Không gian ấy tái hiện một ngôi trường tư nhỏ bên sông Cà Ty trong niên học 1910 – 1911. Ngôi trường khi ấy có thêm một thầy giáo mới, hai mươi tuổi, quê Nghệ An, được học trò gọi là thầy Thành. Chưa đầy nửa năm sau, thầy rời trường vào Sài Gòn. Bốn tháng nữa, người thầy giáo ấy xuống tàu ra đi tìm đường cứu nước, mở đầu ba mươi năm bôn ba khắp năm châu. Gian trưng bày này kể về chặng dừng chân dài cuối cùng của Người trên đất Việt trước chuyến đi lịch sử đó."},{"t":"Hai mươi tuổi, giữa một đất nước chưa tìm ra lối. Nguyễn Tất Thành sinh ngày 19/5/1890, tròn hai mươi tuổi vào năm 1910. Đó là những năm u ám của các phong trào yêu nước đầu thế kỷ XX. Ở Hà Nội, Đông Kinh Nghĩa Thục mở tháng 3/1907 thì cuối năm ấy đã bị thực dân đóng cửa. Phong trào Đông Du tan vỡ khi chính quyền Nhật Bản trục xuất du học sinh Việt Nam trong những năm 1908 – 1909, và Phan Bội Châu phải rời Nhật. Ở Trung Kỳ, phong trào chống sưu thuế năm 1908 lan từ Quảng Nam ra tận Huế rồi bị đàn áp đẫm máu. Chính người học trò Trường Quốc Học Nguyễn Tất Thành đã có mặt trong đoàn biểu tình ở kinh đô (xem gian Huế – Kinh thành và trường Quốc Học). Sau năm 1908, nhiều nhà Duy Tân bị bắt, bị đày, có người bị xử tử. Trên núi rừng Yên Thế, nghĩa quân Hoàng Hoa Thám vẫn cầm cự nhưng ngày càng đơn độc. Con đường cứu nước của lớp cha anh, dù bằng gươm giáo hay bằng sách vở, đều đang gặp bế tắc. Câu hỏi phải đi con đường nào để cứu nước, cứu dân được đặt ra gay gắt trước người thanh niên hai mươi tuổi, đúng lúc gia đình anh cũng gặp biến cố lớn."},{"t":"Bạn có biết? Năm 1905, ba nhà nho Quảng Nam đi vào các tỉnh phía Nam cổ động Duy Tân. Chỉ ba năm sau, trong năm 1908, cả ba đều gặp nạn: Trần Quý Cáp bị xử chém ở Khánh Hòa, còn Phan Châu Trinh và Huỳnh Thúc Kháng bị đày ra Côn Đảo."},{"t":"Thị xã nước mắm bên dòng Cà Ty. Phan Thiết, nơi người thanh niên dừng chân, khi ấy là tỉnh lỵ của Bình Thuận, tỉnh cực nam của Trung Kỳ, giáp với xứ Nam Kỳ thuộc địa. Dòng Cà Ty, còn gọi là sông Phan Thiết, chảy qua lòng thị xã rồi đổ ra biển. Trên sông, thuyền nan, thuyền thúng của ngư dân ra vào theo con nước. Phan Thiết sống nhờ nghề cá. Vùng biển Bình Thuận nhiều cá, nghề đánh bắt và đội ghe thuyền khá phát triển, nghề làm nước mắm có truyền thống lâu đời. Nước mắm là mặt hàng làm nên tên tuổi của thị xã, và cũng là nguồn lợi mà các nhà nho yêu nước ở đây biết tận dụng để làm việc lớn. So với kinh đô Huế, nơi chính quyền bảo hộ và triều đình kiểm soát chặt chẽ, Phan Thiết là một thị xã nhỏ ở xa, gần Sài Gòn hơn, có nguồn hàng đi khắp các tỉnh. Đó là mảnh đất thuận lợi để tư tưởng Duy Tân bén rễ, và để một ngôi trường kiểu mới ra đời."},{"t":"Bạn có biết? Khi thầy Thành đến dạy học năm 1910, thị xã Phan Thiết mới hơn mười năm tuổi: thị xã được lập theo đạo dụ của vua Thành Thái ban hành ngày 20/10/1898."},{"t":"Khi tư tưởng Duy Tân về Phan Thiết. Năm 1905, ba nhà nho Quảng Nam là Phan Châu Trinh, Huỳnh Thúc Kháng và Trần Quý Cáp làm một chuyến đi vào các tỉnh phía Nam Trung Kỳ để tìm hiểu dân tình, cổ động tư tưởng Duy Tân. Ở Phan Thiết, các ông gặp gỡ, bàn bạc tại nhà ông Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông. Tư tưởng của các ông gói trong ba vế: khai dân trí, chấn dân khí, hậu dân sinh. Nghĩa là mở mang hiểu biết cho dân, nâng cao tinh thần tự cường, và làm cho đời sống của dân khá lên. Ở nhiều nơi, những lời hiệu triệu ấy chỉ dừng lại trên giấy. Ở Phan Thiết, chúng thành việc làm cụ thể. Tháng 3/1906, các nhà nho địa phương lập hội buôn Liên Thành, làm nước mắm để có vốn. Tháng 5/1906, hội mở thư xã để phổ biến sách báo mới. Năm 1907, Trường Dục Thanh ra đời, mọi chi phí do Liên Thành gánh vác. Câu chuyện hội buôn nuôi trường được kể riêng ở chuyên đề Hội buôn nước mắm nuôi một ngôi trường. Ở đây chỉ cần nhớ rằng Dục Thanh là con đẻ của phong trào Duy Tân, và vì thế ngay từ đầu đã là một ngôi trường khác thường."},{"t":"Một ngôi trường khác thường. Tên trường, Dục Thanh, có nghĩa là giáo dục lớp thanh thiếu niên. Trường dựng trên khu vườn của gia đình cụ Nguyễn Thông, bên bờ sông Cà Ty. Học trò khoảng năm, sáu mươi em, chia thành bốn lớp Tư, Ba, Nhì, Nhất. Chữ Quốc ngữ được dạy làm môn chính, bên cạnh chữ Hán, chữ Pháp và môn thể dục. Học trò ở xa được ở nội trú ngay trong khuôn viên. Đặt vào thời ấy, chương trình này rất mới. Phần đông con em vẫn theo lối học khoa cử, ngồi đọc kinh sử chữ Hán để chờ ngày đi thi. Các trường Pháp – Việt thì do chính quyền thuộc địa quản lý, dạy theo mục đích của người cai trị. Dục Thanh đứng giữa hai lối ấy: một trường tư của người Việt, lấy chữ Quốc ngữ làm gốc để mở mang hiểu biết cho số đông, coi trọng sức khỏe của học trò, và gửi vào từng bài học tình yêu quê hương. Đó là mô hình mà Đông Kinh Nghĩa Thục ở Hà Nội từng theo đuổi, nhưng ở Phan Thiết, nó còn tồn tại được sau khi ngôi trường nổi tiếng ngoài Bắc đã bị đóng cửa."},{"t":"Thầy giáo mới của lớp nhì. Mùa thu năm 1910, ngôi trường ấy đón một thầy giáo mới. Người thanh niên đến từ Bình Định, qua Phan Rang, được một nhà nho yêu nước, bạn thân của cha, giới thiệu với các nhà Duy Tân Phan Thiết (xem chuyên đề Một mình đi về phương Nam). Thầy được giao lớp nhì, dạy chủ yếu chữ Quốc ngữ, chữ Hán, kiêm môn thể dục; khi trường cần, thầy dạy thay cả tiếng Pháp. Thầy ở ngay nhà Ngư, dãy nhà nội trú trong khuôn viên, đọc sách và soạn bài ở thư viện Ngọa Du Sào. Ngoài giờ lên lớp, thầy dắt học trò đi thăm cảnh vật quê hương, ghé những xóm chài ven biển, vừa đi vừa kể chuyện Hai Bà Trưng, Bà Triệu. Học trò cũ, mấy chục năm sau, vẫn nhớ một người thầy giảng bài nhiệt tình, dễ hiểu, vừa nghiêm vừa gần gũi như một người bạn lớn. Từng mặt đời sống của thầy ở Dục Thanh được kể kỹ trong các chuyên đề về lớp học, thư viện, giếng nước và dòng sông của gian này."},{"t":"Những gì Phan Thiết trao cho người thanh niên. Chưa đầy nửa năm là quãng thời gian ngắn trong cuộc đời bảy mươi chín năm của Chủ tịch Hồ Chí Minh. Nhưng đó là lần đầu tiên người thanh niên sống tự lập, xa cha, xa quê, tự lo cho mình bằng chính công việc của mình. Cũng là lần đầu anh không ngồi ở bàn học trò mà đứng trước lớp, chịu trách nhiệm với mấy chục đứa trẻ đang tuổi ăn tuổi lớn. Ở Phan Thiết, anh sống giữa những con người đang thử một cách yêu nước mới. Họ là nhà nho nhưng đi buôn, học chữ thánh hiền nhưng dạy chữ Quốc ngữ, làm ra tiền rồi đem tiền ấy mở trường, mở thư xã. Anh sống cạnh những người từng tiếp đón Phan Châu Trinh, được đọc sách báo mới trong thư viện của trường. Đồng thời, anh cũng chứng kiến giới hạn của con đường ấy: sau năm 1908, các nhà Duy Tân bị bắt, bị đày, bị theo dõi, và một ngôi trường nhỏ ở tỉnh lẻ không thể thay đổi số phận của cả dân tộc. Người thầy giáo trẻ không chọn ở lại. Anh đi tiếp, tìm đến những chân trời mà các bậc cha anh chưa đặt chân tới."},{"t":"Từ bục giảng đến bến tàu. Tháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn. Ở thành phố cảng, anh ở tạm tại các cơ sở của hội Liên Thành, học nghề và tìm việc trên những con tàu viễn dương (xem gian Sài Gòn – Bến Nhà Rồng). Ngày 5/6/1911, với tên gọi Văn Ba, anh làm phụ bếp trên tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ra đi. Người thầy giáo Dục Thanh năm ấy sẽ vượt qua nhiều đại dương, sống và hoạt động ở Pháp, Anh, Mỹ, Liên Xô, Trung Quốc, Thái Lan. Anh lấy tên Nguyễn Ái Quốc, tìm thấy con đường cứu nước, chủ trì hội nghị hợp nhất các tổ chức cộng sản đầu năm 1930 tại Cửu Long, Hương Cảng. Ngày 28/1/1941, Người về nước qua cột mốc 108, và từ tháng 8/1942 mang tên Hồ Chí Minh. Ngày 2/9/1945, Người đọc Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa. Hơn ba mươi tư năm sau ngày rời trường, người thầy giáo trẻ bên dòng Cà Ty đã đứng đầu một quốc gia độc lập."},{"t":"Đọc gian trưng bày. Gian trưng bày được bố trí để người xem đi từ tổng quát đến chi tiết. Câu chuyện 1, Một mình đi về phương Nam, theo chân người thanh niên từ huyện Bình Khê qua Phan Rang, làng Duồng tới Phan Thiết. Câu chuyện 2, Hội buôn nước mắm nuôi một ngôi trường, kể về hội Liên Thành, nơi những nhà nho làm kinh tế để lo cho việc học. Bảng Mốc thời gian nối lịch sử ngôi trường với hành trình của người thầy giáo, từ ngôi nhà của nhà thơ Nguyễn Thông năm 1880 đến khu di tích hôm nay. Năm bảng ảnh tư liệu dẫn người xem vào từng góc của di tích. Đó là những nếp nhà gỗ còn giữ dáng xưa, lớp học nơi thầy Thành dạy lớp nhì, gian nhà gợi nhớ sự nghiệp trồng người của Bác, chiếc giếng trong sân, dòng Cà Ty và những xóm chài. Ba bảng hiện vật đứng cạnh những gì được dựng lại trong không gian 3D: lớp học với bàn ghế, bảng đen; nhà Ngọa Du Sào của nhà thơ Nguyễn Thông; chiếc giếng gạch. Bấm vào bàn ghế, ngọn đèn dầu hay chiếc giếng, người xem sẽ nghe thêm những câu chuyện gắn với đời sống của thầy trò Dục Thanh."},{"t":"Dấu tích hôm nay. Trường Dục Thanh ngày nay là khu di tích ở số 39 đường Trưng Nhị, bên bờ sông Cà Ty. Từ ngày 1/7/2025, sau khi sắp xếp địa giới hành chính, nơi này thuộc phường Phan Thiết, tỉnh Lâm Đồng. Các công trình được trùng tu theo dáng xưa từ tháng 11/1978 đến tháng 12/1980, dựa trên phần di tích còn lại và lời kể của những học trò cũ. Năm 1986, khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận được khánh thành ngay bên cạnh. Người đến thăm hôm nay có thể ngồi vào bàn học trò trong lớp, đứng bên chiếc giếng gạch và cây khế cổ thụ, nhìn ngôi nhà nhỏ Ngọa Du Sào, rồi ra đứng bên bờ sông Cà Ty. Nhiều trường học, đoàn thanh niên chọn nơi đây làm điểm về nguồn, nhất là vào tháng Năm và dịp Ngày Nhà giáo Việt Nam. Hơn một thế kỷ đã qua, nhưng những bài học đầu tiên của người thầy giáo trẻ về chữ nghĩa, về sức khỏe và về lòng yêu quê hương vẫn được kể lại trong chính ngôi trường ấy."}],"so_chu":2219},{"i":1,"tieu_de_bang":"Một mình đi về phương Nam","tieu_de":"Từ Bình Khê đến Phan Thiết: chặng đường phương Nam của người thanh niên hai mươi tuổi","sapo":"Năm 1910, người cha vừa mất chức quan, còn người con trai không quay về Huế. Nguyễn Tất Thành một mình đi tiếp về phía Nam, qua những vùng đất lần đầu đặt chân tới, với vài mối quen biết của cha làm chỗ dựa. Ở làng biển Duồng, một ngôi chùa nhỏ và một nhà nho yêu nước đã mở cho anh cánh cửa vào Phan Thiết.","bia":{"src":"textures/bai/G03_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Châu điểm của vua Duy Tân","text":"Trong kho châu bản triều Nguyễn, tức những văn bản hành chính có bút phê của nhà vua, còn giữ một bản tấu của Bộ Lại đề ngày 11 tháng 4 năm Duy Tân thứ ba, tức năm 1909. Bản tấu xin bổ Phó bảng Nguyễn Sinh Huy làm tri huyện Bình Khê, tỉnh Bình Định, và được vua Duy Tân chấm châu điểm chuẩn y. Nguyễn Sinh Huy là tên cụ Nguyễn Sinh Sắc dùng trong quan trường. Sau mấy năm làm một chức quan nhỏ ở Bộ Lễ tại kinh đô, đây là lần đầu cụ ra trông coi một huyện.\n\nGiữa năm 1909, người con trai mười chín tuổi rời Trường Quốc Học Huế, theo cha vào nhiệm sở mới. Bình Khê là huyện nằm ở phía tây tỉnh Bình Định, nơi đồng bằng bắt đầu chuyển lên vùng đồi núi. Đây là quê hương của ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ, những người dựng nghiệp Tây Sơn cuối thế kỷ XVIII. Người thanh niên lớn lên trong những câu chuyện về các bậc anh hùng dân tộc nay được sống trên chính mảnh đất đã sinh ra người anh hùng áo vải Quang Trung.","doc":1},{"loai":"anh","src":"textures/bang_w/G03_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một mình đi về phương Nam”, nhìn từ xa."},{"loai":"doan","tieu_de":"Tiếng Pháp ở Quy Nhơn","text":"Theo các tư liệu về thời kỳ này, ở Bình Khê, Nguyễn Tất Thành thường được cha đưa đi thăm các sĩ phu trong vùng và các di tích Tây Sơn. Từ tháng 9/1909, cụ Phó bảng gửi con xuống Quy Nhơn, tỉnh lỵ ven biển của Bình Định, học tiếp ở trường tiểu học Pháp – Việt để trau dồi tiếng Pháp.\n\nVới người thanh niên đã sớm muốn hiểu thế giới bên ngoài, tiếng Pháp là một chiếc chìa khóa. Nó mở ra sách báo, tư tưởng của chính nước đang cai trị dân tộc mình, và mở đường cho những chuyến đi xa. Bình Định khi ấy vẫn chưa nguôi dư âm của phong trào chống sưu thuế năm 1908, khi nông dân nhiều tỉnh Trung Kỳ, trong đó có Bình Định, kéo lên phủ huyện đòi giảm sưu thuế và bị đàn áp. Người thanh niên từng xuống đường ở Huế năm ấy nay học tiếng Pháp giữa một vùng quê còn đầy vết thương. Nhưng chỉ vài tháng sau, một biến cố xảy ra ở huyện đường Bình Khê đã làm thay đổi tất cả.","doc":2},{"loai":"doan","tieu_de":"Vụ án ở huyện đường Bình Khê","text":"Theo các tài liệu viết về cụ, ở Bình Khê, cụ Phó bảng nổi tiếng là vị quan thương người nghèo, nghiêm khắc với bọn cường hào ức hiếp dân. Chính sự nghiêm khắc ấy dẫn tới biến cố. Theo châu bản triều Nguyễn, một địa chủ cường hào trong huyện chống đối, không chịu nộp thuế. Quan tri huyện sai lính nọc ra đánh đòn để răn đe. Hơn hai tháng sau, người này ốm chết, và vợ hắn làm đơn kiện lên trên.\n\nĐầu năm 1910, cụ Nguyễn Sinh Sắc bị cách chức tri huyện, bị đưa về Huế chờ xét xử. Với một vị quan, đó là cú ngã nặng nề. Với gia đình, đó là sự đảo lộn: danh phận và chỗ dựa của người cha bỗng không còn. Người con trai khi ấy đang học ở Quy Nhơn. Chặng đường theo cha vào phương Nam, bắt đầu từ Huế chưa đầy một năm trước, khép lại giữa chừng. Từ đây, người thanh niên phải tự quyết định bước đi của mình.","doc":3},{"loai":"ban_co_biet","text":"Vụ án ở Bình Khê được ghi trong châu bản triều Nguyễn, loại văn bản đang được lưu giữ tại Trung tâm Lưu trữ quốc gia I. Trong đó có bản tấu bổ nhiệm cụ làm tri huyện, đề năm Duy Tân thứ ba (1909), và bản tấu của Bộ Hình xử vụ án, đề năm Duy Tân thứ tư (1910).","nguon_ten":"Znews – Tài liệu quý hiếm về cụ Nguyễn Sinh Sắc từ văn thư triều Nguyễn; Trung tâm Lưu trữ quốc gia I – Châu bản triều Nguyễn","doc":4},{"loai":"doan","tieu_de":"Bản tấu của Bộ Hình","text":"Vụ án được Bộ Hình ở kinh đô xem xét. Trong bản tấu đề ngày 15 tháng 8 năm Duy Tân thứ tư, tức năm 1910, Bộ Hình nhận định người kia chết vì bệnh sau hơn hai tháng, “chớ không phải bị đánh chết tức thì, tình có thể tha thứ”. Quan tri huyện bị xử giáng bốn cấp. Bản án ấy khép lại con đường làm quan của cụ Phó bảng.\n\nSau biến cố ấy, cụ không trở lại chốn quan trường. Cụ vào Nam Kỳ, sống bằng nghề bốc thuốc, dạy học, đi nhiều nơi ở Nam Bộ, và mất năm 1929 tại Cao Lãnh, nay thuộc tỉnh Đồng Tháp. Còn người con trai, sau biến cố của cha, đã tự chọn cho mình một hướng đi khác hẳn. Anh không trở ra Huế, cũng không về làng Kim Liên, mà đi về phía những vùng đất anh chưa từng đặt chân tới.","doc":5},{"loai":"doan","tieu_de":"Ngã rẽ năm hai mươi tuổi","text":"Người cha bị đưa về kinh, người con trai đứng trước một ngã rẽ. Trở ra Huế, anh có thể ở cạnh cha trong những ngày khó khăn. Về quê Nghệ An, anh có họ hàng, làng xóm. Nhưng Nguyễn Tất Thành chọn con đường thứ ba: một mình đi tiếp về phía Nam.\n\nKhông có văn bản nào ghi lại lời anh giải thích quyết định này. Nhưng con đường anh đi nói lên nhiều điều. Từ Bình Định, anh không dừng lâu ở nơi nào, mà cứ xuôi dần về hướng Sài Gòn, thương cảng lớn nhất Nam Kỳ, nơi có những con tàu đi Pháp và đi khắp thế giới. Vài tháng sau, ở Sài Gòn, anh nói với một người bạn rằng mình muốn ra nước ngoài xem nước Pháp và các nước khác làm như thế nào, rồi trở về giúp đồng bào (xem gian Sài Gòn – Bến Nhà Rồng). Hành trang của anh khi rời Bình Định gồm vốn chữ Hán học từ nhỏ, chữ Quốc ngữ và tiếng Pháp học ở trường. Anh cũng đã rõ một lựa chọn: không đi theo con đường làm quan hay làm thông ngôn cho chính quyền bảo hộ.","doc":6},{"loai":"anh","src":"textures/bang_w/G03_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một mình đi về phương Nam”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Qua Phan Rang, tới làng Duồng","text":"Khoảng tháng 8/1910, Nguyễn Tất Thành rời Bình Định. Từ Bình Định vào phương Nam phải đi qua đất Phú Yên, Khánh Hòa. Rồi anh tới Phan Rang, tỉnh lỵ Ninh Thuận, vùng đất nắng gió, nơi có nhiều làng Chăm với những ngọn tháp cổ. Từ Phan Rang, anh đi tiếp về phía Nam, vượt qua ranh giới hai tỉnh để vào đất Bình Thuận.\n\nTheo tư liệu được Báo Thanh Niên dẫn lại, điểm dừng chân tiếp theo của anh là Duồng, một làng ven biển mà theo địa giới trước năm 2025 thuộc xã Chí Công, huyện Tuy Phong, tỉnh Bình Thuận. Tuy Phong là vùng cực bắc của Bình Thuận, khô hạn, nhiều gió cát, người dân sống chủ yếu nhờ biển. Người thanh niên hai mươi tuổi không tìm đến đây một cách tình cờ. Ở Duồng có một người bạn của gia đình, người sẽ giúp anh tìm được chỗ đứng ở Phan Thiết.","doc":7},{"loai":"doan","tieu_de":"Cụ Trương Gia Mô và ngôi chùa Phước An","text":"Người ấy là cụ Trương Gia Mô, hiệu Cúc Nông, sinh năm 1866, một nhà nho yêu nước và là bạn thân của cụ Phó bảng Nguyễn Sinh Sắc. Cụ gắn bó với phong trào Duy Tân và từng bị bắt giam năm 1908, khi thực dân đàn áp phong trào chống sưu thuế ở Trung Kỳ. Gặp con trai của bạn giữa lúc gia đình bạn gặp nạn, cụ Mô ân cần đón nhận.\n\nTheo lời kể được Báo Thanh Niên ghi lại, cụ cho anh ban ngày ở chùa Phước An, ban đêm đưa về nghỉ tại nhà mình. Lời kể không cho biết người thanh niên ở Duồng bao lâu, cũng không nói vì sao cụ sắp xếp như vậy. Dù vậy, chi tiết nhỏ ấy cho thấy sự chu đáo của người bạn già dành cho con trai của bạn mình. Trong lúc người thanh niên chờ đợi ở làng biển, cụ Trương Gia Mô lên đường vào Phan Thiết để lo cho anh một công việc.","doc":8},{"loai":"ban_co_biet","text":"Chùa Phước An ở làng Duồng, nơi Nguyễn Tất Thành được cụ Trương Gia Mô cho ở ban ngày năm 1910, nay được ghi nhận là một trong những nơi Bác Hồ từng dừng chân trên đất Bình Thuận.","nguon_ten":"Báo Lâm Đồng – Chùa Phước An, nơi Bác dừng chân thứ 2 ở Bình Thuận; Thanh Niên – Thầy Thành ở trường Dục Thanh","doc":9},{"loai":"doan","tieu_de":"Cánh cửa Dục Thanh mở ra","text":"Ở Phan Thiết, cụ Trương Gia Mô tìm gặp các nhà Duy Tân sáng lập hội Liên Thành, xin giúp đỡ người con trai của bạn mình. Người quyết định là ông Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông, một trong những người lập ra Trường Dục Thanh. Ông nhận lời để Nguyễn Tất Thành về dạy học ở trường.\n\nVới ngôi trường tư ở tỉnh lẻ, người thanh niên xứ Nghệ là một thầy giáo đáng quý. Anh thông chữ Hán, đọc được sách Pháp, viết thạo chữ Quốc ngữ, lại là con một vị Phó bảng có tiếng yêu nước. Còn với Nguyễn Tất Thành, lời nhận lời của ông Nguyễn Quý Anh mang lại nhiều hơn một công việc. Đó là một chỗ ở trong khuôn viên trường, một nơi để đọc sách, và một cộng đồng những người cùng chí hướng. Từ tháng 9/1910, học trò Dục Thanh có thêm một thầy giáo mới mà các em gọi là thầy Thành (xem chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp).","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh.jpg","chu_thich":"Trường Dục Thanh bên sông Cà Ty, nơi chặng đường phương Nam của Nguyễn Tất Thành dừng lại từ tháng 9/1910 đến tháng 2/1911.","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Rời Phan Thiết vào Sài Gòn","text":"Chưa đầy nửa năm sau, tháng 2/1911, thầy Thành rời Dục Thanh. Một lần nữa, người lo liệu cho anh là cụ Trương Gia Mô. Theo tư liệu do bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, tập hợp và được Báo Thanh Niên dẫn lại, cụ Mô đưa anh vào Sài Gòn. Cụ gửi anh ở tạm nhà ông Lê Văn Đạt ở xóm Cầu Rạch Bần, nay là khu vực đường Cô Bắc, Thành phố Hồ Chí Minh.\n\nVề sau, anh ở tạm tại các cơ sở của hội Liên Thành ở Sài Gòn, Chợ Lớn, học nghề và tìm việc trên những con tàu viễn dương (xem gian Sài Gòn – Bến Nhà Rồng). Suốt chặng đường từ Bình Khê, những người bạn của cha và những nhà Duy Tân đã lần lượt tiếp sức cho người thanh niên: cụ Trương Gia Mô ở Duồng, ông Nguyễn Quý Anh ở Phan Thiết, hội Liên Thành ở Sài Gòn. Ngày 5/6/1911, từ bến Nhà Rồng, anh xuống tàu Amiral Latouche-Tréville, bắt đầu hành trình ra đi tìm đường cứu nước. Con đường một mình về phương Nam đã dẫn anh ra biển lớn.","doc":11},{"loai":"anh","src":"textures/bang_w/G03_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Một mình đi về phương Nam”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Những chặng dừng chân trên hành trình phương Nam hôm nay đều được gìn giữ. Trên đất Bình Định xưa có di tích Huyện đường Bình Khê, nơi cụ Nguyễn Sinh Sắc làm tri huyện, và tượng đài Nguyễn Sinh Sắc – Nguyễn Tất Thành ghi dấu thời gian hai cha con ở vùng đất này. Ở làng Duồng, chùa Phước An là địa chỉ được người Bình Thuận tìm về. Ở Phan Thiết, Trường Dục Thanh bên dòng Cà Ty là di tích quốc gia, cạnh Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận.\n\nỞ cuối chặng đường của người cha, tại Cao Lãnh, Khu di tích mộ cụ Nguyễn Sinh Sắc là nơi các thế hệ người Việt về viếng. Nối các địa danh ấy trên bản đồ, người xem hôm nay có thể hình dung một chặng đường dài hàng trăm cây số dọc duyên hải miền Trung vào Nam. Người thanh niên hai mươi tuổi đã đi qua chặng đường ấy bằng ý chí của mình, và bằng tấm lòng của những người yêu nước mà anh gặp dọc đường.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Thanh Niên – Thầy Thành ở trường Dục Thanh – https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm","Znews – Tài liệu quý hiếm về cụ Nguyễn Sinh Sắc từ văn thư triều Nguyễn – https://znews.vn/tai-lieu-quy-hiem-ve-cu-nguyen-sinh-sac-tu-van-thu-trieu-nguyen-post996476.html","Trung tâm Lưu trữ quốc gia I – Châu bản triều Nguyễn (bản tấu của Bộ Lại năm Duy Tân thứ 3 và của Bộ Hình năm Duy Tân thứ 4)","Báo Lâm Đồng – Chùa Phước An, nơi Bác dừng chân thứ 2 ở Bình Thuận","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh"],"doc":[{"t":"Từ Bình Khê đến Phan Thiết: chặng đường phương Nam của người thanh niên hai mươi tuổi. Năm 1910, người cha vừa mất chức quan, còn người con trai không quay về Huế. Nguyễn Tất Thành một mình đi tiếp về phía Nam, qua những vùng đất lần đầu đặt chân tới, với vài mối quen biết của cha làm chỗ dựa. Ở làng biển Duồng, một ngôi chùa nhỏ và một nhà nho yêu nước đã mở cho anh cánh cửa vào Phan Thiết."},{"t":"Châu điểm của vua Duy Tân. Trong kho châu bản triều Nguyễn, tức những văn bản hành chính có bút phê của nhà vua, còn giữ một bản tấu của Bộ Lại đề ngày 11 tháng 4 năm Duy Tân thứ ba, tức năm 1909. Bản tấu xin bổ Phó bảng Nguyễn Sinh Huy làm tri huyện Bình Khê, tỉnh Bình Định, và được vua Duy Tân chấm châu điểm chuẩn y. Nguyễn Sinh Huy là tên cụ Nguyễn Sinh Sắc dùng trong quan trường. Sau mấy năm làm một chức quan nhỏ ở Bộ Lễ tại kinh đô, đây là lần đầu cụ ra trông coi một huyện. Giữa năm 1909, người con trai mười chín tuổi rời Trường Quốc Học Huế, theo cha vào nhiệm sở mới. Bình Khê là huyện nằm ở phía tây tỉnh Bình Định, nơi đồng bằng bắt đầu chuyển lên vùng đồi núi. Đây là quê hương của ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ, những người dựng nghiệp Tây Sơn cuối thế kỷ XVIII. Người thanh niên lớn lên trong những câu chuyện về các bậc anh hùng dân tộc nay được sống trên chính mảnh đất đã sinh ra người anh hùng áo vải Quang Trung."},{"t":"Tiếng Pháp ở Quy Nhơn. Theo các tư liệu về thời kỳ này, ở Bình Khê, Nguyễn Tất Thành thường được cha đưa đi thăm các sĩ phu trong vùng và các di tích Tây Sơn. Từ tháng 9/1909, cụ Phó bảng gửi con xuống Quy Nhơn, tỉnh lỵ ven biển của Bình Định, học tiếp ở trường tiểu học Pháp – Việt để trau dồi tiếng Pháp. Với người thanh niên đã sớm muốn hiểu thế giới bên ngoài, tiếng Pháp là một chiếc chìa khóa. Nó mở ra sách báo, tư tưởng của chính nước đang cai trị dân tộc mình, và mở đường cho những chuyến đi xa. Bình Định khi ấy vẫn chưa nguôi dư âm của phong trào chống sưu thuế năm 1908, khi nông dân nhiều tỉnh Trung Kỳ, trong đó có Bình Định, kéo lên phủ huyện đòi giảm sưu thuế và bị đàn áp. Người thanh niên từng xuống đường ở Huế năm ấy nay học tiếng Pháp giữa một vùng quê còn đầy vết thương. Nhưng chỉ vài tháng sau, một biến cố xảy ra ở huyện đường Bình Khê đã làm thay đổi tất cả."},{"t":"Vụ án ở huyện đường Bình Khê. Theo các tài liệu viết về cụ, ở Bình Khê, cụ Phó bảng nổi tiếng là vị quan thương người nghèo, nghiêm khắc với bọn cường hào ức hiếp dân. Chính sự nghiêm khắc ấy dẫn tới biến cố. Theo châu bản triều Nguyễn, một địa chủ cường hào trong huyện chống đối, không chịu nộp thuế. Quan tri huyện sai lính nọc ra đánh đòn để răn đe. Hơn hai tháng sau, người này ốm chết, và vợ hắn làm đơn kiện lên trên. Đầu năm 1910, cụ Nguyễn Sinh Sắc bị cách chức tri huyện, bị đưa về Huế chờ xét xử. Với một vị quan, đó là cú ngã nặng nề. Với gia đình, đó là sự đảo lộn: danh phận và chỗ dựa của người cha bỗng không còn. Người con trai khi ấy đang học ở Quy Nhơn. Chặng đường theo cha vào phương Nam, bắt đầu từ Huế chưa đầy một năm trước, khép lại giữa chừng. Từ đây, người thanh niên phải tự quyết định bước đi của mình."},{"t":"Bạn có biết? Vụ án ở Bình Khê được ghi trong châu bản triều Nguyễn, loại văn bản đang được lưu giữ tại Trung tâm Lưu trữ quốc gia I. Trong đó có bản tấu bổ nhiệm cụ làm tri huyện, đề năm Duy Tân thứ ba (1909), và bản tấu của Bộ Hình xử vụ án, đề năm Duy Tân thứ tư (1910)."},{"t":"Bản tấu của Bộ Hình. Vụ án được Bộ Hình ở kinh đô xem xét. Trong bản tấu đề ngày 15 tháng 8 năm Duy Tân thứ tư, tức năm 1910, Bộ Hình nhận định người kia chết vì bệnh sau hơn hai tháng, “chớ không phải bị đánh chết tức thì, tình có thể tha thứ”. Quan tri huyện bị xử giáng bốn cấp. Bản án ấy khép lại con đường làm quan của cụ Phó bảng. Sau biến cố ấy, cụ không trở lại chốn quan trường. Cụ vào Nam Kỳ, sống bằng nghề bốc thuốc, dạy học, đi nhiều nơi ở Nam Bộ, và mất năm 1929 tại Cao Lãnh, nay thuộc tỉnh Đồng Tháp. Còn người con trai, sau biến cố của cha, đã tự chọn cho mình một hướng đi khác hẳn. Anh không trở ra Huế, cũng không về làng Kim Liên, mà đi về phía những vùng đất anh chưa từng đặt chân tới."},{"t":"Ngã rẽ năm hai mươi tuổi. Người cha bị đưa về kinh, người con trai đứng trước một ngã rẽ. Trở ra Huế, anh có thể ở cạnh cha trong những ngày khó khăn. Về quê Nghệ An, anh có họ hàng, làng xóm. Nhưng Nguyễn Tất Thành chọn con đường thứ ba: một mình đi tiếp về phía Nam. Không có văn bản nào ghi lại lời anh giải thích quyết định này. Nhưng con đường anh đi nói lên nhiều điều. Từ Bình Định, anh không dừng lâu ở nơi nào, mà cứ xuôi dần về hướng Sài Gòn, thương cảng lớn nhất Nam Kỳ, nơi có những con tàu đi Pháp và đi khắp thế giới. Vài tháng sau, ở Sài Gòn, anh nói với một người bạn rằng mình muốn ra nước ngoài xem nước Pháp và các nước khác làm như thế nào, rồi trở về giúp đồng bào (xem gian Sài Gòn – Bến Nhà Rồng). Hành trang của anh khi rời Bình Định gồm vốn chữ Hán học từ nhỏ, chữ Quốc ngữ và tiếng Pháp học ở trường. Anh cũng đã rõ một lựa chọn: không đi theo con đường làm quan hay làm thông ngôn cho chính quyền bảo hộ."},{"t":"Qua Phan Rang, tới làng Duồng. Khoảng tháng 8/1910, Nguyễn Tất Thành rời Bình Định. Từ Bình Định vào phương Nam phải đi qua đất Phú Yên, Khánh Hòa. Rồi anh tới Phan Rang, tỉnh lỵ Ninh Thuận, vùng đất nắng gió, nơi có nhiều làng Chăm với những ngọn tháp cổ. Từ Phan Rang, anh đi tiếp về phía Nam, vượt qua ranh giới hai tỉnh để vào đất Bình Thuận. Theo tư liệu được Báo Thanh Niên dẫn lại, điểm dừng chân tiếp theo của anh là Duồng, một làng ven biển mà theo địa giới trước năm 2025 thuộc xã Chí Công, huyện Tuy Phong, tỉnh Bình Thuận. Tuy Phong là vùng cực bắc của Bình Thuận, khô hạn, nhiều gió cát, người dân sống chủ yếu nhờ biển. Người thanh niên hai mươi tuổi không tìm đến đây một cách tình cờ. Ở Duồng có một người bạn của gia đình, người sẽ giúp anh tìm được chỗ đứng ở Phan Thiết."},{"t":"Cụ Trương Gia Mô và ngôi chùa Phước An. Người ấy là cụ Trương Gia Mô, hiệu Cúc Nông, sinh năm 1866, một nhà nho yêu nước và là bạn thân của cụ Phó bảng Nguyễn Sinh Sắc. Cụ gắn bó với phong trào Duy Tân và từng bị bắt giam năm 1908, khi thực dân đàn áp phong trào chống sưu thuế ở Trung Kỳ. Gặp con trai của bạn giữa lúc gia đình bạn gặp nạn, cụ Mô ân cần đón nhận. Theo lời kể được Báo Thanh Niên ghi lại, cụ cho anh ban ngày ở chùa Phước An, ban đêm đưa về nghỉ tại nhà mình. Lời kể không cho biết người thanh niên ở Duồng bao lâu, cũng không nói vì sao cụ sắp xếp như vậy. Dù vậy, chi tiết nhỏ ấy cho thấy sự chu đáo của người bạn già dành cho con trai của bạn mình. Trong lúc người thanh niên chờ đợi ở làng biển, cụ Trương Gia Mô lên đường vào Phan Thiết để lo cho anh một công việc."},{"t":"Bạn có biết? Chùa Phước An ở làng Duồng, nơi Nguyễn Tất Thành được cụ Trương Gia Mô cho ở ban ngày năm 1910, nay được ghi nhận là một trong những nơi Bác Hồ từng dừng chân trên đất Bình Thuận."},{"t":"Cánh cửa Dục Thanh mở ra. Ở Phan Thiết, cụ Trương Gia Mô tìm gặp các nhà Duy Tân sáng lập hội Liên Thành, xin giúp đỡ người con trai của bạn mình. Người quyết định là ông Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông, một trong những người lập ra Trường Dục Thanh. Ông nhận lời để Nguyễn Tất Thành về dạy học ở trường. Với ngôi trường tư ở tỉnh lẻ, người thanh niên xứ Nghệ là một thầy giáo đáng quý. Anh thông chữ Hán, đọc được sách Pháp, viết thạo chữ Quốc ngữ, lại là con một vị Phó bảng có tiếng yêu nước. Còn với Nguyễn Tất Thành, lời nhận lời của ông Nguyễn Quý Anh mang lại nhiều hơn một công việc. Đó là một chỗ ở trong khuôn viên trường, một nơi để đọc sách, và một cộng đồng những người cùng chí hướng. Từ tháng 9/1910, học trò Dục Thanh có thêm một thầy giáo mới mà các em gọi là thầy Thành (xem chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp)."},{"t":"Rời Phan Thiết vào Sài Gòn. Chưa đầy nửa năm sau, tháng 2/1911, thầy Thành rời Dục Thanh. Một lần nữa, người lo liệu cho anh là cụ Trương Gia Mô. Theo tư liệu do bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, tập hợp và được Báo Thanh Niên dẫn lại, cụ Mô đưa anh vào Sài Gòn. Cụ gửi anh ở tạm nhà ông Lê Văn Đạt ở xóm Cầu Rạch Bần, nay là khu vực đường Cô Bắc, Thành phố Hồ Chí Minh. Về sau, anh ở tạm tại các cơ sở của hội Liên Thành ở Sài Gòn, Chợ Lớn, học nghề và tìm việc trên những con tàu viễn dương (xem gian Sài Gòn – Bến Nhà Rồng). Suốt chặng đường từ Bình Khê, những người bạn của cha và những nhà Duy Tân đã lần lượt tiếp sức cho người thanh niên: cụ Trương Gia Mô ở Duồng, ông Nguyễn Quý Anh ở Phan Thiết, hội Liên Thành ở Sài Gòn. Ngày 5/6/1911, từ bến Nhà Rồng, anh xuống tàu Amiral Latouche-Tréville, bắt đầu hành trình ra đi tìm đường cứu nước. Con đường một mình về phương Nam đã dẫn anh ra biển lớn."},{"t":"Dấu tích hôm nay. Những chặng dừng chân trên hành trình phương Nam hôm nay đều được gìn giữ. Trên đất Bình Định xưa có di tích Huyện đường Bình Khê, nơi cụ Nguyễn Sinh Sắc làm tri huyện, và tượng đài Nguyễn Sinh Sắc – Nguyễn Tất Thành ghi dấu thời gian hai cha con ở vùng đất này. Ở làng Duồng, chùa Phước An là địa chỉ được người Bình Thuận tìm về. Ở Phan Thiết, Trường Dục Thanh bên dòng Cà Ty là di tích quốc gia, cạnh Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Ở cuối chặng đường của người cha, tại Cao Lãnh, Khu di tích mộ cụ Nguyễn Sinh Sắc là nơi các thế hệ người Việt về viếng. Nối các địa danh ấy trên bản đồ, người xem hôm nay có thể hình dung một chặng đường dài hàng trăm cây số dọc duyên hải miền Trung vào Nam. Người thanh niên hai mươi tuổi đã đi qua chặng đường ấy bằng ý chí của mình, và bằng tấm lòng của những người yêu nước mà anh gặp dọc đường."}],"so_chu":2001},{"i":2,"tieu_de_bang":"Hội buôn nước mắm nuôi một ngôi trường","tieu_de":"Liên Thành: khi nghề nước mắm nuôi một ngôi trường yêu nước","sapo":"Năm 1906, ở Phan Thiết, sáu nhà nho làm một việc khiến người đương thời lấy làm lạ: họ lập hội đi buôn nước mắm. Đồng tiền từ những thùng nước mắm ấy nuôi một thư xã, một ngôi trường, và bốn năm sau mở cho người thanh niên Nguyễn Tất Thành một lớp học để đứng. Hội buôn ấy còn sống lâu hơn cả ngôi trường, qua gần bảy mươi năm thăng trầm của đất nước.","bia":{"src":"textures/bai/G03_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Khi nhà nho phải đi buôn","text":"Xã hội Việt Nam đầu thế kỷ XX vẫn xếp con người theo bậc thang cũ: sĩ, nông, công, thương. Người đi học đứng đầu, người buôn bán đứng cuối. Nhà nho sống bằng khoa cử, bằng việc dạy chữ hay làm quan. Ít ai nghĩ một người đọc sách thánh hiền lại tính chuyện lời lỗ, sổ sách. Trong khi đó, những mạch kinh tế lớn của xứ thuộc địa nằm trong tay người Pháp và thương nhân người Hoa, còn phần đông người Việt nghèo khó và không biết chữ.\n\nCác nhà Duy Tân nhìn thấy nghịch lý ấy. Theo một nghiên cứu về lịch sử công ty Liên Thành được Liên hiệp các Hội Khoa học và Kỹ thuật Việt Nam giới thiệu, hội buôn ra đời như phản ứng của lớp nhà nho trước sự bế tắc của lối học cũ. Muốn khai dân trí thì phải có tiền mở trường. Muốn chấn dân khí thì người Việt phải tự đứng được trên đôi chân mình. Muốn hậu dân sinh thì phải làm kinh tế. Ba vế của khẩu hiệu Duy Tân dẫn tới một kết luận giản dị mà táo bạo: nhà nho phải đi buôn. Chuyến đi của Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp tới Phan Thiết năm 1905 đã thổi bùng ý tưởng ấy (xem chuyên đề Phan Thiết – Trường Dục Thanh).","doc":1},{"loai":"anh","src":"textures/bang_w/G03_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hội buôn nước mắm nuôi một ngôi trường”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Sáu người sáng lập","text":"Tháng 3/1906, ở Phan Thiết, Liên Thành thương quán chính thức ra đời. Sáu người đứng tên sáng lập là Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng. Hai người đầu là con trai nhà thơ yêu nước Nguyễn Thông, người từ Nam Kỳ ra Bình Thuận khi đất Nam Kỳ rơi vào tay thực dân. Theo Báo Người Lao Động, Trần Lệ Chất khi ấy làm thư ký cho tòa công sứ Pháp, nghĩa là cả người trong bộ máy hành chính cũng góp sức với hội.\n\nHội không hoạt động lén lút. Theo nghiên cứu về lịch sử công ty, công sứ Pháp ở Phan Thiết khi ấy là Lucien Garnier có thái độ cởi mở với các nhà nho Duy Tân. Tại lễ khai trương Liên Thành, ông còn nói rõ công chức cũng có thể góp vốn vào các công ty. Nhờ vậy, Liên Thành có tư cách của một cơ sở buôn bán hợp pháp. Bên trong cái vỏ thương mại ấy, những người sáng lập theo đuổi một mục đích xa hơn: làm kinh tế để có tiền cho việc học và việc nước. Người trực tiếp điều hành công việc buôn bán buổi đầu là ông Nguyễn Trọng Lội.","doc":2},{"loai":"doan","tieu_de":"Thành sen giữa chốn thương trường","text":"Theo Báo Người Lao Động, tên Liên Thành có nghĩa là thành sen. Hoa sen từ lâu là biểu tượng của sự thanh khiết trong văn hóa Việt, như câu ca dao quen thuộc tả loài hoa gần bùn mà chẳng hôi tanh mùi bùn. Chọn cái tên ấy, những người sáng lập như muốn nói rằng họ buôn bán giữa chốn thương trường, dưới chế độ thuộc địa, nhưng vẫn giữ lòng trong sạch và chí hướng vì nước. Người đương thời còn gọi tổ chức này là hội Duy Tân.\n\nHội hoạt động theo lối góp vốn cổ phần, điều còn mới mẻ với người Việt thời ấy. Vốn được huy động từ các gia đình quan lại, sĩ phu trong vùng và cả từ thương nhân người Hoa. Ngoài sáu người sáng lập, Liên Thành còn thu hút nhiều cổ đông khác. Nhà nho đi buôn thì phải học lại từ đầu, và những người sáng lập đã không ngần ngại học hỏi chính những người đang nắm giữ thương trường. Nhờ sự hợp sức ấy, một hội buôn ra đời ở tỉnh lẻ đã sớm có chỗ đứng vững vàng, và nhanh chóng tích lũy được một số vốn lớn.","doc":3},{"loai":"ban_co_biet","text":"Theo Báo Người Lao Động, chỉ sau một năm hoạt động, vốn của Liên Thành đã lên tới khoảng 90.000 đồng, một con số rất lớn đối với một cơ sở kinh doanh của người Việt thời ấy.","nguon_ten":"Báo Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành","doc":4},{"loai":"doan","tieu_de":"Từ mẻ cá cơm đến thùng nước mắm","text":"Liên Thành chọn đúng thế mạnh của đất Phan Thiết. Vùng biển Bình Thuận nhiều cá, nghề đánh bắt và đội ghe thuyền khá phát triển, nghề làm nước mắm có truyền thống lâu đời. Theo lối làm truyền thống ở Phan Thiết, cá cơm tươi được trộn với muối hạt rồi cho vào những thùng gỗ lớn mà người địa phương gọi là thùng lều, ủ chượp trong khoảng một năm. Khi chượp chín, người thợ rút lấy nước mắm cốt, màu cánh gián, thơm và đậm.\n\nNghề này cần vốn lớn và sự kiên nhẫn. Phải mua cá theo mùa, mua muối, đóng thùng, có nhà thùng và nhân công, rồi chờ hàng tháng trời mới có sản phẩm để bán. Một hội buôn góp vốn của nhiều người có điều kiện làm những việc mà một gia đình khó kham nổi. Theo nghiên cứu về lịch sử công ty, trong giai đoạn đầu từ năm 1906 đến năm 1917, Liên Thành mở rộng hoạt động ra Phan Rí, Hội An. Theo Báo Người Lao Động, mạng lưới của hội dần vươn khắp miền Trung, miền Nam và sang cả Cao Miên, tức Campuchia ngày nay. Từ những thùng lều bên bờ biển Phan Thiết, nước mắm Liên Thành đi xa, và lợi nhuận quay về nuôi việc học.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_song_ca_ty.jpg","chu_thich":"Sông Cà Ty chảy qua Phan Thiết ra biển, ảnh chụp năm 2014. Nghề biển và nghề nước mắm của vùng đất này đã nuôi hội buôn Liên Thành và Trường Dục Thanh.","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Thư xã và ngôi trường","text":"Liên Thành không chỉ buôn nước mắm. Tháng 5/1906, chỉ hai tháng sau khi thương quán ra đời, hội lập Liên Thành thư xã để phổ biến sách báo mới, sách báo yêu nước. Thời ấy, các nhà Duy Tân khắp nơi truyền tay nhau những cuốn tân thư giới thiệu tư tưởng dân quyền, khoa học phương Tây và các cuộc canh tân ở Nhật Bản, Trung Quốc. Ở một thị xã nhỏ xa các trung tâm lớn, thư xã là cánh cửa để người Phan Thiết nhìn ra thế giới.\n\nNăm 1907, Trường Dục Thanh ra đời trên khu đất của gia đình cụ Nguyễn Thông, do ông Nguyễn Quý Anh trông coi. Theo nghiên cứu về lịch sử công ty, mọi chi phí của trường đều do Liên Thành chi trả. Như vậy, ba hoạt động gắn chặt với nhau: thương quán làm ra tiền, thư xã lo sách báo, nhà trường dạy chữ cho lớp trẻ. Mỗi thùng nước mắm bán được góp một phần vào việc học của học trò Dục Thanh. Nghiên cứu ấy coi Liên Thành là trường hợp điển hình cho bước chuyển mà các nhà nho Duy Tân thiết tha kêu gọi: từ nho sĩ trở thành những nhà tư sản dân tộc, vừa làm kinh tế vừa lo văn hóa, giáo dục.","doc":6},{"loai":"ban_co_biet","text":"Nhà nho đi buôn phải học nghề từ đầu. Theo nghiên cứu về lịch sử công ty, hai thương nhân người Hoa là Trương Thái Lợi và Lý Thoại Xuân đã chỉ cho ông Nguyễn Trọng Lội cách điều hành công ty, ghi chép sổ sách và các quy tắc kế toán.","nguon_ten":"VUSTA – Công ty Liên Thành (1906–1975): Từ hội Duy Tân đến doanh nghiệp hiện đại","doc":7},{"loai":"doan","tieu_de":"Hội buôn và người thầy giáo trẻ","text":"Mùa thu năm 1910, hơn bốn năm sau ngày Liên Thành ra đời, cụ Trương Gia Mô tìm đến những người sáng lập hội, xin giúp đỡ người con trai của bạn mình, cụ Phó bảng Nguyễn Sinh Sắc. Ông Nguyễn Quý Anh nhận lời để Nguyễn Tất Thành về dạy ở Dục Thanh (xem chuyên đề Một mình đi về phương Nam). Lớp học nơi thầy Thành đứng giảng, chỗ ở nội trú của thầy, những cuốn sách thầy đọc trong thư viện đều được duy trì nhờ đồng tiền của hội buôn nước mắm.\n\nMối quan hệ ấy không dừng lại ở Phan Thiết. Tháng 2/1911, khi vào Sài Gòn chuẩn bị cho chuyến đi xa, Nguyễn Tất Thành ở tạm tại các cơ sở của Liên Thành; căn nhà chi nhánh ở Chợ Lớn nay là di tích quốc gia (xem gian Sài Gòn – Bến Nhà Rồng). Ở Phan Thiết, người thanh niên được tận mắt thấy một cách yêu nước không ồn ào mà bền bỉ: làm ra đồng tiền, dựng ngôi trường, dạy từng con chữ. Khác với những lời hiệu triệu trên giấy, đó là lòng yêu nước được đo bằng thùng nước mắm, bằng sổ sách, bằng từng buổi lên lớp.","doc":8},{"loai":"anh","src":"textures/bang_w/G03_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hội buôn nước mắm nuôi một ngôi trường”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Qua những thăng trầm","text":"Những năm sau đó, số phận của hội buôn gắn với thăng trầm của phong trào yêu nước. Trường Dục Thanh chỉ hoạt động đến năm 1912 thì đóng cửa. Theo nghiên cứu về lịch sử công ty, ông Nguyễn Trọng Lội, người điều hành buổi đầu, mất năm 1911. Nhưng thương quán vẫn đứng vững. Giai đoạn 1917 – 1937 đánh dấu bước phát triển mới khi Liên Thành vào Chợ Lớn, với tham vọng mở rộng ra toàn cõi Đông Dương.\n\nTheo Báo Người Lao Động, các chi nhánh của Liên Thành về sau vẫn là nơi hội họp của những người yêu nước, và hội còn hỗ trợ tài chính cho các hoạt động chính trị. Năm 1926, khi Phan Châu Trinh qua đời tại Sài Gòn, Liên Thành tổ chức lễ tưởng niệm người đã khơi nguồn cảm hứng cho sự ra đời của mình. Doanh nghiệp đi qua những biến động dữ dội của đất nước, hoạt động cho đến sau ngày miền Nam giải phóng năm 1975 rồi mới chuyển đổi hình thức. Khoảng bảy mươi năm của một hội buôn nước mắm vì thế cũng là một lát cắt của lịch sử dân tộc.","doc":9},{"loai":"doan","tieu_de":"Một mô hình hiếm hoi","text":"Đầu thế kỷ XX, theo lời kêu gọi chấn hưng thực nghiệp của phong trào Duy Tân, nhiều hội buôn, công ty của người Việt đã ra đời, từ Quảng Nam đến Hà Nội và Nam Kỳ. Nhưng sau cuộc đàn áp năm 1908, không ít cơ sở như thế bị chính quyền thực dân theo dõi, khó khăn rồi tan rã. Liên Thành là một trường hợp đặc biệt: vừa giữ được tư cách một doanh nghiệp hợp pháp, vừa bền bỉ theo đuổi mục đích ban đầu, và còn tồn tại qua nhiều thập kỷ.\n\nCó thể thấy một vài lý do từ chính câu chuyện của hội. Những người sáng lập chọn một mặt hàng gắn với thế mạnh của địa phương, nên có nguồn thu ổn định. Họ học cách quản lý, ghi sổ sách bài bản. Họ tận dụng sự cởi mở của viên công sứ sở tại để có chỗ đứng hợp pháp. Và họ biết gắn việc buôn bán với những việc làm có ích cho cộng đồng như mở thư xã, mở trường. Hơn một thế kỷ sau, cách làm ấy vẫn là một bài học về kinh doanh gắn với trách nhiệm xã hội.","doc":10},{"loai":"anh","src":"textures/bang_w/G03_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hội buôn nước mắm nuôi một ngôi trường”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn một thế kỷ sau, dấu vết của Liên Thành vẫn còn ở nhiều nơi. Tại Phan Thiết, khu di tích Trường Dục Thanh bên sông Cà Ty lưu giữ ký ức về ngôi trường mà hội buôn đã nuôi dưỡng. Tại Thành phố Hồ Chí Minh, căn nhà chi nhánh Liên Thành ở số 5 đường Châu Văn Liêm, nơi Nguyễn Tất Thành ở tạm năm 1911, được công nhận là di tích lịch sử cấp quốc gia. Thương hiệu nước mắm Liên Thành vẫn còn đến ngày nay.\n\nNghề làm nước mắm ở Phan Thiết cũng vẫn sống. Những thùng lều bằng gỗ vẫn ủ chượp trong các nhà thùng, và nước mắm Phan Thiết được bảo hộ chỉ dẫn địa lý, trở thành niềm tự hào của vùng đất. Mỗi lần nhắc tới thứ nước chấm quen thuộc ấy, người ta có thể nhớ rằng đã có thời nó nuôi cả một ngôi trường yêu nước, nơi người thanh niên Nguyễn Tất Thành đứng lớp trước khi ra đi tìm đường cứu nước.","doc":11}],"nguon":["Báo Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành – https://tuoitre.vn/nld/hoi-nhap/bai-1-phong-trao-duy-tan-o-binh-thuan-da-khai-sinh-ra-lien-thanh-20090522104457589.htm","VUSTA – Công ty Liên Thành (1906–1975): Từ hội Duy Tân đến doanh nghiệp hiện đại – https://vusta.vn/cong-ty-lien-thanh-1906-1975-tu-hoi-duy-tan-den-doanh-nghiep-hien-dai-p77095.html","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","Thanh Niên – Thầy Thành ở trường Dục Thanh – https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm","VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia"],"doc":[{"t":"Liên Thành: khi nghề nước mắm nuôi một ngôi trường yêu nước. Năm 1906, ở Phan Thiết, sáu nhà nho làm một việc khiến người đương thời lấy làm lạ: họ lập hội đi buôn nước mắm. Đồng tiền từ những thùng nước mắm ấy nuôi một thư xã, một ngôi trường, và bốn năm sau mở cho người thanh niên Nguyễn Tất Thành một lớp học để đứng. Hội buôn ấy còn sống lâu hơn cả ngôi trường, qua gần bảy mươi năm thăng trầm của đất nước."},{"t":"Khi nhà nho phải đi buôn. Xã hội Việt Nam đầu thế kỷ XX vẫn xếp con người theo bậc thang cũ: sĩ, nông, công, thương. Người đi học đứng đầu, người buôn bán đứng cuối. Nhà nho sống bằng khoa cử, bằng việc dạy chữ hay làm quan. Ít ai nghĩ một người đọc sách thánh hiền lại tính chuyện lời lỗ, sổ sách. Trong khi đó, những mạch kinh tế lớn của xứ thuộc địa nằm trong tay người Pháp và thương nhân người Hoa, còn phần đông người Việt nghèo khó và không biết chữ. Các nhà Duy Tân nhìn thấy nghịch lý ấy. Theo một nghiên cứu về lịch sử công ty Liên Thành được Liên hiệp các Hội Khoa học và Kỹ thuật Việt Nam giới thiệu, hội buôn ra đời như phản ứng của lớp nhà nho trước sự bế tắc của lối học cũ. Muốn khai dân trí thì phải có tiền mở trường. Muốn chấn dân khí thì người Việt phải tự đứng được trên đôi chân mình. Muốn hậu dân sinh thì phải làm kinh tế. Ba vế của khẩu hiệu Duy Tân dẫn tới một kết luận giản dị mà táo bạo: nhà nho phải đi buôn. Chuyến đi của Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp tới Phan Thiết năm 1905 đã thổi bùng ý tưởng ấy (xem chuyên đề Phan Thiết – Trường Dục Thanh)."},{"t":"Sáu người sáng lập. Tháng 3/1906, ở Phan Thiết, Liên Thành thương quán chính thức ra đời. Sáu người đứng tên sáng lập là Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng. Hai người đầu là con trai nhà thơ yêu nước Nguyễn Thông, người từ Nam Kỳ ra Bình Thuận khi đất Nam Kỳ rơi vào tay thực dân. Theo Báo Người Lao Động, Trần Lệ Chất khi ấy làm thư ký cho tòa công sứ Pháp, nghĩa là cả người trong bộ máy hành chính cũng góp sức với hội. Hội không hoạt động lén lút. Theo nghiên cứu về lịch sử công ty, công sứ Pháp ở Phan Thiết khi ấy là Lucien Garnier có thái độ cởi mở với các nhà nho Duy Tân. Tại lễ khai trương Liên Thành, ông còn nói rõ công chức cũng có thể góp vốn vào các công ty. Nhờ vậy, Liên Thành có tư cách của một cơ sở buôn bán hợp pháp. Bên trong cái vỏ thương mại ấy, những người sáng lập theo đuổi một mục đích xa hơn: làm kinh tế để có tiền cho việc học và việc nước. Người trực tiếp điều hành công việc buôn bán buổi đầu là ông Nguyễn Trọng Lội."},{"t":"Thành sen giữa chốn thương trường. Theo Báo Người Lao Động, tên Liên Thành có nghĩa là thành sen. Hoa sen từ lâu là biểu tượng của sự thanh khiết trong văn hóa Việt, như câu ca dao quen thuộc tả loài hoa gần bùn mà chẳng hôi tanh mùi bùn. Chọn cái tên ấy, những người sáng lập như muốn nói rằng họ buôn bán giữa chốn thương trường, dưới chế độ thuộc địa, nhưng vẫn giữ lòng trong sạch và chí hướng vì nước. Người đương thời còn gọi tổ chức này là hội Duy Tân. Hội hoạt động theo lối góp vốn cổ phần, điều còn mới mẻ với người Việt thời ấy. Vốn được huy động từ các gia đình quan lại, sĩ phu trong vùng và cả từ thương nhân người Hoa. Ngoài sáu người sáng lập, Liên Thành còn thu hút nhiều cổ đông khác. Nhà nho đi buôn thì phải học lại từ đầu, và những người sáng lập đã không ngần ngại học hỏi chính những người đang nắm giữ thương trường. Nhờ sự hợp sức ấy, một hội buôn ra đời ở tỉnh lẻ đã sớm có chỗ đứng vững vàng, và nhanh chóng tích lũy được một số vốn lớn."},{"t":"Bạn có biết? Theo Báo Người Lao Động, chỉ sau một năm hoạt động, vốn của Liên Thành đã lên tới khoảng 90.000 đồng, một con số rất lớn đối với một cơ sở kinh doanh của người Việt thời ấy."},{"t":"Từ mẻ cá cơm đến thùng nước mắm. Liên Thành chọn đúng thế mạnh của đất Phan Thiết. Vùng biển Bình Thuận nhiều cá, nghề đánh bắt và đội ghe thuyền khá phát triển, nghề làm nước mắm có truyền thống lâu đời. Theo lối làm truyền thống ở Phan Thiết, cá cơm tươi được trộn với muối hạt rồi cho vào những thùng gỗ lớn mà người địa phương gọi là thùng lều, ủ chượp trong khoảng một năm. Khi chượp chín, người thợ rút lấy nước mắm cốt, màu cánh gián, thơm và đậm. Nghề này cần vốn lớn và sự kiên nhẫn. Phải mua cá theo mùa, mua muối, đóng thùng, có nhà thùng và nhân công, rồi chờ hàng tháng trời mới có sản phẩm để bán. Một hội buôn góp vốn của nhiều người có điều kiện làm những việc mà một gia đình khó kham nổi. Theo nghiên cứu về lịch sử công ty, trong giai đoạn đầu từ năm 1906 đến năm 1917, Liên Thành mở rộng hoạt động ra Phan Rí, Hội An. Theo Báo Người Lao Động, mạng lưới của hội dần vươn khắp miền Trung, miền Nam và sang cả Cao Miên, tức Campuchia ngày nay. Từ những thùng lều bên bờ biển Phan Thiết, nước mắm Liên Thành đi xa, và lợi nhuận quay về nuôi việc học."},{"t":"Thư xã và ngôi trường. Liên Thành không chỉ buôn nước mắm. Tháng 5/1906, chỉ hai tháng sau khi thương quán ra đời, hội lập Liên Thành thư xã để phổ biến sách báo mới, sách báo yêu nước. Thời ấy, các nhà Duy Tân khắp nơi truyền tay nhau những cuốn tân thư giới thiệu tư tưởng dân quyền, khoa học phương Tây và các cuộc canh tân ở Nhật Bản, Trung Quốc. Ở một thị xã nhỏ xa các trung tâm lớn, thư xã là cánh cửa để người Phan Thiết nhìn ra thế giới. Năm 1907, Trường Dục Thanh ra đời trên khu đất của gia đình cụ Nguyễn Thông, do ông Nguyễn Quý Anh trông coi. Theo nghiên cứu về lịch sử công ty, mọi chi phí của trường đều do Liên Thành chi trả. Như vậy, ba hoạt động gắn chặt với nhau: thương quán làm ra tiền, thư xã lo sách báo, nhà trường dạy chữ cho lớp trẻ. Mỗi thùng nước mắm bán được góp một phần vào việc học của học trò Dục Thanh. Nghiên cứu ấy coi Liên Thành là trường hợp điển hình cho bước chuyển mà các nhà nho Duy Tân thiết tha kêu gọi: từ nho sĩ trở thành những nhà tư sản dân tộc, vừa làm kinh tế vừa lo văn hóa, giáo dục."},{"t":"Bạn có biết? Nhà nho đi buôn phải học nghề từ đầu. Theo nghiên cứu về lịch sử công ty, hai thương nhân người Hoa là Trương Thái Lợi và Lý Thoại Xuân đã chỉ cho ông Nguyễn Trọng Lội cách điều hành công ty, ghi chép sổ sách và các quy tắc kế toán."},{"t":"Hội buôn và người thầy giáo trẻ. Mùa thu năm 1910, hơn bốn năm sau ngày Liên Thành ra đời, cụ Trương Gia Mô tìm đến những người sáng lập hội, xin giúp đỡ người con trai của bạn mình, cụ Phó bảng Nguyễn Sinh Sắc. Ông Nguyễn Quý Anh nhận lời để Nguyễn Tất Thành về dạy ở Dục Thanh (xem chuyên đề Một mình đi về phương Nam). Lớp học nơi thầy Thành đứng giảng, chỗ ở nội trú của thầy, những cuốn sách thầy đọc trong thư viện đều được duy trì nhờ đồng tiền của hội buôn nước mắm. Mối quan hệ ấy không dừng lại ở Phan Thiết. Tháng 2/1911, khi vào Sài Gòn chuẩn bị cho chuyến đi xa, Nguyễn Tất Thành ở tạm tại các cơ sở của Liên Thành; căn nhà chi nhánh ở Chợ Lớn nay là di tích quốc gia (xem gian Sài Gòn – Bến Nhà Rồng). Ở Phan Thiết, người thanh niên được tận mắt thấy một cách yêu nước không ồn ào mà bền bỉ: làm ra đồng tiền, dựng ngôi trường, dạy từng con chữ. Khác với những lời hiệu triệu trên giấy, đó là lòng yêu nước được đo bằng thùng nước mắm, bằng sổ sách, bằng từng buổi lên lớp."},{"t":"Qua những thăng trầm. Những năm sau đó, số phận của hội buôn gắn với thăng trầm của phong trào yêu nước. Trường Dục Thanh chỉ hoạt động đến năm 1912 thì đóng cửa. Theo nghiên cứu về lịch sử công ty, ông Nguyễn Trọng Lội, người điều hành buổi đầu, mất năm 1911. Nhưng thương quán vẫn đứng vững. Giai đoạn 1917 – 1937 đánh dấu bước phát triển mới khi Liên Thành vào Chợ Lớn, với tham vọng mở rộng ra toàn cõi Đông Dương. Theo Báo Người Lao Động, các chi nhánh của Liên Thành về sau vẫn là nơi hội họp của những người yêu nước, và hội còn hỗ trợ tài chính cho các hoạt động chính trị. Năm 1926, khi Phan Châu Trinh qua đời tại Sài Gòn, Liên Thành tổ chức lễ tưởng niệm người đã khơi nguồn cảm hứng cho sự ra đời của mình. Doanh nghiệp đi qua những biến động dữ dội của đất nước, hoạt động cho đến sau ngày miền Nam giải phóng năm 1975 rồi mới chuyển đổi hình thức. Khoảng bảy mươi năm của một hội buôn nước mắm vì thế cũng là một lát cắt của lịch sử dân tộc."},{"t":"Một mô hình hiếm hoi. Đầu thế kỷ XX, theo lời kêu gọi chấn hưng thực nghiệp của phong trào Duy Tân, nhiều hội buôn, công ty của người Việt đã ra đời, từ Quảng Nam đến Hà Nội và Nam Kỳ. Nhưng sau cuộc đàn áp năm 1908, không ít cơ sở như thế bị chính quyền thực dân theo dõi, khó khăn rồi tan rã. Liên Thành là một trường hợp đặc biệt: vừa giữ được tư cách một doanh nghiệp hợp pháp, vừa bền bỉ theo đuổi mục đích ban đầu, và còn tồn tại qua nhiều thập kỷ. Có thể thấy một vài lý do từ chính câu chuyện của hội. Những người sáng lập chọn một mặt hàng gắn với thế mạnh của địa phương, nên có nguồn thu ổn định. Họ học cách quản lý, ghi sổ sách bài bản. Họ tận dụng sự cởi mở của viên công sứ sở tại để có chỗ đứng hợp pháp. Và họ biết gắn việc buôn bán với những việc làm có ích cho cộng đồng như mở thư xã, mở trường. Hơn một thế kỷ sau, cách làm ấy vẫn là một bài học về kinh doanh gắn với trách nhiệm xã hội."},{"t":"Dấu tích hôm nay. Hơn một thế kỷ sau, dấu vết của Liên Thành vẫn còn ở nhiều nơi. Tại Phan Thiết, khu di tích Trường Dục Thanh bên sông Cà Ty lưu giữ ký ức về ngôi trường mà hội buôn đã nuôi dưỡng. Tại Thành phố Hồ Chí Minh, căn nhà chi nhánh Liên Thành ở số 5 đường Châu Văn Liêm, nơi Nguyễn Tất Thành ở tạm năm 1911, được công nhận là di tích lịch sử cấp quốc gia. Thương hiệu nước mắm Liên Thành vẫn còn đến ngày nay. Nghề làm nước mắm ở Phan Thiết cũng vẫn sống. Những thùng lều bằng gỗ vẫn ủ chượp trong các nhà thùng, và nước mắm Phan Thiết được bảo hộ chỉ dẫn địa lý, trở thành niềm tự hào của vùng đất. Mỗi lần nhắc tới thứ nước chấm quen thuộc ấy, người ta có thể nhớ rằng đã có thời nó nuôi cả một ngôi trường yêu nước, nơi người thanh niên Nguyễn Tất Thành đứng lớp trước khi ra đi tìm đường cứu nước."}],"so_chu":2053},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Ngọa Du Sào đến bến Nhà Rồng: dòng thời gian của Trường Dục Thanh","sapo":"Câu chuyện Dục Thanh bắt đầu từ trước khi thầy Thành ra đời, và đến nay vẫn chưa khép lại. Ba mươi mốt mốc dưới đây nối lịch sử một mảnh vườn, một hội buôn và một ngôi trường với hành trình của người thanh niên Nguyễn Tất Thành. Đọc chúng theo thứ tự, ta sẽ thấy vì sao một thị xã nhỏ ven biển lại trở thành chặng dừng chân cuối cùng của Người trên đất Việt trước chuyến đi xa.","bia":{"src":"textures/bai/G03_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai dòng thời gian gặp nhau","text":"Bảng mốc thời gian này đặt cạnh nhau hai câu chuyện. Câu chuyện thứ nhất là của một mảnh đất và một ngôi trường: bắt đầu từ khi nhà thơ Nguyễn Thông dựng nhà bên sông Cà Ty, qua hội buôn Liên Thành, đến Trường Dục Thanh. Câu chuyện thứ hai là của một người thanh niên: rời Huế năm 1909, qua Bình Định, Phan Rang, làng Duồng rồi tới Phan Thiết vào mùa thu năm 1910.\n\nHai dòng ấy gặp nhau trong chưa đầy nửa năm, từ tháng 9/1910 đến tháng 2/1911. Sau đó, mỗi dòng đi tiếp con đường riêng. Người thầy giáo trẻ vào Sài Gòn, xuống tàu ra đi, rồi trở thành Nguyễn Ái Quốc, Hồ Chí Minh. Ngôi trường khép cửa, lặng lẽ qua gần bảy mươi năm, rồi được dựng lại thành di tích lưu giữ ký ức về Người. Bảng dưới đây xếp các mốc của cả hai dòng theo đúng trình tự thời gian.","doc":1},{"loai":"moc","items":[["1827","Nhà thơ, nhà yêu nước Nguyễn Thông ra đời ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An"],["1877","Nguyễn Thông được triều đình cử về Bình Thuận lo việc khai hoang vùng La Ngư, Ba Dầu"],["1880","Nguyễn Thông dựng ngôi nhà nhỏ Ngọa Du Sào bên một con rạch của sông Cà Ty, thuộc làng Thành Đức, Phan Thiết"],["1884","Nguyễn Thông qua đời; khu vườn ven sông và tủ sách được con cháu gìn giữ"],["19/5/1890","Nguyễn Sinh Cung, sau này là Nguyễn Tất Thành, chào đời tại làng Hoàng Trù, huyện Nam Đàn, tỉnh Nghệ An"],["20/10/1898","Vua Thành Thái ra đạo dụ lập thị xã Phan Thiết, tỉnh lỵ của Bình Thuận"],["1905","Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp đi vào các tỉnh phía Nam Trung Kỳ cổ động Duy Tân, gặp gỡ các nhà nho Phan Thiết"],["3/1906","Sáu nhà nho yêu nước lập Liên Thành thương quán, làm nước mắm để có vốn cho việc học và việc nước"],["5/1906","Liên Thành thư xã ra đời, phổ biến sách báo mới, sách báo yêu nước"],["1906","Nhà Ngư được dựng trong khuôn viên nhà họ Nguyễn để chứa ngư cụ; về sau là chỗ ở nội trú của thầy trò Dục Thanh"],["1907","Trường Dục Thanh ra đời do ông Nguyễn Quý Anh trông coi, mọi chi phí do Liên Thành đài thọ; có tài liệu ghi năm 1908"],["1908","Phong trào chống sưu thuế ở Trung Kỳ bị đàn áp; nhiều nhà Duy Tân bị bắt, trong đó có cụ Trương Gia Mô"],["11/4 năm Duy Tân thứ 3 (1909)","Bộ Lại dâng tấu bổ nhiệm Phó bảng Nguyễn Sinh Huy, tức cụ Nguyễn Sinh Sắc, làm tri huyện Bình Khê; vua Duy Tân chấm châu điểm chuẩn y"],["giữa 1909","Nguyễn Tất Thành rời Trường Quốc Học Huế, theo cha vào Bình Khê, tỉnh Bình Định"],["9/1909","Nguyễn Tất Thành xuống Quy Nhơn học tiếp ở trường tiểu học Pháp – Việt, trau dồi tiếng Pháp"],["đầu 1910","Cụ Nguyễn Sinh Sắc bị cách chức tri huyện Bình Khê, bị đưa về Huế chờ xét xử"],["khoảng 8/1910","Nguyễn Tất Thành rời Bình Định, qua Phan Rang tới làng Duồng; cụ Trương Gia Mô cho ở chùa Phước An ban ngày, đêm về nhà cụ"],["9/1910","Được ông Nguyễn Quý Anh nhận lời, Nguyễn Tất Thành bắt đầu dạy lớp nhì ở Trường Dục Thanh: chữ Quốc ngữ, chữ Hán, kiêm môn thể dục"],["15/8 năm Duy Tân thứ 4 (1910)","Bộ Hình dâng bản tấu kết luận vụ án Bình Khê, xử giáng cụ Nguyễn Sinh Sắc bốn cấp; cụ rời hẳn chốn quan trường"],["18/9/1910","Tết Trung thu năm Canh Tuất; học trò cũ nhớ thầy Thành đã ăn Tết này cùng thầy trò Dục Thanh"],["30/1/1911","Tết Nguyên đán Tân Hợi; thầy Thành vẫn ở Dục Thanh, mốc để các nhà nghiên cứu xác định thời gian thầy dạy học"],["2/1911","Thầy Thành rời Dục Thanh; cụ Trương Gia Mô đưa vào Sài Gòn, gửi ở tạm nhà ông Lê Văn Đạt, xóm Cầu Rạch Bần"],["5/6/1911","Với tên Văn Ba, Nguyễn Tất Thành làm phụ bếp trên tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ra đi tìm đường cứu nước"],["1912","Trường Dục Thanh đóng cửa sau khoảng năm năm hoạt động"],["1929","Cụ Nguyễn Sinh Sắc mất tại Cao Lãnh; cũng năm này cụ Trương Gia Mô qua đời"],["1978","Con cháu cụ Nguyễn Thông giao khu đất cho Nhà nước quản lý"],["11/1978 – 12/1980","Trùng tu, phục dựng lớp học, nhà Ngư, Ngọa Du Sào theo dáng xưa, dựa vào di tích gốc cùng lời kể và bản vẽ của bốn học trò cũ"],["19/5/1983","Khởi công nhà trưng bày về Chủ tịch Hồ Chí Minh ngay đối diện Trường Dục Thanh"],["19/5/1986","Khánh thành công trình nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh; về sau là Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận"],["12/12/1986","Bộ Văn hóa – Thông tin xếp hạng Trường Dục Thanh là di tích lịch sử – văn hóa cấp quốc gia"],["1/7/2025","Sau khi sắp xếp địa giới hành chính, khu di tích ở số 39 Trưng Nhị thuộc phường Phan Thiết, tỉnh Lâm Đồng"]],"doc":2},{"loai":"doan","tieu_de":"Trước khi có ngôi trường","text":"Các mốc đầu tiên đưa người xem về cuối thế kỷ XIX. Nguyễn Thông, sinh năm 1827 ở phủ Tân An thuộc Gia Định cũ, là một nhà thơ, nhà yêu nước Nam Kỳ. Khi thực dân Pháp chiếm dần Nam Kỳ, ông không chịu sống dưới ách cai trị của giặc. Năm 1877, ông được triều đình cử về Bình Thuận lo việc khai hoang. Năm 1880, bên một con rạch nhỏ chảy từ sông Cà Ty vào làng Thành Đức, ông dựng ngôi nhà nhỏ Ngọa Du Sào. Ông mất năm 1884, để lại cho con cháu mảnh vườn ven sông và một tủ sách.\n\nMười bốn năm sau, ngày 20/10/1898, vua Thành Thái ra đạo dụ lập thị xã Phan Thiết. Mảnh vườn của họ Nguyễn giờ nằm trong lòng một đô thị đang hình thành. Những mốc này cho thấy Dục Thanh không mọc lên trên đất trống. Nó được đặt trên nền của một gia đình có truyền thống yêu nước và học vấn, giữa một thị xã đang lớn lên nhờ biển.","doc":3},{"loai":"anh","src":"textures/bang_w/G03_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ba năm dựng nghiệp, 1905 – 1907","text":"Nhịp của các mốc dồn dập hơn ở đầu thế kỷ XX. Năm 1905, chuyến đi vào phương Nam của Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp đem tư tưởng Duy Tân tới Phan Thiết. Tháng 3/1906, hội buôn Liên Thành ra đời. Tháng 5/1906, Liên Thành thư xã mở cửa. Cũng năm 1906, trong khuôn viên nhà họ Nguyễn, nhà Ngư được dựng để chứa ngư cụ; về sau nó thành chỗ ở nội trú của thầy trò. Năm 1907, Trường Dục Thanh ra đời.\n\nChỉ trong khoảng hai năm, từ một ý tưởng, các nhà Duy Tân Phan Thiết đã có đủ ba trụ cột: tiền, sách và trường. Thứ tự các mốc cũng cho thấy cách làm của họ: lo nguồn tài chính trước, rồi mới mở trường. Về năm thành lập trường, tài liệu chưa hoàn toàn thống nhất. Phần lớn ghi năm 1907, một số ghi năm 1908. Bảng mốc ghi theo năm 1907 và chú thích cách ghi còn lại.","doc":4},{"loai":"ban_co_biet","text":"Nhà trưng bày về Chủ tịch Hồ Chí Minh bên Trường Dục Thanh khởi công ngày 19/5/1983 và khánh thành ngày 19/5/1986: cả hai mốc đều được chọn đúng vào Ngày sinh của Bác.","nguon_ten":"Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận; Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","doc":5},{"loai":"doan","tieu_de":"Năm 1908 và những đám mây","text":"Mốc năm 1908 ghi lại một biến cố lớn. Phong trào chống sưu thuế bùng lên ở các tỉnh Trung Kỳ và bị thực dân đàn áp. Nhiều nhà Duy Tân bị bắt, bị đày, có người bị xử tử. Cụ Trương Gia Mô, người hai năm sau sẽ đưa Nguyễn Tất Thành tới Phan Thiết, cũng bị bắt giam vì liên quan đến phong trào.\n\nTrong bầu không khí ấy, Trường Dục Thanh vẫn tiếp tục mở cửa. Liên Thành vẫn buôn bán như một cơ sở kinh doanh hợp pháp, và nhờ vậy nhà trường có chỗ dựa. Chính vì ngôi trường còn đứng vững nên hai năm sau, người thanh niên Nguyễn Tất Thành mới có một lớp học để đứng. Đặt các mốc cạnh nhau, người xem thấy một điều đáng chú ý: ở nhiều nơi, phong trào Duy Tân bị dập tắt sau năm 1908; ở Phan Thiết, nó vẫn lặng lẽ tồn tại trong hình thức một hội buôn và một trường tư.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_gieng_truong_duc_thanh.jpg","chu_thich":"Chiếc giếng gạch trong sân Trường Dục Thanh, một trong số ít chứng tích còn lại từ thời thầy Thành dạy học, trước đợt phục dựng những năm 1978 – 1980.","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hai năm dồn dập","text":"Dòng thời gian của Nguyễn Tất Thành dày đặc nhất trong những năm 1909 – 1911. Bản tấu bổ nhiệm cụ Nguyễn Sinh Huy làm tri huyện Bình Khê đề ngày 11 tháng 4 năm Duy Tân thứ ba, tức năm 1909. Giữa năm ấy, người con trai theo cha vào Bình Định; từ tháng 9 học tiếng Pháp ở Quy Nhơn. Khoảng tháng 8/1910, người con một mình đi tiếp về phương Nam. Tháng 2/1911, anh vào Sài Gòn. Ngày 5/6/1911, anh xuống tàu ra đi.\n\nNhư vậy, từ khi rời Huế đến ngày rời Tổ quốc chỉ khoảng hai năm. Riêng từ lúc rời Dục Thanh đến ngày xuống tàu ở bến Nhà Rồng là khoảng bốn tháng. Những con số ấy cho thấy Phan Thiết là chặng dừng chân dài cuối cùng của Người trên đất Việt trước chuyến đi. Chúng cũng cho thấy một quyết tâm đã chín: người thanh niên không lưu lại lâu ở đâu, mỗi bước chân đều hướng ra biển lớn.","doc":7},{"loai":"doan","tieu_de":"Vì sao có những mốc ghi “khoảng”","text":"Người xem sẽ thấy nhiều mốc trong bảng được ghi là khoảng, giữa năm hay đầu năm. Đó không phải sự tùy tiện, mà là sự thận trọng cần có với tư liệu lịch sử. Những gì ta biết về chặng Phan Thiết đến từ ba nguồn chính: văn bản hành chính như châu bản triều Nguyễn, các công trình biên niên do cơ quan nghiên cứu biên soạn, và lời kể của những người từng gặp Người.\n\nMỗi nguồn có cách ghi ngày riêng. Châu bản ghi theo niên hiệu nhà vua, như ngày 15 tháng 8 năm Duy Tân thứ tư, khi Bộ Hình dâng bản tấu xử vụ án Bình Khê. Còn thời gian thầy Thành ở Dục Thanh được bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, xác định qua ký ức của học trò cũ. Các cụ nhớ thầy đã ăn Tết Trung thu năm 1910 và Tết Nguyên đán năm 1911 ở trường. Từ hai cái Tết ấy, các nhà nghiên cứu ghi mốc từ tháng 9/1910 đến tháng 2/1911.","doc":8},{"loai":"anh","src":"textures/bang_w/G03_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Sau khi thầy đi","text":"Các mốc sau năm 1911 cho thấy số phận khác nhau của những con người và nơi chốn trong câu chuyện. Trường Dục Thanh hoạt động thêm một thời gian rồi đóng cửa vào năm 1912; cả đời trường chỉ khoảng năm năm. Hội buôn Liên Thành thì trụ vững, mở rộng vào Chợ Lớn và tồn tại đến sau năm 1975. Năm 1929, cụ Nguyễn Sinh Sắc mất ở Cao Lãnh; cũng năm ấy, cụ Trương Gia Mô qua đời. Hai bậc cha chú đã tiếp sức cho chặng đường phương Nam của người thanh niên đều không kịp thấy ngày Người trở về Tổ quốc năm 1941.\n\nTrong khi đó, khu vườn nhà họ Nguyễn bên sông Cà Ty vẫn do con cháu cụ Nguyễn Thông gìn giữ. Lớp học, nhà Ngư dần xuống cấp rồi không còn. Đến những năm sau 1975, trong khuôn viên chỉ còn Ngọa Du Sào, nhà thờ họ, cây khế và chiếc giếng. Ký ức về ngôi trường và người thầy giáo trẻ khi ấy chủ yếu nằm trong trí nhớ của những học trò cũ đã cao tuổi.","doc":9},{"loai":"anh","src":"textures/bang_w/G03_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Từ ký ức thành di tích","text":"Năm 1978, con cháu cụ Nguyễn Thông giao khu đất cho Nhà nước quản lý. Từ tháng 11/1978 đến tháng 12/1980, lớp học, nhà Ngư và Ngọa Du Sào được trùng tu, phục dựng theo dáng xưa. Công việc dựa trên phần di tích gốc cùng lời kể, bản vẽ phác họa của bốn học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh, nhà trưng bày bên trường được khánh thành; về sau hợp nhất thành Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Ngày 12/12/1986, Trường Dục Thanh được xếp hạng di tích lịch sử – văn hóa cấp quốc gia.\n\nMốc gần nhất trong bảng là ngày 1/7/2025: sau khi sắp xếp địa giới hành chính, khu di tích ở số 39 Trưng Nhị thuộc phường Phan Thiết, tỉnh Lâm Đồng. Dòng thời gian của Dục Thanh vì thế chưa khép lại: mỗi đoàn học trò đến thăm hôm nay lại viết tiếp vào đó một trang.","doc":10},{"loai":"ban_co_biet","text":"Cả đời Trường Dục Thanh chỉ khoảng năm năm, từ 1907 đến 1912, và thầy Thành đứng lớp ở đây chưa đầy nửa năm. Nhưng tính từ lần trùng tu 1978 – 1980, khu di tích đã được gìn giữ hơn bốn mươi lăm năm, lâu gấp nhiều lần đời của chính ngôi trường.","nguon_ten":"VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","Thanh Niên – Thầy Thành ở trường Dục Thanh – https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm","Znews – Tài liệu quý hiếm về cụ Nguyễn Sinh Sắc từ văn thư triều Nguyễn – https://znews.vn/tai-lieu-quy-hiem-ve-cu-nguyen-sinh-sac-tu-van-thu-trieu-nguyen-post996476.html","Báo Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành – https://tuoitre.vn/nld/hoi-nhap/bai-1-phong-trao-duy-tan-o-binh-thuan-da-khai-sinh-ra-lien-thanh-20090522104457589.htm","Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng"],"doc":[{"t":"Từ Ngọa Du Sào đến bến Nhà Rồng: dòng thời gian của Trường Dục Thanh. Câu chuyện Dục Thanh bắt đầu từ trước khi thầy Thành ra đời, và đến nay vẫn chưa khép lại. Ba mươi mốt mốc dưới đây nối lịch sử một mảnh vườn, một hội buôn và một ngôi trường với hành trình của người thanh niên Nguyễn Tất Thành. Đọc chúng theo thứ tự, ta sẽ thấy vì sao một thị xã nhỏ ven biển lại trở thành chặng dừng chân cuối cùng của Người trên đất Việt trước chuyến đi xa."},{"t":"Hai dòng thời gian gặp nhau. Bảng mốc thời gian này đặt cạnh nhau hai câu chuyện. Câu chuyện thứ nhất là của một mảnh đất và một ngôi trường: bắt đầu từ khi nhà thơ Nguyễn Thông dựng nhà bên sông Cà Ty, qua hội buôn Liên Thành, đến Trường Dục Thanh. Câu chuyện thứ hai là của một người thanh niên: rời Huế năm 1909, qua Bình Định, Phan Rang, làng Duồng rồi tới Phan Thiết vào mùa thu năm 1910. Hai dòng ấy gặp nhau trong chưa đầy nửa năm, từ tháng 9/1910 đến tháng 2/1911. Sau đó, mỗi dòng đi tiếp con đường riêng. Người thầy giáo trẻ vào Sài Gòn, xuống tàu ra đi, rồi trở thành Nguyễn Ái Quốc, Hồ Chí Minh. Ngôi trường khép cửa, lặng lẽ qua gần bảy mươi năm, rồi được dựng lại thành di tích lưu giữ ký ức về Người. Bảng dưới đây xếp các mốc của cả hai dòng theo đúng trình tự thời gian."},{"t":"Các mốc thời gian. 1827: Nhà thơ, nhà yêu nước Nguyễn Thông ra đời ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An. 1877: Nguyễn Thông được triều đình cử về Bình Thuận lo việc khai hoang vùng La Ngư, Ba Dầu. 1880: Nguyễn Thông dựng ngôi nhà nhỏ Ngọa Du Sào bên một con rạch của sông Cà Ty, thuộc làng Thành Đức, Phan Thiết. 1884: Nguyễn Thông qua đời; khu vườn ven sông và tủ sách được con cháu gìn giữ. 19/5/1890: Nguyễn Sinh Cung, sau này là Nguyễn Tất Thành, chào đời tại làng Hoàng Trù, huyện Nam Đàn, tỉnh Nghệ An. 20/10/1898: Vua Thành Thái ra đạo dụ lập thị xã Phan Thiết, tỉnh lỵ của Bình Thuận. 1905: Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp đi vào các tỉnh phía Nam Trung Kỳ cổ động Duy Tân, gặp gỡ các nhà nho Phan Thiết. 3/1906: Sáu nhà nho yêu nước lập Liên Thành thương quán, làm nước mắm để có vốn cho việc học và việc nước. 5/1906: Liên Thành thư xã ra đời, phổ biến sách báo mới, sách báo yêu nước. 1906: Nhà Ngư được dựng trong khuôn viên nhà họ Nguyễn để chứa ngư cụ; về sau là chỗ ở nội trú của thầy trò Dục Thanh. 1907: Trường Dục Thanh ra đời do ông Nguyễn Quý Anh trông coi, mọi chi phí do Liên Thành đài thọ; có tài liệu ghi năm 1908. 1908: Phong trào chống sưu thuế ở Trung Kỳ bị đàn áp; nhiều nhà Duy Tân bị bắt, trong đó có cụ Trương Gia Mô. 11/4 năm Duy Tân thứ 3 (1909): Bộ Lại dâng tấu bổ nhiệm Phó bảng Nguyễn Sinh Huy, tức cụ Nguyễn Sinh Sắc, làm tri huyện Bình Khê; vua Duy Tân chấm châu điểm chuẩn y. giữa 1909: Nguyễn Tất Thành rời Trường Quốc Học Huế, theo cha vào Bình Khê, tỉnh Bình Định. 9/1909: Nguyễn Tất Thành xuống Quy Nhơn học tiếp ở trường tiểu học Pháp – Việt, trau dồi tiếng Pháp. đầu 1910: Cụ Nguyễn Sinh Sắc bị cách chức tri huyện Bình Khê, bị đưa về Huế chờ xét xử. khoảng 8/1910: Nguyễn Tất Thành rời Bình Định, qua Phan Rang tới làng Duồng; cụ Trương Gia Mô cho ở chùa Phước An ban ngày, đêm về nhà cụ. 9/1910: Được ông Nguyễn Quý Anh nhận lời, Nguyễn Tất Thành bắt đầu dạy lớp nhì ở Trường Dục Thanh: chữ Quốc ngữ, chữ Hán, kiêm môn thể dục. 15/8 năm Duy Tân thứ 4 (1910): Bộ Hình dâng bản tấu kết luận vụ án Bình Khê, xử giáng cụ Nguyễn Sinh Sắc bốn cấp; cụ rời hẳn chốn quan trường. 18/9/1910: Tết Trung thu năm Canh Tuất; học trò cũ nhớ thầy Thành đã ăn Tết này cùng thầy trò Dục Thanh. 30/1/1911: Tết Nguyên đán Tân Hợi; thầy Thành vẫn ở Dục Thanh, mốc để các nhà nghiên cứu xác định thời gian thầy dạy học. 2/1911: Thầy Thành rời Dục Thanh; cụ Trương Gia Mô đưa vào Sài Gòn, gửi ở tạm nhà ông Lê Văn Đạt, xóm Cầu Rạch Bần. 5/6/1911: Với tên Văn Ba, Nguyễn Tất Thành làm phụ bếp trên tàu Amiral Latouche-Tréville, rời bến Nhà Rồng ra đi tìm đường cứu nước. 1912: Trường Dục Thanh đóng cửa sau khoảng năm năm hoạt động. 1929: Cụ Nguyễn Sinh Sắc mất tại Cao Lãnh; cũng năm này cụ Trương Gia Mô qua đời. 1978: Con cháu cụ Nguyễn Thông giao khu đất cho Nhà nước quản lý. 11/1978 – 12/1980: Trùng tu, phục dựng lớp học, nhà Ngư, Ngọa Du Sào theo dáng xưa, dựa vào di tích gốc cùng lời kể và bản vẽ của bốn học trò cũ. 19/5/1983: Khởi công nhà trưng bày về Chủ tịch Hồ Chí Minh ngay đối diện Trường Dục Thanh. 19/5/1986: Khánh thành công trình nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh; về sau là Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. 12/12/1986: Bộ Văn hóa – Thông tin xếp hạng Trường Dục Thanh là di tích lịch sử – văn hóa cấp quốc gia. 1/7/2025: Sau khi sắp xếp địa giới hành chính, khu di tích ở số 39 Trưng Nhị thuộc phường Phan Thiết, tỉnh Lâm Đồng."},{"t":"Trước khi có ngôi trường. Các mốc đầu tiên đưa người xem về cuối thế kỷ XIX. Nguyễn Thông, sinh năm 1827 ở phủ Tân An thuộc Gia Định cũ, là một nhà thơ, nhà yêu nước Nam Kỳ. Khi thực dân Pháp chiếm dần Nam Kỳ, ông không chịu sống dưới ách cai trị của giặc. Năm 1877, ông được triều đình cử về Bình Thuận lo việc khai hoang. Năm 1880, bên một con rạch nhỏ chảy từ sông Cà Ty vào làng Thành Đức, ông dựng ngôi nhà nhỏ Ngọa Du Sào. Ông mất năm 1884, để lại cho con cháu mảnh vườn ven sông và một tủ sách. Mười bốn năm sau, ngày 20/10/1898, vua Thành Thái ra đạo dụ lập thị xã Phan Thiết. Mảnh vườn của họ Nguyễn giờ nằm trong lòng một đô thị đang hình thành. Những mốc này cho thấy Dục Thanh không mọc lên trên đất trống. Nó được đặt trên nền của một gia đình có truyền thống yêu nước và học vấn, giữa một thị xã đang lớn lên nhờ biển."},{"t":"Ba năm dựng nghiệp, 1905 – 1907. Nhịp của các mốc dồn dập hơn ở đầu thế kỷ XX. Năm 1905, chuyến đi vào phương Nam của Phan Châu Trinh, Huỳnh Thúc Kháng, Trần Quý Cáp đem tư tưởng Duy Tân tới Phan Thiết. Tháng 3/1906, hội buôn Liên Thành ra đời. Tháng 5/1906, Liên Thành thư xã mở cửa. Cũng năm 1906, trong khuôn viên nhà họ Nguyễn, nhà Ngư được dựng để chứa ngư cụ; về sau nó thành chỗ ở nội trú của thầy trò. Năm 1907, Trường Dục Thanh ra đời. Chỉ trong khoảng hai năm, từ một ý tưởng, các nhà Duy Tân Phan Thiết đã có đủ ba trụ cột: tiền, sách và trường. Thứ tự các mốc cũng cho thấy cách làm của họ: lo nguồn tài chính trước, rồi mới mở trường. Về năm thành lập trường, tài liệu chưa hoàn toàn thống nhất. Phần lớn ghi năm 1907, một số ghi năm 1908. Bảng mốc ghi theo năm 1907 và chú thích cách ghi còn lại."},{"t":"Bạn có biết? Nhà trưng bày về Chủ tịch Hồ Chí Minh bên Trường Dục Thanh khởi công ngày 19/5/1983 và khánh thành ngày 19/5/1986: cả hai mốc đều được chọn đúng vào Ngày sinh của Bác."},{"t":"Năm 1908 và những đám mây. Mốc năm 1908 ghi lại một biến cố lớn. Phong trào chống sưu thuế bùng lên ở các tỉnh Trung Kỳ và bị thực dân đàn áp. Nhiều nhà Duy Tân bị bắt, bị đày, có người bị xử tử. Cụ Trương Gia Mô, người hai năm sau sẽ đưa Nguyễn Tất Thành tới Phan Thiết, cũng bị bắt giam vì liên quan đến phong trào. Trong bầu không khí ấy, Trường Dục Thanh vẫn tiếp tục mở cửa. Liên Thành vẫn buôn bán như một cơ sở kinh doanh hợp pháp, và nhờ vậy nhà trường có chỗ dựa. Chính vì ngôi trường còn đứng vững nên hai năm sau, người thanh niên Nguyễn Tất Thành mới có một lớp học để đứng. Đặt các mốc cạnh nhau, người xem thấy một điều đáng chú ý: ở nhiều nơi, phong trào Duy Tân bị dập tắt sau năm 1908; ở Phan Thiết, nó vẫn lặng lẽ tồn tại trong hình thức một hội buôn và một trường tư."},{"t":"Hai năm dồn dập. Dòng thời gian của Nguyễn Tất Thành dày đặc nhất trong những năm 1909 – 1911. Bản tấu bổ nhiệm cụ Nguyễn Sinh Huy làm tri huyện Bình Khê đề ngày 11 tháng 4 năm Duy Tân thứ ba, tức năm 1909. Giữa năm ấy, người con trai theo cha vào Bình Định; từ tháng 9 học tiếng Pháp ở Quy Nhơn. Khoảng tháng 8/1910, người con một mình đi tiếp về phương Nam. Tháng 2/1911, anh vào Sài Gòn. Ngày 5/6/1911, anh xuống tàu ra đi. Như vậy, từ khi rời Huế đến ngày rời Tổ quốc chỉ khoảng hai năm. Riêng từ lúc rời Dục Thanh đến ngày xuống tàu ở bến Nhà Rồng là khoảng bốn tháng. Những con số ấy cho thấy Phan Thiết là chặng dừng chân dài cuối cùng của Người trên đất Việt trước chuyến đi. Chúng cũng cho thấy một quyết tâm đã chín: người thanh niên không lưu lại lâu ở đâu, mỗi bước chân đều hướng ra biển lớn."},{"t":"Vì sao có những mốc ghi “khoảng”. Người xem sẽ thấy nhiều mốc trong bảng được ghi là khoảng, giữa năm hay đầu năm. Đó không phải sự tùy tiện, mà là sự thận trọng cần có với tư liệu lịch sử. Những gì ta biết về chặng Phan Thiết đến từ ba nguồn chính: văn bản hành chính như châu bản triều Nguyễn, các công trình biên niên do cơ quan nghiên cứu biên soạn, và lời kể của những người từng gặp Người. Mỗi nguồn có cách ghi ngày riêng. Châu bản ghi theo niên hiệu nhà vua, như ngày 15 tháng 8 năm Duy Tân thứ tư, khi Bộ Hình dâng bản tấu xử vụ án Bình Khê. Còn thời gian thầy Thành ở Dục Thanh được bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, xác định qua ký ức của học trò cũ. Các cụ nhớ thầy đã ăn Tết Trung thu năm 1910 và Tết Nguyên đán năm 1911 ở trường. Từ hai cái Tết ấy, các nhà nghiên cứu ghi mốc từ tháng 9/1910 đến tháng 2/1911."},{"t":"Sau khi thầy đi. Các mốc sau năm 1911 cho thấy số phận khác nhau của những con người và nơi chốn trong câu chuyện. Trường Dục Thanh hoạt động thêm một thời gian rồi đóng cửa vào năm 1912; cả đời trường chỉ khoảng năm năm. Hội buôn Liên Thành thì trụ vững, mở rộng vào Chợ Lớn và tồn tại đến sau năm 1975. Năm 1929, cụ Nguyễn Sinh Sắc mất ở Cao Lãnh; cũng năm ấy, cụ Trương Gia Mô qua đời. Hai bậc cha chú đã tiếp sức cho chặng đường phương Nam của người thanh niên đều không kịp thấy ngày Người trở về Tổ quốc năm 1941. Trong khi đó, khu vườn nhà họ Nguyễn bên sông Cà Ty vẫn do con cháu cụ Nguyễn Thông gìn giữ. Lớp học, nhà Ngư dần xuống cấp rồi không còn. Đến những năm sau 1975, trong khuôn viên chỉ còn Ngọa Du Sào, nhà thờ họ, cây khế và chiếc giếng. Ký ức về ngôi trường và người thầy giáo trẻ khi ấy chủ yếu nằm trong trí nhớ của những học trò cũ đã cao tuổi."},{"t":"Từ ký ức thành di tích. Năm 1978, con cháu cụ Nguyễn Thông giao khu đất cho Nhà nước quản lý. Từ tháng 11/1978 đến tháng 12/1980, lớp học, nhà Ngư và Ngọa Du Sào được trùng tu, phục dựng theo dáng xưa. Công việc dựa trên phần di tích gốc cùng lời kể, bản vẽ phác họa của bốn học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh Chủ tịch Hồ Chí Minh, nhà trưng bày bên trường được khánh thành; về sau hợp nhất thành Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Ngày 12/12/1986, Trường Dục Thanh được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Mốc gần nhất trong bảng là ngày 1/7/2025: sau khi sắp xếp địa giới hành chính, khu di tích ở số 39 Trưng Nhị thuộc phường Phan Thiết, tỉnh Lâm Đồng. Dòng thời gian của Dục Thanh vì thế chưa khép lại: mỗi đoàn học trò đến thăm hôm nay lại viết tiếp vào đó một trang."},{"t":"Bạn có biết? Cả đời Trường Dục Thanh chỉ khoảng năm năm, từ 1907 đến 1912, và thầy Thành đứng lớp ở đây chưa đầy nửa năm. Nhưng tính từ lần trùng tu 1978 – 1980, khu di tích đã được gìn giữ hơn bốn mươi lăm năm, lâu gấp nhiều lần đời của chính ngôi trường."}],"so_chu":1574},{"i":4,"tieu_de_bang":"Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ","tieu_de":"Nếp nhà gỗ bên sông Cà Ty: hành trình hơn một thế kỷ của Trường Dục Thanh","sapo":"Nhìn qua tấm ảnh, đó chỉ là mấy nếp nhà gỗ mái ngói giữa lòng Phan Thiết. Nhưng ngôi trường ấy chỉ hoạt động khoảng năm năm, rồi có lúc chỉ còn lại một ngôi nhà nhỏ, một nhà thờ họ, một cây khế và một chiếc giếng. Nó được dựng lại nhờ trí nhớ của bốn học trò cũ của thầy Thành. Câu chuyện của những nếp nhà gỗ ấy dài hơn một thế kỷ.","bia":{"src":"textures/ht/ht_anh_truong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Mấy nếp nhà gỗ trong khung hình","text":"Tấm ảnh ghi lại Trường Dục Thanh như du khách nhìn thấy hôm nay: những nếp nhà gỗ lợp ngói âm dương, giản dị. Ảnh do Bùi Thụy Đào Nguyên chụp, chia sẻ trên kho tư liệu Wikimedia Commons theo giấy phép CC BY-SA 3.0; ngày chụp không được ghi lại. Đó là cả một quần thể di tích quốc gia rộng khoảng 4.090 mét vuông, ở số 39 đường Trưng Nhị, bên hữu ngạn sông Cà Ty.\n\nHơn một thế kỷ trước, nơi này thuộc làng Thành Đức, thị xã Phan Thiết, tỉnh Bình Thuận. Từ ngày 1/7/2025, sau khi sắp xếp lại địa giới hành chính, khu di tích thuộc phường Phan Thiết, tỉnh Lâm Đồng. Từ tháng 9/1910 đến tháng 2/1911, dưới một mái nhà gỗ như thế, người thanh niên Nguyễn Tất Thành, vừa hai mươi tuổi, đứng lớp nhì của trường. Nhưng câu chuyện của những nếp nhà này không bắt đầu từ năm 1910. Nó bắt đầu sớm hơn ba mươi năm, với một nhà thơ yêu nước từ Nam Kỳ ra lập nghiệp.","doc":1},{"loai":"doan","tieu_de":"Mảnh đất của nhà thơ Nguyễn Thông","text":"Khu đất vốn thuộc nhà thơ, nhà yêu nước Nguyễn Thông (1827–1884), quê ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An. Khi thực dân Pháp chiếm dần Nam Kỳ, ông cùng một số sĩ phu ra Bình Thuận. Năm 1877, ông được triều đình cử về đây lo việc khai hoang vùng La Ngư, Ba Dầu, rồi lãnh chức Bố chánh Bình Thuận. Ở hữu ngạn sông Phan Thiết, ông gặp một con rạch nhỏ chảy vào làng Thành Đức, cảnh sông nước giống hệt quê nhà Nam Bộ thời thơ ấu. Ông mua đất, dựng nhà, rồi năm 1880 cất thêm ngôi nhà nhỏ Ngọa Du Sào ngay bên cạnh (xem chuyên đề Nhà Ngọa Du Sào).\n\nTrong Ngọa Du Sào văn tập, Nguyễn Thông tả nơi ở của mình: con rạch từ sông chảy vào tận nhà, đi lại bằng xuồng rất tiện. Buổi sáng, chim quốc về đậu cành cây, kêu não nùng. Khi nước ròng, hai bờ sông lộ ra bãi cồn mọc đầy bần, đước. Nhờ những dòng văn ấy, người đời sau biết mảnh đất của Trường Dục Thanh từng mang dáng một vườn quê sông nước Nam Bộ giữa đất Bình Thuận nắng gió. Hai mươi bảy năm sau khi Ngọa Du Sào được dựng, trên chính mảnh vườn ấy, một ngôi trường ra đời.","doc":2},{"loai":"anh","src":"textures/bang_w/G03_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một ngôi nhà chung cho cả bốn lớp","text":"Năm 1905, trong chuyến Nam du tìm hiểu dân tình các tỉnh Nam Trung Bộ, Phan Châu Trinh đến Phan Thiết và gặp hai người con của cụ Nguyễn Thông là Nguyễn Trọng Lội và Nguyễn Quý Anh. Từ những cuộc trò chuyện về việc mở mang dân trí, ý tưởng lập một ngôi trường cho con em địa phương đã hình thành. Các ông cùng những nhà Duy Tân khác lập hội buôn Liên Thành để lo tiền cho việc học (xem chuyên đề Hội buôn nước mắm nuôi một ngôi trường). Năm 1907, có tài liệu ghi năm 1908, trường được dựng ngay trong khuôn viên nhà cụ Nguyễn Thông, lấy tên Dục Thanh, nghĩa là giáo dục thanh thiếu niên.\n\nNgười đi học khi ấy còn ít, trường lại theo một mô hình rất mới, nên không chia thành từng phòng riêng. Cả trường chỉ là một ngôi nhà chung hai mái, lợp ngói âm dương, nền lát gạch Bát Tràng, cột và vách đều bằng gỗ. Tường bao quanh làm bằng những song gỗ xếp chéo hình thoi để đón ánh sáng và gió từ bên ngoài. Bốn lớp Tư, Ba, Nhì, Nhất cùng học dưới một mái nhà. Đó là một lối kiến trúc Á Đông giản dị, thoáng đãng và tiết kiệm.","doc":3},{"loai":"doan","tieu_de":"Mỗi nếp nhà một công năng","text":"Đứng từ cổng nhìn vào, ngôi nhà đầu tiên là lớp học. Ngay bên phải là nhà Ngư, dựng năm 1906, ban đầu dùng để chứa ngư cụ, làm cá và chế biến nước mắm của gia đình cụ Nguyễn Thông. Khi trường mở, nhà Ngư được sửa sang thành chỗ ở nội trú cho thầy giáo và học trò ở xa. Phía sau lớp học và nhà Ngư là Ngọa Du Sào, được dùng làm thư viện của trường. Sau nữa là chiếc giếng gạch và khu vườn có cây khế cổ thụ. Trong khuôn viên còn có nhà thờ cụ Nguyễn Thông và dòng họ.\n\nBố cục ấy cho thấy một ngôi trường tự lo liệu mọi mặt: nơi học, nơi ở, nơi đọc sách và nguồn nước đều nằm gọn trong một khu vườn. Học trò không chỉ là con em Phan Thiết. Theo Báo Cần Thơ, có em từ Sài Gòn ra, có em từ Đà Nẵng, Hội An vào, cùng nhiều nơi ở Nam Trung Bộ và miền Đông Nam Bộ, do các thân sĩ gửi gắm trọ học. Những nếp nhà gỗ nhỏ vì thế từng là mái nhà chung của một cộng đồng thầy trò đến từ nhiều miền, cùng ở, cùng học.","doc":4},{"loai":"ban_co_biet","text":"Theo tư liệu của Bảo tàng Hồ Chí Minh, Dục Thanh là trường nội trú đầu tiên của tỉnh Bình Thuận. Chỗ ở của thầy trò chính là nhà Ngư, nơi trước đó gia đình cụ Nguyễn Thông dùng để chứa ngư cụ và làm nước mắm.","nguon_ten":"Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","doc":5},{"loai":"doan","tieu_de":"Khi tiếng học trò lặng đi","text":"Tháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn; bốn tháng sau, người thanh niên xuống tàu ra đi tìm đường cứu nước. Ngôi trường còn hoạt động thêm một thời gian rồi đóng cửa vào năm 1912. Như vậy, cả đời trường chỉ vỏn vẹn khoảng năm năm. Đó cũng là những năm phong trào Duy Tân ở Trung Kỳ bị thực dân Pháp đàn áp sau vụ chống sưu thuế năm 1908. Chính cụ Trương Gia Mô, người giới thiệu Nguyễn Tất Thành đến Phan Thiết, cũng từng bị bắt giam năm 1908 vì liên quan đến phong trào ấy.\n\nTrường đóng cửa, những ngôi nhà gỗ ít được chăm sóc, lại chịu tác động của thời gian và khí hậu miền biển, nên dần xuống cấp. Khu đất vẫn do con cháu cụ Nguyễn Thông gìn giữ. Nhưng đến những năm sau 1975, phần lớn các công trình của trường xưa không còn. Lớp học nơi thầy Thành từng đứng giảng, nhà Ngư nơi thầy từng ở chỉ còn trong trí nhớ của những học trò cũ, khi ấy đều đã là những cụ già. Muốn dựng lại ngôi trường, người ta phải tìm đến chính những trí nhớ ấy.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_song_ca_ty.jpg","chu_thich":"Sông Cà Ty chảy qua Phan Thiết (ảnh chụp tháng 11/2014). Trường Dục Thanh nằm bên hữu ngạn dòng sông này. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dựng lại từ trí nhớ của bốn học trò","text":"Sau ngày đất nước thống nhất, Đảng bộ tỉnh Thuận Hải, tên chung của vùng đất Bình Thuận, Ninh Thuận những năm ấy, báo cáo Ban Bí thư Trung ương Đảng xin phép trùng tu, phục dựng khu Dục Thanh. Năm 1978, con cháu cụ Nguyễn Thông giao lại khu đất cho Nhà nước quản lý. Công việc kéo dài từ tháng 11/1978 đến tháng 12/1980, trên toàn bộ khuôn viên rộng khoảng 4.090 mét vuông.\n\nViệc phục dựng dựa trên phần di tích gốc còn lại, cùng lời kể và những bản vẽ phác họa của bốn học trò từng học thầy Thành năm 1910. Đó là các cụ Nguyễn Quý Phầu, Nguyễn Đăng Lầu, Từ Trường Phùng và Nguyễn Kinh Chi. Qua trí nhớ của các cụ, lớp học, nhà Ngư, cổng trường và tường rào gỗ lần lượt được dựng lại theo dáng xưa. Có thể nói, những nếp nhà gỗ trong tấm ảnh là ký ức của học trò được dựng thành kiến trúc. Lời kể của các cụ cũng trở thành nguồn tư liệu quý để giới nghiên cứu tìm hiểu cách dạy, cách sống của thầy giáo trẻ Nguyễn Tất Thành.","doc":7},{"loai":"ban_co_biet","text":"Sau năm 1975, trong khuôn viên Dục Thanh chỉ còn lại Ngọa Du Sào, nhà thờ cụ Nguyễn Thông, cây khế và giếng nước. Lớp học và nhà Ngư mà du khách thấy hôm nay được phục dựng trong những năm 1978–1980.","nguon_ten":"VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết","doc":8},{"loai":"anh","src":"textures/bang_w/G03_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Di tích quốc gia bên một công trình tưởng niệm","text":"Ngày 12/12/1986, Bộ Văn hóa – Thông tin xếp hạng Trường Dục Thanh là di tích lịch sử – văn hóa cấp quốc gia. Trước đó, ngày 19/5/1983, nhân kỷ niệm 93 năm Ngày sinh Chủ tịch Hồ Chí Minh, một nhà trưng bày về tiểu sử và sự nghiệp của Người được khởi công ngay đối diện trường. Đi cùng là một công viên và tượng đài Bác Hồ với các cháu thiếu nhi. Công trình khánh thành ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh của Người.\n\nVề sau, khu di tích, nhà trưng bày, công viên và tượng đài được hợp nhất thành Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Nhà trưng bày có một gian trang trọng để tưởng niệm Bác, nơi thường diễn ra lễ báo công, lễ kết nạp Đội, Đoàn, Đảng. Phần còn lại giới thiệu cuộc đời, sự nghiệp của Người và tình cảm của Người với nhân dân Bình Thuận, bằng hàng trăm hình ảnh, hiện vật, tài liệu, sa bàn, bản đồ. Quanh mấy nếp nhà gỗ nhỏ, cả một quần thể tưởng niệm đã hình thành bên dòng Cà Ty.","doc":9},{"loai":"doan","tieu_de":"Phần gốc và phần phục dựng","text":"Giữa những công trình phục dựng, khu di tích vẫn giữ được một số hiện vật gốc từ thời thầy Thành dạy học. Đó là bộ họa đàn trường kỷ, bộ ván gõ, chiếc án thư, tủ đứng, tráp văn thư, nghiên mài mực, ba chiếc ly nhỏ và một chiếc khay. Tất cả đều cũ kỹ nhưng được bảo quản cẩn thận. Bên cạnh đó là hai chứng nhân sống ngoài vườn: cây khế cổ thụ và chiếc giếng gạch mà thầy Thành từng múc nước tưới cây (xem chuyên đề Giếng nước trong sân Trường Dục Thanh).\n\nSự kết hợp giữa phần gốc và phần phục dựng là đặc điểm cần hiểu đúng khi tham quan Dục Thanh. Mái ngói, vách gỗ của lớp học hôm nay được làm lại trong những năm 1978–1980. Nhưng vị trí, bố cục và dáng vẻ của chúng được giữ theo lời kể của chính những người từng ngồi học ở đây. Vì vậy, khi nói Dục Thanh là di tích giữ nguyên nếp nhà gỗ, ta nói về cái nếp, cái dáng của ngôi trường xưa được trao truyền qua trí nhớ của nhiều thế hệ.","doc":10},{"loai":"anh","src":"textures/bang_w/G03_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dục Thanh hôm nay","text":"Du khách hôm nay vào di tích từ phía bờ sông Cà Ty. Cổng trường làm bằng gỗ gõ sừng, một loại danh mộc của Bình Thuận, trên lợp mái ngói âm dương phục chế hình thuyền. Qua cổng là khoảng sân rộng lát gạch tàu đỏ, hai bên trồng cà đam, kim quít, sứ đỏ, dâm bụt. Trong lớp học, khách có thể ngồi vào bàn học trò, nghe thuyết minh viên kể về người thầy giáo trẻ năm 1910.\n\nDi tích là địa chỉ quen thuộc của những buổi sinh hoạt truyền thống, nhất là dịp tháng Năm và Ngày Nhà giáo Việt Nam. Riêng bảy tháng đầu năm 2026, nơi đây đón gần 1.400 đoàn với hơn 103.000 lượt khách, trong đó có nhiều đoàn khách quốc tế đến từ Anh, Úc, Hàn Quốc, Nga, Mỹ, Trung Quốc. Hơn một trăm năm sau ngày thầy Thành rời trường, những nếp nhà gỗ bên dòng Cà Ty vẫn làm đúng việc của một ngôi trường: kể cho lớp trẻ nghe về tình yêu đất nước.","doc":11}],"nguon":["Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng – https://baovanhoa.vn/van-hoa/ky-2-dia-chi-do-ve-nguon-thieng-lieng-256668.html","Báo Văn hóa – Kỳ 1: Về Dục Thanh nghe kể chuyện Bác Hồ dạy học – https://baovanhoa.vn/van-hoa/ky-1-ve-duc-thanh-nghe-ke-chuyen-bac-ho-day-hoc-255667.html","Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành – https://giaoducthoidai.vn/noi-luu-dau-cua-thay-giao-nguyen-tat-thanh-post671585.html","VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh – https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm","Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành – https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html"],"doc":[{"t":"Nếp nhà gỗ bên sông Cà Ty: hành trình hơn một thế kỷ của Trường Dục Thanh. Nhìn qua tấm ảnh, đó chỉ là mấy nếp nhà gỗ mái ngói giữa lòng Phan Thiết. Nhưng ngôi trường ấy chỉ hoạt động khoảng năm năm, rồi có lúc chỉ còn lại một ngôi nhà nhỏ, một nhà thờ họ, một cây khế và một chiếc giếng. Nó được dựng lại nhờ trí nhớ của bốn học trò cũ của thầy Thành. Câu chuyện của những nếp nhà gỗ ấy dài hơn một thế kỷ."},{"t":"Mấy nếp nhà gỗ trong khung hình. Tấm ảnh ghi lại Trường Dục Thanh như du khách nhìn thấy hôm nay: những nếp nhà gỗ lợp ngói âm dương, giản dị. Ảnh do Bùi Thụy Đào Nguyên chụp, chia sẻ trên kho tư liệu Wikimedia Commons theo giấy phép CC BY-SA 3.0; ngày chụp không được ghi lại. Đó là cả một quần thể di tích quốc gia rộng khoảng 4.090 mét vuông, ở số 39 đường Trưng Nhị, bên hữu ngạn sông Cà Ty. Hơn một thế kỷ trước, nơi này thuộc làng Thành Đức, thị xã Phan Thiết, tỉnh Bình Thuận. Từ ngày 1/7/2025, sau khi sắp xếp lại địa giới hành chính, khu di tích thuộc phường Phan Thiết, tỉnh Lâm Đồng. Từ tháng 9/1910 đến tháng 2/1911, dưới một mái nhà gỗ như thế, người thanh niên Nguyễn Tất Thành, vừa hai mươi tuổi, đứng lớp nhì của trường. Nhưng câu chuyện của những nếp nhà này không bắt đầu từ năm 1910. Nó bắt đầu sớm hơn ba mươi năm, với một nhà thơ yêu nước từ Nam Kỳ ra lập nghiệp."},{"t":"Mảnh đất của nhà thơ Nguyễn Thông. Khu đất vốn thuộc nhà thơ, nhà yêu nước Nguyễn Thông (1827–1884), quê ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An. Khi thực dân Pháp chiếm dần Nam Kỳ, ông cùng một số sĩ phu ra Bình Thuận. Năm 1877, ông được triều đình cử về đây lo việc khai hoang vùng La Ngư, Ba Dầu, rồi lãnh chức Bố chánh Bình Thuận. Ở hữu ngạn sông Phan Thiết, ông gặp một con rạch nhỏ chảy vào làng Thành Đức, cảnh sông nước giống hệt quê nhà Nam Bộ thời thơ ấu. Ông mua đất, dựng nhà, rồi năm 1880 cất thêm ngôi nhà nhỏ Ngọa Du Sào ngay bên cạnh (xem chuyên đề Nhà Ngọa Du Sào). Trong Ngọa Du Sào văn tập, Nguyễn Thông tả nơi ở của mình: con rạch từ sông chảy vào tận nhà, đi lại bằng xuồng rất tiện. Buổi sáng, chim quốc về đậu cành cây, kêu não nùng. Khi nước ròng, hai bờ sông lộ ra bãi cồn mọc đầy bần, đước. Nhờ những dòng văn ấy, người đời sau biết mảnh đất của Trường Dục Thanh từng mang dáng một vườn quê sông nước Nam Bộ giữa đất Bình Thuận nắng gió. Hai mươi bảy năm sau khi Ngọa Du Sào được dựng, trên chính mảnh vườn ấy, một ngôi trường ra đời."},{"t":"Một ngôi nhà chung cho cả bốn lớp. Năm 1905, trong chuyến Nam du tìm hiểu dân tình các tỉnh Nam Trung Bộ, Phan Châu Trinh đến Phan Thiết và gặp hai người con của cụ Nguyễn Thông là Nguyễn Trọng Lội và Nguyễn Quý Anh. Từ những cuộc trò chuyện về việc mở mang dân trí, ý tưởng lập một ngôi trường cho con em địa phương đã hình thành. Các ông cùng những nhà Duy Tân khác lập hội buôn Liên Thành để lo tiền cho việc học (xem chuyên đề Hội buôn nước mắm nuôi một ngôi trường). Năm 1907, có tài liệu ghi năm 1908, trường được dựng ngay trong khuôn viên nhà cụ Nguyễn Thông, lấy tên Dục Thanh, nghĩa là giáo dục thanh thiếu niên. Người đi học khi ấy còn ít, trường lại theo một mô hình rất mới, nên không chia thành từng phòng riêng. Cả trường chỉ là một ngôi nhà chung hai mái, lợp ngói âm dương, nền lát gạch Bát Tràng, cột và vách đều bằng gỗ. Tường bao quanh làm bằng những song gỗ xếp chéo hình thoi để đón ánh sáng và gió từ bên ngoài. Bốn lớp Tư, Ba, Nhì, Nhất cùng học dưới một mái nhà. Đó là một lối kiến trúc Á Đông giản dị, thoáng đãng và tiết kiệm."},{"t":"Mỗi nếp nhà một công năng. Đứng từ cổng nhìn vào, ngôi nhà đầu tiên là lớp học. Ngay bên phải là nhà Ngư, dựng năm 1906, ban đầu dùng để chứa ngư cụ, làm cá và chế biến nước mắm của gia đình cụ Nguyễn Thông. Khi trường mở, nhà Ngư được sửa sang thành chỗ ở nội trú cho thầy giáo và học trò ở xa. Phía sau lớp học và nhà Ngư là Ngọa Du Sào, được dùng làm thư viện của trường. Sau nữa là chiếc giếng gạch và khu vườn có cây khế cổ thụ. Trong khuôn viên còn có nhà thờ cụ Nguyễn Thông và dòng họ. Bố cục ấy cho thấy một ngôi trường tự lo liệu mọi mặt: nơi học, nơi ở, nơi đọc sách và nguồn nước đều nằm gọn trong một khu vườn. Học trò không chỉ là con em Phan Thiết. Theo Báo Cần Thơ, có em từ Sài Gòn ra, có em từ Đà Nẵng, Hội An vào, cùng nhiều nơi ở Nam Trung Bộ và miền Đông Nam Bộ, do các thân sĩ gửi gắm trọ học. Những nếp nhà gỗ nhỏ vì thế từng là mái nhà chung của một cộng đồng thầy trò đến từ nhiều miền, cùng ở, cùng học."},{"t":"Bạn có biết? Theo tư liệu của Bảo tàng Hồ Chí Minh, Dục Thanh là trường nội trú đầu tiên của tỉnh Bình Thuận. Chỗ ở của thầy trò chính là nhà Ngư, nơi trước đó gia đình cụ Nguyễn Thông dùng để chứa ngư cụ và làm nước mắm."},{"t":"Khi tiếng học trò lặng đi. Tháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn; bốn tháng sau, người thanh niên xuống tàu ra đi tìm đường cứu nước. Ngôi trường còn hoạt động thêm một thời gian rồi đóng cửa vào năm 1912. Như vậy, cả đời trường chỉ vỏn vẹn khoảng năm năm. Đó cũng là những năm phong trào Duy Tân ở Trung Kỳ bị thực dân Pháp đàn áp sau vụ chống sưu thuế năm 1908. Chính cụ Trương Gia Mô, người giới thiệu Nguyễn Tất Thành đến Phan Thiết, cũng từng bị bắt giam năm 1908 vì liên quan đến phong trào ấy. Trường đóng cửa, những ngôi nhà gỗ ít được chăm sóc, lại chịu tác động của thời gian và khí hậu miền biển, nên dần xuống cấp. Khu đất vẫn do con cháu cụ Nguyễn Thông gìn giữ. Nhưng đến những năm sau 1975, phần lớn các công trình của trường xưa không còn. Lớp học nơi thầy Thành từng đứng giảng, nhà Ngư nơi thầy từng ở chỉ còn trong trí nhớ của những học trò cũ, khi ấy đều đã là những cụ già. Muốn dựng lại ngôi trường, người ta phải tìm đến chính những trí nhớ ấy."},{"t":"Dựng lại từ trí nhớ của bốn học trò. Sau ngày đất nước thống nhất, Đảng bộ tỉnh Thuận Hải, tên chung của vùng đất Bình Thuận, Ninh Thuận những năm ấy, báo cáo Ban Bí thư Trung ương Đảng xin phép trùng tu, phục dựng khu Dục Thanh. Năm 1978, con cháu cụ Nguyễn Thông giao lại khu đất cho Nhà nước quản lý. Công việc kéo dài từ tháng 11/1978 đến tháng 12/1980, trên toàn bộ khuôn viên rộng khoảng 4.090 mét vuông. Việc phục dựng dựa trên phần di tích gốc còn lại, cùng lời kể và những bản vẽ phác họa của bốn học trò từng học thầy Thành năm 1910. Đó là các cụ Nguyễn Quý Phầu, Nguyễn Đăng Lầu, Từ Trường Phùng và Nguyễn Kinh Chi. Qua trí nhớ của các cụ, lớp học, nhà Ngư, cổng trường và tường rào gỗ lần lượt được dựng lại theo dáng xưa. Có thể nói, những nếp nhà gỗ trong tấm ảnh là ký ức của học trò được dựng thành kiến trúc. Lời kể của các cụ cũng trở thành nguồn tư liệu quý để giới nghiên cứu tìm hiểu cách dạy, cách sống của thầy giáo trẻ Nguyễn Tất Thành."},{"t":"Bạn có biết? Sau năm 1975, trong khuôn viên Dục Thanh chỉ còn lại Ngọa Du Sào, nhà thờ cụ Nguyễn Thông, cây khế và giếng nước. Lớp học và nhà Ngư mà du khách thấy hôm nay được phục dựng trong những năm 1978–1980."},{"t":"Di tích quốc gia bên một công trình tưởng niệm. Ngày 12/12/1986, Bộ Văn hóa – Thông tin xếp hạng Trường Dục Thanh là di tích lịch sử – văn hóa cấp quốc gia. Trước đó, ngày 19/5/1983, nhân kỷ niệm 93 năm Ngày sinh Chủ tịch Hồ Chí Minh, một nhà trưng bày về tiểu sử và sự nghiệp của Người được khởi công ngay đối diện trường. Đi cùng là một công viên và tượng đài Bác Hồ với các cháu thiếu nhi. Công trình khánh thành ngày 19/5/1986, nhân kỷ niệm 96 năm Ngày sinh của Người. Về sau, khu di tích, nhà trưng bày, công viên và tượng đài được hợp nhất thành Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Nhà trưng bày có một gian trang trọng để tưởng niệm Bác, nơi thường diễn ra lễ báo công, lễ kết nạp Đội, Đoàn, Đảng. Phần còn lại giới thiệu cuộc đời, sự nghiệp của Người và tình cảm của Người với nhân dân Bình Thuận, bằng hàng trăm hình ảnh, hiện vật, tài liệu, sa bàn, bản đồ. Quanh mấy nếp nhà gỗ nhỏ, cả một quần thể tưởng niệm đã hình thành bên dòng Cà Ty."},{"t":"Phần gốc và phần phục dựng. Giữa những công trình phục dựng, khu di tích vẫn giữ được một số hiện vật gốc từ thời thầy Thành dạy học. Đó là bộ họa đàn trường kỷ, bộ ván gõ, chiếc án thư, tủ đứng, tráp văn thư, nghiên mài mực, ba chiếc ly nhỏ và một chiếc khay. Tất cả đều cũ kỹ nhưng được bảo quản cẩn thận. Bên cạnh đó là hai chứng nhân sống ngoài vườn: cây khế cổ thụ và chiếc giếng gạch mà thầy Thành từng múc nước tưới cây (xem chuyên đề Giếng nước trong sân Trường Dục Thanh). Sự kết hợp giữa phần gốc và phần phục dựng là đặc điểm cần hiểu đúng khi tham quan Dục Thanh. Mái ngói, vách gỗ của lớp học hôm nay được làm lại trong những năm 1978–1980. Nhưng vị trí, bố cục và dáng vẻ của chúng được giữ theo lời kể của chính những người từng ngồi học ở đây. Vì vậy, khi nói Dục Thanh là di tích giữ nguyên nếp nhà gỗ, ta nói về cái nếp, cái dáng của ngôi trường xưa được trao truyền qua trí nhớ của nhiều thế hệ."},{"t":"Dục Thanh hôm nay. Du khách hôm nay vào di tích từ phía bờ sông Cà Ty. Cổng trường làm bằng gỗ gõ sừng, một loại danh mộc của Bình Thuận, trên lợp mái ngói âm dương phục chế hình thuyền. Qua cổng là khoảng sân rộng lát gạch tàu đỏ, hai bên trồng cà đam, kim quít, sứ đỏ, dâm bụt. Trong lớp học, khách có thể ngồi vào bàn học trò, nghe thuyết minh viên kể về người thầy giáo trẻ năm 1910. Di tích là địa chỉ quen thuộc của những buổi sinh hoạt truyền thống, nhất là dịp tháng Năm và Ngày Nhà giáo Việt Nam. Riêng bảy tháng đầu năm 2026, nơi đây đón gần 1.400 đoàn với hơn 103.000 lượt khách, trong đó có nhiều đoàn khách quốc tế đến từ Anh, Úc, Hàn Quốc, Nga, Mỹ, Trung Quốc. Hơn một trăm năm sau ngày thầy Thành rời trường, những nếp nhà gỗ bên dòng Cà Ty vẫn làm đúng việc của một ngôi trường: kể cho lớp trẻ nghe về tình yêu đất nước."}],"so_chu":1967},{"i":5,"tieu_de_bang":"Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp","tieu_de":"Một ngày ở lớp nhì Dục Thanh: thầy Thành dạy gì và dạy thế nào?","sapo":"Sáu giờ sáng, giờ học ở Trường Dục Thanh đã bắt đầu, sau buổi tập thể dục ngoài sân. Trong ngôi nhà gỗ chung của cả bốn lớp, một thầy giáo hai mươi tuổi giảng chậm những bài khó và kiên nhẫn hỏi lại từng trò. Mấy chục năm sau, học trò cũ vẫn nhớ từng nét trong cách dạy ấy. Một ngày học ở Dục Thanh năm 1910 diễn ra như thế nào?","bia":{"src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một mái nhà cho bốn lớp học","text":"Tấm ảnh do Bùi Thụy Đào Nguyên chụp bên trong lớp học của Trường Dục Thanh, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 3.0. Không gian ấy được phục dựng trong những năm 1978–1980, theo lời kể của chính những học trò từng ngồi học ở đây năm 1910. Vì vậy, nhìn vào lớp học, ta có thể hình dung khá sát một ngày học của thầy trò Dục Thanh hơn một thế kỷ trước.\n\nĐiều đầu tiên cần biết là trường không chia thành từng phòng riêng. Cả bốn lớp Tư, Ba, Nhì, Nhất cùng học trong một ngôi nhà chung. Lúc đông nhất, trường có khoảng sáu mươi học trò, trong đó có bốn nữ sinh, một chi tiết đáng chú ý ở thời ấy. Trong bốn bậc lớp, lớp nhì là bậc thứ ba, chỉ đứng sau lớp nhất. Trường có khoảng bảy thầy giáo, ông Nguyễn Quý Anh, con trai nhà thơ Nguyễn Thông, làm hiệu trưởng. Trẻ nhất trong các thầy là Nguyễn Tất Thành, vừa tròn hai mươi tuổi, được giao phụ trách lớp nhì.","doc":1},{"loai":"doan","tieu_de":"Sáu giờ sáng, giờ thể dục","text":"Nội quy của trường rất nghiêm. Hằng ngày, giờ học bắt đầu từ sáu giờ sáng, đến năm giờ chiều mới tan. Buổi sáng, học trò tập thể dục trước, rồi xếp hàng thật ngay ngắn đi vào lớp. Theo tài liệu của PGS.TS Trần Thị Thu Hương, Viện Lịch sử Đảng, sáng nào thầy Thành cũng dậy sớm và gọi mọi người ra sân tập. Thầy ở nội trú ngay trong khuôn viên trường, nên giờ thể dục buổi sớm gắn liền với nếp sinh hoạt hằng ngày của thầy.\n\nVào lớp, học trò khoanh tay trước ngực, cùng hát một bài ca ái quốc dựa theo bài thơ yêu nước Phan Châu Trinh viết năm 1907. Đó là bài mỗi học trò phải thuộc lòng. Thầy Thành còn đem những bài ca của phong trào Duy Tân phổ biến cho thầy trò trong trường. Một ngày học vì thế mở đầu không phải bằng con chữ, mà bằng sức khỏe và lời ca về đất nước. Cách mở đầu ấy nói lên mục đích của ngôi trường: đào tạo những người trẻ vừa khỏe mạnh, vừa hiểu biết, vừa biết yêu nước.","doc":2},{"loai":"anh","src":"textures/bang_w/G03_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chương trình theo khuôn Đông Kinh Nghĩa Thục","text":"Nội dung học ở Dục Thanh dựa theo mô hình Đông Kinh Nghĩa Thục ở Hà Nội, có cải biến cho hợp với thực tế Bình Thuận để tránh bị thực dân đàn áp. Theo Báo Cần Thơ, chương trình giảng dạy do Đông Kinh Nghĩa Thục biên khảo, chú giải rồi gửi vào Phan Thiết. Chữ Quốc ngữ là môn chính, bên cạnh chữ Hán và tiếng Pháp. Khi ấy, phần đông con em vẫn theo lối học khoa cử nặng về kinh sử chữ Hán, còn trường Pháp – Việt do chính quyền thuộc địa quản lý. Một trường tư lấy chữ Quốc ngữ làm gốc là một lựa chọn mới mẻ và mạnh dạn.\n\nTrường còn có một nếp sinh hoạt rất riêng. Tối thứ năm hằng tuần, học trò lớp nhất và lớp nhì luân phiên chuẩn bị trước một đề tài, rồi đứng lên thuyết trình bằng tiếng Việt trước tập thể. Học trò lớp nhì của thầy Thành vì thế không chỉ học đọc, học viết, mà còn tập nói trước đông người. Nhận xét về chất lượng và xu hướng mới của Dục Thanh, nhiều nhà nghiên cứu cho rằng ở Phan Thiết khi ấy có một trường tư thục vào loại tiến bộ nhất Việt Nam.","doc":3},{"loai":"ban_co_biet","text":"Các học trò cũ nhớ thầy Thành đã ăn hai cái Tết ở Phan Thiết: Tết Trung thu năm Canh Tuất, ngày 18/9/1910, và Tết Nguyên đán Tân Hợi, ngày 30/1/1911. Nhà nghiên cứu Ngô Thị Mùi dựa vào chi tiết ấy để xác định thầy có mặt ở Dục Thanh từ tháng 9/1910 đến tháng 2/1911.","nguon_ten":"Thanh Niên – Thầy Thành ở trường Dục Thanh","doc":4},{"loai":"doan","tieu_de":"Thầy giáo trẻ nhất trường nhận lớp nhì","text":"Theo phần lớn tư liệu, ở lớp nhì thầy Thành chủ yếu dạy chữ Quốc ngữ và chữ Hán, kiêm môn thể dục. Khi thầy giáo Pháp văn vắng mặt, thầy dạy thay tiếng Pháp. Cũng có tư liệu ghi thầy phụ trách thể dục là chính, trợ giảng ba môn Quốc ngữ, Hán văn, Pháp văn, và đứng lớp thay khi các thầy khác nghỉ bệnh hay bận việc. Hai cách ghi chép cùng cho thấy một người thầy trẻ được nhà trường tin cậy, có thể đảm đương nhiều việc.\n\nPGS.TS Trần Thị Thu Hương nghiêng về khả năng thầy dạy Quốc ngữ và Hán văn, bởi thầy lớn lên trong một gia đình khoa bảng, Nho học. Vốn chữ Hán thầy có từ những năm học với cha và thầy đồ Vương Thúc Quý ở quê nhà Nghệ An. Chữ Quốc ngữ và tiếng Pháp thầy học ở các trường Pháp – Việt, ở Trường Quốc Học Huế, rồi học thêm tiếng Pháp ở Quy Nhơn. Một người vừa thông chữ Hán, vừa đọc được sách Pháp như thế là vốn quý với một trường tư ở tỉnh lẻ.","doc":5},{"loai":"doan","tieu_de":"Bài khó thì giảng chậm","text":"Cách dạy của thầy Thành được biết đến chủ yếu qua lời kể của các học trò cũ như cụ Nguyễn Quý Phầu và cụ Nguyễn Đăng Lầu. Các cụ nhớ thầy giảng bài rất nhiệt tình, dễ hiểu. Những bài khó, thầy giảng chậm và kỹ. Giảng xong, thầy hay hỏi trò đã hiểu chưa; chừng nào học trò nói hiểu rồi, thầy mới chuyển sang ý khác. Người thầy ấy không vội vàng cho xong bài, mà chờ đến khi cả lớp cùng theo kịp.\n\nThầy cũng nổi tiếng công bằng. Ở Dục Thanh, học trò được chấm bằng công điểm. Học trò cũ kể rằng thầy Thành dùng công điểm rất công bằng và không dùng nó để phạt trò. Khi trò tiến bộ, thầy khen ngợi; khi trò mắc lỗi, thầy ân cần chỉ bảo. Với những học trò nhỏ, người thầy hai mươi tuổi vừa nghiêm vừa gần gũi như một người bạn lớn. Chính sự kiên nhẫn và công bằng ấy khiến các cụ, mấy chục năm sau, vẫn nhớ rõ từng nét trong cách dạy của thầy.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh_noi_bac_ho_day_o_truong_duc_tha.jpg","chu_thich":"Gian nhà nơi thầy Nguyễn Tất Thành dạy học ở Trường Dục Thanh (ảnh chụp ngày 27/8/2016). Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons","credit":"Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Giờ thể dục không có dụng cụ","text":"Môn thể dục là nét mới nhất trong chương trình Dục Thanh. Với lối học cũ, người học trò chủ yếu ngồi đọc sách, viết chữ. Các nhà Duy Tân muốn đào tạo những người trẻ khỏe cả thân thể lẫn trí tuệ, nên đưa thể dục vào dạy trong nhà trường. Môn học này chưa có giờ lý thuyết, chủ yếu thực hành trên sân bãi, và việc tập luyện cũng được tính bằng công điểm.\n\nKhó khăn lớn nhất là trường thiếu thốn cơ sở vật chất. Không có hố nhảy, cũng không có dụng cụ chuyên dùng. Thầy Thành cùng học trò tự lao động làm sân bãi. Với môn nhảy cao, thay vì nhảy qua xà như ngày nay, thầy cho đào một cái hố để học trò nhảy từ dưới lên. Khi trò đã quen, hố được đào sâu thêm để nâng dần độ khó. Chi tiết nhỏ ấy cho thấy một người thầy năng động, biết xoay xở với những gì sẵn có. Nó cũng phản chiếu tinh thần tự lực của cả ngôi trường, vốn được nuôi bằng chính sức lao động của những người yêu nước.","doc":7},{"loai":"ban_co_biet","text":"Giữa lớp học phục dựng có một bộ họa đàn trường kỷ, nơi các thầy ngồi giảng bài và chấm bài. Bộ trường kỷ ấy nằm trong số hiện vật gốc còn được lưu giữ từ thời thầy Thành dạy học ở Dục Thanh.","nguon_ten":"Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành; Báo Quân khu 7 – Trường Dục Thanh những ngày tháng Năm","doc":8},{"loai":"doan","tieu_de":"Mỗi bài học là một bài học yêu nước","text":"Bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, đã tập hợp lời kể của các học trò cũ. Theo đó, tất cả những bài giảng của thầy Thành mà các cụ còn nhớ đều nhằm giáo dục lòng yêu quê hương, đất nước. Thầy không dạy chữ đơn thuần. Cùng với con chữ, thầy truyền cho học trò lòng yêu quê hương, đất nước, nòi giống tổ tiên. Điều đó hợp với tinh thần của chính ngôi trường, vốn ra đời để khai dân trí, chấn dân khí.\n\nChữ Quốc ngữ khi ấy cũng không chỉ là một môn học. Các nhà Duy Tân coi đó là công cụ để mở mang hiểu biết cho số đông, vì dễ học hơn chữ Hán rất nhiều. Học trò biết chữ Quốc ngữ có thể tự đọc sách báo mới, hiểu chuyện trong nước và ngoài nước. Ngoài giờ lên lớp, thầy còn đưa học trò đi thăm cảnh vật, các xóm chài quanh Phan Thiết (xem chuyên đề Sông Cà Ty, Phan Thiết). Trong lớp hay ngoài lớp, bài học chung vẫn là một: học để hiểu biết, và học để biết yêu quê hương, đất nước, con người.","doc":9},{"loai":"anh","src":"textures/bang_w/G03_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Lớp học hôm nay","text":"Lớp học du khách thấy hôm nay được phục dựng theo lời kể và bản vẽ phác họa của bốn học trò cũ của thầy Thành (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ba dãy bàn ghế học trò, hai tấm bảng đen và bộ họa đàn trường kỷ nơi thầy ngồi giảng bài được bày lại như xưa (xem chuyên đề Lớp học Trường Dục Thanh). Khách tham quan có thể ngồi vào chỗ của học trò, nghe thuyết minh viên kể về một ngày học năm 1910.\n\nNhiều trường học chọn nơi đây để tổ chức sinh hoạt truyền thống nhân Ngày Nhà giáo Việt Nam. Trong không gian ấy, những chi tiết như giờ thể dục lúc sáng sớm, bài ca ái quốc đầu giờ, buổi thuyết trình tối thứ năm hay hố nhảy cao đào sâu dần giúp học trò hôm nay thấy thầy Thành thật gần gũi. Các em không chỉ học về một vị lãnh tụ, mà còn gặp lại một thầy giáo trẻ tận tâm, sáng tạo, luôn muốn trò mình hiểu bài và biết yêu nước.","doc":10},{"loai":"anh","src":"textures/bang_w/G03_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp”, nhìn từ trên cao."}],"nguon":["Báo Văn hóa – Kỳ 1: Về Dục Thanh nghe kể chuyện Bác Hồ dạy học – https://baovanhoa.vn/van-hoa/ky-1-ve-duc-thanh-nghe-ke-chuyen-bac-ho-day-hoc-255667.html","Thanh Niên – Thầy Thành ở trường Dục Thanh – https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm","Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành – https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html","VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành – https://giaoducthoidai.vn/noi-luu-dau-cua-thay-giao-nguyen-tat-thanh-post671585.html","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh – https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm"],"doc":[{"t":"Một ngày ở lớp nhì Dục Thanh: thầy Thành dạy gì và dạy thế nào?. Sáu giờ sáng, giờ học ở Trường Dục Thanh đã bắt đầu, sau buổi tập thể dục ngoài sân. Trong ngôi nhà gỗ chung của cả bốn lớp, một thầy giáo hai mươi tuổi giảng chậm những bài khó và kiên nhẫn hỏi lại từng trò. Mấy chục năm sau, học trò cũ vẫn nhớ từng nét trong cách dạy ấy. Một ngày học ở Dục Thanh năm 1910 diễn ra như thế nào?"},{"t":"Một mái nhà cho bốn lớp học. Tấm ảnh do Bùi Thụy Đào Nguyên chụp bên trong lớp học của Trường Dục Thanh, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 3.0. Không gian ấy được phục dựng trong những năm 1978–1980, theo lời kể của chính những học trò từng ngồi học ở đây năm 1910. Vì vậy, nhìn vào lớp học, ta có thể hình dung khá sát một ngày học của thầy trò Dục Thanh hơn một thế kỷ trước. Điều đầu tiên cần biết là trường không chia thành từng phòng riêng. Cả bốn lớp Tư, Ba, Nhì, Nhất cùng học trong một ngôi nhà chung. Lúc đông nhất, trường có khoảng sáu mươi học trò, trong đó có bốn nữ sinh, một chi tiết đáng chú ý ở thời ấy. Trong bốn bậc lớp, lớp nhì là bậc thứ ba, chỉ đứng sau lớp nhất. Trường có khoảng bảy thầy giáo, ông Nguyễn Quý Anh, con trai nhà thơ Nguyễn Thông, làm hiệu trưởng. Trẻ nhất trong các thầy là Nguyễn Tất Thành, vừa tròn hai mươi tuổi, được giao phụ trách lớp nhì."},{"t":"Sáu giờ sáng, giờ thể dục. Nội quy của trường rất nghiêm. Hằng ngày, giờ học bắt đầu từ sáu giờ sáng, đến năm giờ chiều mới tan. Buổi sáng, học trò tập thể dục trước, rồi xếp hàng thật ngay ngắn đi vào lớp. Theo tài liệu của PGS.TS Trần Thị Thu Hương, Viện Lịch sử Đảng, sáng nào thầy Thành cũng dậy sớm và gọi mọi người ra sân tập. Thầy ở nội trú ngay trong khuôn viên trường, nên giờ thể dục buổi sớm gắn liền với nếp sinh hoạt hằng ngày của thầy. Vào lớp, học trò khoanh tay trước ngực, cùng hát một bài ca ái quốc dựa theo bài thơ yêu nước Phan Châu Trinh viết năm 1907. Đó là bài mỗi học trò phải thuộc lòng. Thầy Thành còn đem những bài ca của phong trào Duy Tân phổ biến cho thầy trò trong trường. Một ngày học vì thế mở đầu không phải bằng con chữ, mà bằng sức khỏe và lời ca về đất nước. Cách mở đầu ấy nói lên mục đích của ngôi trường: đào tạo những người trẻ vừa khỏe mạnh, vừa hiểu biết, vừa biết yêu nước."},{"t":"Chương trình theo khuôn Đông Kinh Nghĩa Thục. Nội dung học ở Dục Thanh dựa theo mô hình Đông Kinh Nghĩa Thục ở Hà Nội, có cải biến cho hợp với thực tế Bình Thuận để tránh bị thực dân đàn áp. Theo Báo Cần Thơ, chương trình giảng dạy do Đông Kinh Nghĩa Thục biên khảo, chú giải rồi gửi vào Phan Thiết. Chữ Quốc ngữ là môn chính, bên cạnh chữ Hán và tiếng Pháp. Khi ấy, phần đông con em vẫn theo lối học khoa cử nặng về kinh sử chữ Hán, còn trường Pháp – Việt do chính quyền thuộc địa quản lý. Một trường tư lấy chữ Quốc ngữ làm gốc là một lựa chọn mới mẻ và mạnh dạn. Trường còn có một nếp sinh hoạt rất riêng. Tối thứ năm hằng tuần, học trò lớp nhất và lớp nhì luân phiên chuẩn bị trước một đề tài, rồi đứng lên thuyết trình bằng tiếng Việt trước tập thể. Học trò lớp nhì của thầy Thành vì thế không chỉ học đọc, học viết, mà còn tập nói trước đông người. Nhận xét về chất lượng và xu hướng mới của Dục Thanh, nhiều nhà nghiên cứu cho rằng ở Phan Thiết khi ấy có một trường tư thục vào loại tiến bộ nhất Việt Nam."},{"t":"Bạn có biết? Các học trò cũ nhớ thầy Thành đã ăn hai cái Tết ở Phan Thiết: Tết Trung thu năm Canh Tuất, ngày 18/9/1910, và Tết Nguyên đán Tân Hợi, ngày 30/1/1911. Nhà nghiên cứu Ngô Thị Mùi dựa vào chi tiết ấy để xác định thầy có mặt ở Dục Thanh từ tháng 9/1910 đến tháng 2/1911."},{"t":"Thầy giáo trẻ nhất trường nhận lớp nhì. Theo phần lớn tư liệu, ở lớp nhì thầy Thành chủ yếu dạy chữ Quốc ngữ và chữ Hán, kiêm môn thể dục. Khi thầy giáo Pháp văn vắng mặt, thầy dạy thay tiếng Pháp. Cũng có tư liệu ghi thầy phụ trách thể dục là chính, trợ giảng ba môn Quốc ngữ, Hán văn, Pháp văn, và đứng lớp thay khi các thầy khác nghỉ bệnh hay bận việc. Hai cách ghi chép cùng cho thấy một người thầy trẻ được nhà trường tin cậy, có thể đảm đương nhiều việc. PGS.TS Trần Thị Thu Hương nghiêng về khả năng thầy dạy Quốc ngữ và Hán văn, bởi thầy lớn lên trong một gia đình khoa bảng, Nho học. Vốn chữ Hán thầy có từ những năm học với cha và thầy đồ Vương Thúc Quý ở quê nhà Nghệ An. Chữ Quốc ngữ và tiếng Pháp thầy học ở các trường Pháp – Việt, ở Trường Quốc Học Huế, rồi học thêm tiếng Pháp ở Quy Nhơn. Một người vừa thông chữ Hán, vừa đọc được sách Pháp như thế là vốn quý với một trường tư ở tỉnh lẻ."},{"t":"Bài khó thì giảng chậm. Cách dạy của thầy Thành được biết đến chủ yếu qua lời kể của các học trò cũ như cụ Nguyễn Quý Phầu và cụ Nguyễn Đăng Lầu. Các cụ nhớ thầy giảng bài rất nhiệt tình, dễ hiểu. Những bài khó, thầy giảng chậm và kỹ. Giảng xong, thầy hay hỏi trò đã hiểu chưa; chừng nào học trò nói hiểu rồi, thầy mới chuyển sang ý khác. Người thầy ấy không vội vàng cho xong bài, mà chờ đến khi cả lớp cùng theo kịp. Thầy cũng nổi tiếng công bằng. Ở Dục Thanh, học trò được chấm bằng công điểm. Học trò cũ kể rằng thầy Thành dùng công điểm rất công bằng và không dùng nó để phạt trò. Khi trò tiến bộ, thầy khen ngợi; khi trò mắc lỗi, thầy ân cần chỉ bảo. Với những học trò nhỏ, người thầy hai mươi tuổi vừa nghiêm vừa gần gũi như một người bạn lớn. Chính sự kiên nhẫn và công bằng ấy khiến các cụ, mấy chục năm sau, vẫn nhớ rõ từng nét trong cách dạy của thầy."},{"t":"Giờ thể dục không có dụng cụ. Môn thể dục là nét mới nhất trong chương trình Dục Thanh. Với lối học cũ, người học trò chủ yếu ngồi đọc sách, viết chữ. Các nhà Duy Tân muốn đào tạo những người trẻ khỏe cả thân thể lẫn trí tuệ, nên đưa thể dục vào dạy trong nhà trường. Môn học này chưa có giờ lý thuyết, chủ yếu thực hành trên sân bãi, và việc tập luyện cũng được tính bằng công điểm. Khó khăn lớn nhất là trường thiếu thốn cơ sở vật chất. Không có hố nhảy, cũng không có dụng cụ chuyên dùng. Thầy Thành cùng học trò tự lao động làm sân bãi. Với môn nhảy cao, thay vì nhảy qua xà như ngày nay, thầy cho đào một cái hố để học trò nhảy từ dưới lên. Khi trò đã quen, hố được đào sâu thêm để nâng dần độ khó. Chi tiết nhỏ ấy cho thấy một người thầy năng động, biết xoay xở với những gì sẵn có. Nó cũng phản chiếu tinh thần tự lực của cả ngôi trường, vốn được nuôi bằng chính sức lao động của những người yêu nước."},{"t":"Bạn có biết? Giữa lớp học phục dựng có một bộ họa đàn trường kỷ, nơi các thầy ngồi giảng bài và chấm bài. Bộ trường kỷ ấy nằm trong số hiện vật gốc còn được lưu giữ từ thời thầy Thành dạy học ở Dục Thanh."},{"t":"Mỗi bài học là một bài học yêu nước. Bà Ngô Thị Mùi, khi ấy là Phó giám đốc Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, đã tập hợp lời kể của các học trò cũ. Theo đó, tất cả những bài giảng của thầy Thành mà các cụ còn nhớ đều nhằm giáo dục lòng yêu quê hương, đất nước. Thầy không dạy chữ đơn thuần. Cùng với con chữ, thầy truyền cho học trò lòng yêu quê hương, đất nước, nòi giống tổ tiên. Điều đó hợp với tinh thần của chính ngôi trường, vốn ra đời để khai dân trí, chấn dân khí. Chữ Quốc ngữ khi ấy cũng không chỉ là một môn học. Các nhà Duy Tân coi đó là công cụ để mở mang hiểu biết cho số đông, vì dễ học hơn chữ Hán rất nhiều. Học trò biết chữ Quốc ngữ có thể tự đọc sách báo mới, hiểu chuyện trong nước và ngoài nước. Ngoài giờ lên lớp, thầy còn đưa học trò đi thăm cảnh vật, các xóm chài quanh Phan Thiết (xem chuyên đề Sông Cà Ty, Phan Thiết). Trong lớp hay ngoài lớp, bài học chung vẫn là một: học để hiểu biết, và học để biết yêu quê hương, đất nước, con người."},{"t":"Lớp học hôm nay. Lớp học du khách thấy hôm nay được phục dựng theo lời kể và bản vẽ phác họa của bốn học trò cũ của thầy Thành (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ba dãy bàn ghế học trò, hai tấm bảng đen và bộ họa đàn trường kỷ nơi thầy ngồi giảng bài được bày lại như xưa (xem chuyên đề Lớp học Trường Dục Thanh). Khách tham quan có thể ngồi vào chỗ của học trò, nghe thuyết minh viên kể về một ngày học năm 1910. Nhiều trường học chọn nơi đây để tổ chức sinh hoạt truyền thống nhân Ngày Nhà giáo Việt Nam. Trong không gian ấy, những chi tiết như giờ thể dục lúc sáng sớm, bài ca ái quốc đầu giờ, buổi thuyết trình tối thứ năm hay hố nhảy cao đào sâu dần giúp học trò hôm nay thấy thầy Thành thật gần gũi. Các em không chỉ học về một vị lãnh tụ, mà còn gặp lại một thầy giáo trẻ tận tâm, sáng tạo, luôn muốn trò mình hiểu bài và biết yêu nước."}],"so_chu":1738},{"i":6,"tieu_de_bang":"Gian nhà nơi Bác Hồ dạy học ở Dục Thanh","tieu_de":"Từ bục giảng Dục Thanh đến sự nghiệp “trồng người”","sapo":"Tấm ảnh chụp một ngày cuối tháng 8/2016 cho thấy gian nhà gỗ nơi thầy Thành từng đứng lớp. Người thầy trẻ ấy chỉ dạy ở đây chưa đầy nửa năm. Nhưng việc dạy người thì Người theo đuổi suốt đời: từ lớp huấn luyện ở Quảng Châu, lớp học ở Pác Bó, đến chiến dịch diệt giặc dốt của cả một dân tộc vừa giành độc lập.","bia":{"src":"textures/ht/ht_anh_truong_duc_thanh_noi_bac_ho_day_o_truong_duc_tha.jpg","credit":"Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Gian nhà trong ảnh","text":"Tấm ảnh do Phương Huy chụp ngày 27/8/2016, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 4.0. Ảnh ghi lại gian nhà gỗ nơi thầy Nguyễn Tất Thành dạy học từ tháng 9/1910 đến tháng 2/1911. Gian nhà ấy nay thuộc khu di tích Trường Dục Thanh, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận quản lý, ở số 39 đường Trưng Nhị, phường Phan Thiết, tỉnh Lâm Đồng. Mỗi năm, hàng vạn lượt học sinh, đoàn viên và du khách tìm về đây.\n\nĐiều làm gian nhà nhỏ này trở nên đặc biệt không nằm ở kiến trúc. Nó nằm ở chỗ đây là nơi lưu dấu quãng thời gian Chủ tịch Hồ Chí Minh làm thầy giáo, đứng trên bục giảng dạy chữ cho trẻ em. Quãng thời gian ấy chưa đầy nửa năm. Nhưng trong cuộc đời hoạt động của Người, việc dạy người còn lặp lại nhiều lần, dưới nhiều hình thức, với những lớp học ngày càng rộng lớn. Gian nhà gỗ ở Phan Thiết là một điểm khởi đầu của sợi chỉ xuyên suốt ấy.","doc":1},{"loai":"doan","tieu_de":"Thầy giáo trẻ nhất trường","text":"Năm 1910, Nguyễn Tất Thành là thầy giáo trẻ nhất của Trường Dục Thanh, vừa tròn hai mươi tuổi. TS Trần Viết Lưu, Ban Tuyên giáo Trung ương, nhận xét rằng thầy dạy học ở Phan Thiết nhưng không coi đó là kế mưu sinh, cũng không coi là sự nghiệp. Với người thanh niên đang ấp ủ chí lớn, Phan Thiết là chặng dừng chân trước chuyến đi xa. Vậy mà thầy vẫn dạy hết lòng, và lồng vào từng bài học tinh thần yêu nước để truyền cho học trò nhỏ.\n\nTheo tư liệu của Bảo tàng Hồ Chí Minh, các học trò cũ nhớ nhất ở thầy ba điều. Đó là thương yêu, gần gũi học sinh; chịu khó tìm tòi, học hỏi, đọc sách báo; và luôn hòa đồng với cuộc sống của người lao động nghèo Phan Thiết. Ba điều ấy về sau trở thành những nét quen thuộc ở Chủ tịch Hồ Chí Minh: yêu trẻ, ham học suốt đời và gần dân. Cách thầy giảng bài ở lớp nhì, với những câu hỏi kiên nhẫn xem trò đã hiểu chưa, được kể kỹ trong chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp.","doc":2},{"loai":"anh","src":"textures/bang_w/G03_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Gian nhà nơi Bác Hồ dạy học ở Dục Thanh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người thầy của những người cách mạng","text":"Rời Dục Thanh, người thầy giáo trẻ vào Sài Gòn, rồi ngày 5/6/1911 rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville. Mười bốn năm sau, người thanh niên năm xưa, khi ấy là Nguyễn Ái Quốc, lại đứng lớp. Từ năm 1925 đến năm 1927, tại Quảng Châu, Trung Quốc, Người trực tiếp mở các lớp huấn luyện chính trị cho thanh niên Việt Nam, đào tạo cán bộ cho Hội Việt Nam Cách mạng Thanh niên. Những bài giảng ấy được tập hợp, in thành cuốn Đường Kách mệnh năm 1927.\n\nCuốn sách được viết ngắn gọn, giản dị, để người mới học cũng hiểu được. Người thầy từng kiên nhẫn hỏi học trò lớp nhì đã hiểu bài chưa, nay soạn bài giảng sao cho người thợ, người nông dân đọc cũng hiểu. Năm 1941, về nước ở Pác Bó, Cao Bằng, Người lại mở lớp huấn luyện cán bộ. Theo hồi ký của Đại tướng Võ Nguyên Giáp, khi đọc Tuyên ngôn Độc lập ngày 2/9/1945, Người dừng lại hỏi: “Tôi nói, đồng bào nghe rõ không?”. Câu hỏi giản dị ấy gợi nhớ nếp quen của thầy giáo Dục Thanh năm nào.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","chu_thich":"Bên trong lớp học Trường Dục Thanh, nơi thầy Thành đứng lớp năm 1910. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Diệt giặc dốt","text":"Tháng 9/1945, người thầy giáo năm xưa đứng đầu Nhà nước Việt Nam Dân chủ Cộng hòa. Khi ấy, khoảng 95% dân số mù chữ. Theo thống kê thời kỳ đó, cứ một trăm người chỉ có ba trẻ em đi học và hai người lớn biết chữ. Tại phiên họp đầu tiên của Chính phủ ngày 3/9/1945, Người nêu sáu nhiệm vụ cấp bách, trong đó chống nạn mù chữ đứng thứ hai, chỉ sau chống nạn đói. Người nói: “Một dân tộc dốt là một dân tộc yếu”. Từ nhận thức ấy, chống giặc dốt được đặt ngang hàng với chống giặc đói và giặc ngoại xâm.\n\nNgày 8/9/1945, Chủ tịch Hồ Chí Minh ký ba sắc lệnh số 17, 19 và 20. Sắc lệnh 17 lập Nha Bình dân học vụ. Sắc lệnh 19 quy định trong sáu tháng, làng nào, thị trấn nào cũng phải có lớp học bình dân. Sắc lệnh 20 định rằng việc học chữ Quốc ngữ là bắt buộc và không mất tiền. Ngày 4/10/1945, Người ra lời kêu gọi chống nạn thất học. Người viết rằng muốn giữ vững nền độc lập, làm cho dân mạnh nước giàu, mọi người Việt Nam trước hết phải biết đọc, biết viết chữ Quốc ngữ. Người đã biết chữ hãy dạy cho người chưa biết chữ; người chưa biết chữ hãy gắng sức mà học. Ngày 8/10/1945, Người dự khai mạc lớp huấn luyện cán bộ bình dân học vụ khóa đầu tiên, mang tên Hồ Chí Minh, tại Hà Nội.","doc":4},{"loai":"ban_co_biet","text":"Chỉ trong một năm, từ tháng 8/1945 đến tháng 8/1946, phong trào Bình dân học vụ đã xóa mù chữ cho hơn 2,5 triệu người, với gần 96.000 giáo viên và gần 75.000 lớp học. Phần lớn người dạy làm việc không lương.","nguon_ten":"Việt Nam chống nạn thất học, NXB Giáo dục, 1980; dẫn theo VnExpress – Phong trào bình dân học vụ 75 năm trước","doc":5},{"loai":"doan","tieu_de":"Lá thư gửi học trò ngày khai trường","text":"Cũng tháng 9/1945, nhân ngày khai trường đầu tiên của nước Việt Nam độc lập, Chủ tịch Hồ Chí Minh viết thư gửi các học sinh. Người nói với các em rằng từ nay, các em được hưởng một nền giáo dục của một nước độc lập, điều cha anh các em chưa từng có. Người nhắc rằng sau tám mươi năm nô lệ, nước nhà cần được xây dựng lại, và việc ấy trông cậy rất nhiều vào lớp trẻ đang ngồi trên ghế nhà trường.\n\nLá thư ngắn, lời lẽ ân cần như lời một người thầy dặn học trò trước năm học mới. Đọc lại, ta dễ nhận ra giọng của người từng đứng lớp nhì ở Dục Thanh: vừa nghiêm, vừa gần gũi, vừa gửi gắm niềm tin. Ba mươi lăm năm trước, thầy Thành dạy học trò Phan Thiết học chữ để biết yêu quê hương, đất nước. Giờ đây, trên cương vị Chủ tịch nước, Người đặt vào tay cả một thế hệ học sinh trách nhiệm làm cho non sông tươi đẹp. Câu văn sau đây về sau trở nên quen thuộc với nhiều thế hệ học trò Việt Nam.","doc":6},{"loai":"trich","text":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Thư gửi các học sinh nhân ngày khai trường, tháng 9/1945 – Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia, 2011","doc":7},{"loai":"doan","tieu_de":"Vì lợi ích trăm năm","text":"Ngày 13/9/1958, Người nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc. Tại đây, Người nói câu về sau trở thành phương châm của ngành giáo dục: “Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người”. Câu nói mượn ý người xưa, nhưng được Người đặt vào hoàn cảnh một đất nước đang xây dựng lại sau chiến tranh. Trồng người là việc lâu dài, cần sự kiên nhẫn của cả xã hội, và trước hết của người thầy.\n\nNhìn lại, có thể thấy một sợi chỉ xuyên suốt. Ở Dục Thanh, thầy Thành dạy chữ cho những học trò nhỏ của lớp nhì. Ở Quảng Châu, Người đào tạo những cán bộ cách mạng đầu tiên. Năm 1945, Người phát động cả một dân tộc đi học. Năm 1958, Người nói với các thầy cô giáo về sự nghiệp trồng người. Gian nhà gỗ ở Phan Thiết vì thế không chỉ là nơi Người từng dạy học. Đó là nơi gợi nhớ những ngày đầu của một tư tưởng giáo dục lớn, theo Người suốt cuộc đời.","doc":8},{"loai":"anh","src":"textures/bang_w/G03_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Gian nhà nơi Bác Hồ dạy học ở Dục Thanh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, gian nhà gỗ trong ảnh là điểm dừng chân quen thuộc của những chuyến về nguồn. Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận thường tổ chức tại đây lễ báo công, lễ kết nạp Đội, Đoàn, Đảng và các buổi giao lưu chuyên đề Thăm trường xưa nhớ Bác. Dịp Ngày Nhà giáo Việt Nam, nhiều trường học về đây sinh hoạt truyền thống. Trong lớp học, khách có thể ngồi vào bàn học trò, nghe kể về người thầy giáo trẻ năm 1910.\n\nNgôi trường cũng đi vào thơ ca. Nhà thơ Giang Nam có bài Thăm trường xưa Bác dạy. Nhà thơ Huy Cận ghi lại cảm xúc khi về thăm Dục Thanh trong bài Những cột buồm cao. Tháng 5/2010, bảo tàng tổ chức một hội thảo khoa học với hàng trăm đại biểu là các nhà sử học, nhà nghiên cứu. Dịp ấy đánh dấu 120 năm Ngày sinh của Người và 100 năm ngày Người dừng chân dạy học ở Dục Thanh. Hơn một thế kỷ trôi qua, gian nhà gỗ vẫn làm nhiệm vụ của một lớp học: dạy người đến sau về lòng yêu nước và niềm tin vào việc học.","doc":9},{"loai":"ban_co_biet","text":"Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua nghị quyết kỷ niệm 100 năm Ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990, tôn vinh Người là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam.","nguon_ten":"Nghị quyết 24C/18.65 của Đại hội đồng UNESCO, 1987","doc":10},{"loai":"anh","src":"textures/bang_w/G03_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Gian nhà nơi Bác Hồ dạy học ở Dục Thanh”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh Toàn tập, tập 4 và tập 11, NXB Chính trị quốc gia, 2011","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh – https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm","Thanh Niên – Thầy Thành ở trường Dục Thanh – https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm","VnExpress – Phong trào bình dân học vụ 75 năm trước – https://vnexpress.net/phong-trao-binh-dan-hoc-vu-75-nam-truoc-4166631.html","Giáo dục & Thời đại – Ký ức thời diệt giặc dốt – https://giaoducthoidai.vn/ky-uc-thoi-diet-giac-dot-post650423.html"],"doc":[{"t":"Từ bục giảng Dục Thanh đến sự nghiệp “trồng người”. Tấm ảnh chụp một ngày cuối tháng 8/2016 cho thấy gian nhà gỗ nơi thầy Thành từng đứng lớp. Người thầy trẻ ấy chỉ dạy ở đây chưa đầy nửa năm. Nhưng việc dạy người thì Người theo đuổi suốt đời: từ lớp huấn luyện ở Quảng Châu, lớp học ở Pác Bó, đến chiến dịch diệt giặc dốt của cả một dân tộc vừa giành độc lập."},{"t":"Gian nhà trong ảnh. Tấm ảnh do Phương Huy chụp ngày 27/8/2016, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 4.0. Ảnh ghi lại gian nhà gỗ nơi thầy Nguyễn Tất Thành dạy học từ tháng 9/1910 đến tháng 2/1911. Gian nhà ấy nay thuộc khu di tích Trường Dục Thanh, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận quản lý, ở số 39 đường Trưng Nhị, phường Phan Thiết, tỉnh Lâm Đồng. Mỗi năm, hàng vạn lượt học sinh, đoàn viên và du khách tìm về đây. Điều làm gian nhà nhỏ này trở nên đặc biệt không nằm ở kiến trúc. Nó nằm ở chỗ đây là nơi lưu dấu quãng thời gian Chủ tịch Hồ Chí Minh làm thầy giáo, đứng trên bục giảng dạy chữ cho trẻ em. Quãng thời gian ấy chưa đầy nửa năm. Nhưng trong cuộc đời hoạt động của Người, việc dạy người còn lặp lại nhiều lần, dưới nhiều hình thức, với những lớp học ngày càng rộng lớn. Gian nhà gỗ ở Phan Thiết là một điểm khởi đầu của sợi chỉ xuyên suốt ấy."},{"t":"Thầy giáo trẻ nhất trường. Năm 1910, Nguyễn Tất Thành là thầy giáo trẻ nhất của Trường Dục Thanh, vừa tròn hai mươi tuổi. TS Trần Viết Lưu, Ban Tuyên giáo Trung ương, nhận xét rằng thầy dạy học ở Phan Thiết nhưng không coi đó là kế mưu sinh, cũng không coi là sự nghiệp. Với người thanh niên đang ấp ủ chí lớn, Phan Thiết là chặng dừng chân trước chuyến đi xa. Vậy mà thầy vẫn dạy hết lòng, và lồng vào từng bài học tinh thần yêu nước để truyền cho học trò nhỏ. Theo tư liệu của Bảo tàng Hồ Chí Minh, các học trò cũ nhớ nhất ở thầy ba điều. Đó là thương yêu, gần gũi học sinh; chịu khó tìm tòi, học hỏi, đọc sách báo; và luôn hòa đồng với cuộc sống của người lao động nghèo Phan Thiết. Ba điều ấy về sau trở thành những nét quen thuộc ở Chủ tịch Hồ Chí Minh: yêu trẻ, ham học suốt đời và gần dân. Cách thầy giảng bài ở lớp nhì, với những câu hỏi kiên nhẫn xem trò đã hiểu chưa, được kể kỹ trong chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp."},{"t":"Người thầy của những người cách mạng. Rời Dục Thanh, người thầy giáo trẻ vào Sài Gòn, rồi ngày 5/6/1911 rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville. Mười bốn năm sau, người thanh niên năm xưa, khi ấy là Nguyễn Ái Quốc, lại đứng lớp. Từ năm 1925 đến năm 1927, tại Quảng Châu, Trung Quốc, Người trực tiếp mở các lớp huấn luyện chính trị cho thanh niên Việt Nam, đào tạo cán bộ cho Hội Việt Nam Cách mạng Thanh niên. Những bài giảng ấy được tập hợp, in thành cuốn Đường Kách mệnh năm 1927. Cuốn sách được viết ngắn gọn, giản dị, để người mới học cũng hiểu được. Người thầy từng kiên nhẫn hỏi học trò lớp nhì đã hiểu bài chưa, nay soạn bài giảng sao cho người thợ, người nông dân đọc cũng hiểu. Năm 1941, về nước ở Pác Bó, Cao Bằng, Người lại mở lớp huấn luyện cán bộ. Theo hồi ký của Đại tướng Võ Nguyên Giáp, khi đọc Tuyên ngôn Độc lập ngày 2/9/1945, Người dừng lại hỏi: “Tôi nói, đồng bào nghe rõ không?”. Câu hỏi giản dị ấy gợi nhớ nếp quen của thầy giáo Dục Thanh năm nào."},{"t":"Diệt giặc dốt. Tháng 9/1945, người thầy giáo năm xưa đứng đầu Nhà nước Việt Nam Dân chủ Cộng hòa. Khi ấy, khoảng 95% dân số mù chữ. Theo thống kê thời kỳ đó, cứ một trăm người chỉ có ba trẻ em đi học và hai người lớn biết chữ. Tại phiên họp đầu tiên của Chính phủ ngày 3/9/1945, Người nêu sáu nhiệm vụ cấp bách, trong đó chống nạn mù chữ đứng thứ hai, chỉ sau chống nạn đói. Người nói: “Một dân tộc dốt là một dân tộc yếu”. Từ nhận thức ấy, chống giặc dốt được đặt ngang hàng với chống giặc đói và giặc ngoại xâm. Ngày 8/9/1945, Chủ tịch Hồ Chí Minh ký ba sắc lệnh số 17, 19 và 20. Sắc lệnh 17 lập Nha Bình dân học vụ. Sắc lệnh 19 quy định trong sáu tháng, làng nào, thị trấn nào cũng phải có lớp học bình dân. Sắc lệnh 20 định rằng việc học chữ Quốc ngữ là bắt buộc và không mất tiền. Ngày 4/10/1945, Người ra lời kêu gọi chống nạn thất học. Người viết rằng muốn giữ vững nền độc lập, làm cho dân mạnh nước giàu, mọi người Việt Nam trước hết phải biết đọc, biết viết chữ Quốc ngữ. Người đã biết chữ hãy dạy cho người chưa biết chữ; người chưa biết chữ hãy gắng sức mà học. Ngày 8/10/1945, Người dự khai mạc lớp huấn luyện cán bộ bình dân học vụ khóa đầu tiên, mang tên Hồ Chí Minh, tại Hà Nội."},{"t":"Bạn có biết? Chỉ trong một năm, từ tháng 8/1945 đến tháng 8/1946, phong trào Bình dân học vụ đã xóa mù chữ cho hơn 2,5 triệu người, với gần 96.000 giáo viên và gần 75.000 lớp học. Phần lớn người dạy làm việc không lương."},{"t":"Lá thư gửi học trò ngày khai trường. Cũng tháng 9/1945, nhân ngày khai trường đầu tiên của nước Việt Nam độc lập, Chủ tịch Hồ Chí Minh viết thư gửi các học sinh. Người nói với các em rằng từ nay, các em được hưởng một nền giáo dục của một nước độc lập, điều cha anh các em chưa từng có. Người nhắc rằng sau tám mươi năm nô lệ, nước nhà cần được xây dựng lại, và việc ấy trông cậy rất nhiều vào lớp trẻ đang ngồi trên ghế nhà trường. Lá thư ngắn, lời lẽ ân cần như lời một người thầy dặn học trò trước năm học mới. Đọc lại, ta dễ nhận ra giọng của người từng đứng lớp nhì ở Dục Thanh: vừa nghiêm, vừa gần gũi, vừa gửi gắm niềm tin. Ba mươi lăm năm trước, thầy Thành dạy học trò Phan Thiết học chữ để biết yêu quê hương, đất nước. Giờ đây, trên cương vị Chủ tịch nước, Người đặt vào tay cả một thế hệ học sinh trách nhiệm làm cho non sông tươi đẹp. Câu văn sau đây về sau trở nên quen thuộc với nhiều thế hệ học trò Việt Nam."},{"t":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em. — Chủ tịch Hồ Chí Minh"},{"t":"Vì lợi ích trăm năm. Ngày 13/9/1958, Người nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc. Tại đây, Người nói câu về sau trở thành phương châm của ngành giáo dục: “Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người”. Câu nói mượn ý người xưa, nhưng được Người đặt vào hoàn cảnh một đất nước đang xây dựng lại sau chiến tranh. Trồng người là việc lâu dài, cần sự kiên nhẫn của cả xã hội, và trước hết của người thầy. Nhìn lại, có thể thấy một sợi chỉ xuyên suốt. Ở Dục Thanh, thầy Thành dạy chữ cho những học trò nhỏ của lớp nhì. Ở Quảng Châu, Người đào tạo những cán bộ cách mạng đầu tiên. Năm 1945, Người phát động cả một dân tộc đi học. Năm 1958, Người nói với các thầy cô giáo về sự nghiệp trồng người. Gian nhà gỗ ở Phan Thiết vì thế không chỉ là nơi Người từng dạy học. Đó là nơi gợi nhớ những ngày đầu của một tư tưởng giáo dục lớn, theo Người suốt cuộc đời."},{"t":"Dấu tích hôm nay. Ngày nay, gian nhà gỗ trong ảnh là điểm dừng chân quen thuộc của những chuyến về nguồn. Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận thường tổ chức tại đây lễ báo công, lễ kết nạp Đội, Đoàn, Đảng và các buổi giao lưu chuyên đề Thăm trường xưa nhớ Bác. Dịp Ngày Nhà giáo Việt Nam, nhiều trường học về đây sinh hoạt truyền thống. Trong lớp học, khách có thể ngồi vào bàn học trò, nghe kể về người thầy giáo trẻ năm 1910. Ngôi trường cũng đi vào thơ ca. Nhà thơ Giang Nam có bài Thăm trường xưa Bác dạy. Nhà thơ Huy Cận ghi lại cảm xúc khi về thăm Dục Thanh trong bài Những cột buồm cao. Tháng 5/2010, bảo tàng tổ chức một hội thảo khoa học với hàng trăm đại biểu là các nhà sử học, nhà nghiên cứu. Dịp ấy đánh dấu 120 năm Ngày sinh của Người và 100 năm ngày Người dừng chân dạy học ở Dục Thanh. Hơn một thế kỷ trôi qua, gian nhà gỗ vẫn làm nhiệm vụ của một lớp học: dạy người đến sau về lòng yêu nước và niềm tin vào việc học."},{"t":"Bạn có biết? Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua nghị quyết kỷ niệm 100 năm Ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990, tôn vinh Người là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam."}],"so_chu":1639},{"i":7,"tieu_de_bang":"Giếng nước trong sân Trường Dục Thanh","tieu_de":"Chiếc giếng, cây khế và thói quen trồng cây suốt đời của Bác","sapo":"Chiếc giếng gạch sâu chừng bốn mét trong sân Trường Dục Thanh đã hơn một trăm tuổi. Năm 1910, thầy giáo Thành thường ra đây múc nước, tưới cho cây khế của bà Nguyễn Thông. Gần nửa thế kỷ sau, người thầy ấy, khi đã là Chủ tịch nước, phát động cả miền Bắc đón Tết bằng cách trồng cây.","bia":{"src":"textures/ht/ht_anh_gieng_truong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Chiếc giếng có trước ngôi trường","text":"Tấm ảnh do Bùi Thụy Đào Nguyên chụp, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 3.0, ghi lại chiếc giếng nước trong khuôn viên Trường Dục Thanh. Theo Báo Văn hóa, giếng sâu khoảng bốn mét, được xây bằng gạch và xi măng vào cuối thế kỷ XIX để phục vụ sinh hoạt của gia đình nhà thơ Nguyễn Thông. Như vậy, chiếc giếng có trước ngôi trường. Nó đã ở đó khi các con cụ Nguyễn Thông mở trường năm 1907, và khi người thầy giáo trẻ Nguyễn Tất Thành đến dạy học mùa thu năm 1910.\n\nGiếng nằm trong khu vườn phía sau ngôi nhà Ngọa Du Sào, gần cây khế cổ thụ. Phần lớn công trình của khu di tích hôm nay được phục dựng trong những năm 1978–1980. Theo tư liệu của bảo tàng được Báo Cần Thơ dẫn lại, phần di tích cũ còn nguyên vẹn gồm cây khế mà Bác từng chăm sóc và chiếc giếng mỗi ngày Người lấy nước tưới cây. Đứng bên thành giếng, người xem đang đứng trước một trong số ít chứng nhân thật sự của những tháng ngày năm 1910.","doc":1},{"loai":"doan","tieu_de":"Nước giếng cho cả một ngôi trường","text":"Khu nhà cụ Nguyễn Thông nằm sát sông Cà Ty, không xa cửa biển. Trong văn của cụ, khi nước ròng, hai bờ sông lộ ra bãi cồn mọc đầy bần, đước, những loài cây quen với vùng nước lợ. Với một ngôi nhà bên cửa sông như thế, chiếc giếng trong vườn là nguồn nước sinh hoạt quen thuộc của cả gia đình. Khi Trường Dục Thanh ra đời và có nội trú, nguồn nước ấy phục vụ thêm thầy giáo và học trò ở xa đến học.\n\nTheo Báo Văn hóa, thầy giáo Nguyễn Tất Thành và các học trò thường múc nước ở giếng để dùng trong sinh hoạt, làm vệ sinh trường lớp và tưới cây trong vườn. Những việc ấy nghe bình thường, nhưng cho thấy nếp sống tự lo liệu của một ngôi trường nhỏ: thầy và trò cùng múc nước, cùng quét dọn, cùng chăm vườn. Đời sống nội trú của thầy trò quanh nhà Ngư được kể trong chuyên đề Giếng nước. Ở đây, chiếc giếng dẫn ta tới một thói quen khác của thầy Thành: chăm cây.","doc":2},{"loai":"anh","src":"textures/bang_w/G03_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước trong sân Trường Dục Thanh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Cây khế của bà Nguyễn Thông","text":"Cách giếng không xa là cây khế cổ thụ do phu nhân cụ Nguyễn Thông trồng vào cuối thế kỷ XIX. Cũng như chiếc giếng, cây khế có mặt trước khi trường mở. Trong những tháng dạy học ở Dục Thanh, thầy Thành cùng học trò thường chăm sóc, tưới nước cho cây, lấy nước từ chính chiếc giếng gần đó. Vì thế, người dân quanh vùng trìu mến gọi nó là cây khế Bác Hồ, hay cây khế Dục Thanh.\n\nCây khế cũng có số phận riêng. Năm 1993, phần thân chính của cây bị ngã đổ vì mục. Từ phần gốc còn lại, nhiều nhánh mới đâm lên, lớn dần và xanh tốt. Ngày nay, cây được cắt tỉa thành tán tròn như một cây nấm lớn, vẫn ra hoa, kết trái quanh năm nhờ nhân viên di tích chăm sóc cẩn thận. Một bài viết của Hội Bảo vệ thiên nhiên và môi trường Việt Nam cho biết quả khế khá to, mỗi quả trên dưới một trăm gam, nhưng rất ít hạt, chỉ ba đến bốn hạt. Tác giả bài viết cho rằng cây khế đáp ứng các tiêu chí của một Cây Di sản Việt Nam.","doc":3},{"loai":"ban_co_biet","text":"Du khách đến Dục Thanh không được hái khế trên cành, nhưng có thể xin những quả chín rụng để lấy hạt về trồng. Nhờ vậy, giống khế trong sân trường xưa đã theo chân du khách về nhiều vùng đất nước.","nguon_ten":"Hội Bảo vệ thiên nhiên và môi trường Việt Nam (VACNE) – Cây khế trên trăm tuổi ở Phan Thiết","doc":4},{"loai":"doan","tieu_de":"Người thầy trẻ yêu cây cỏ","text":"Báo Văn hóa nhận xét rằng những không gian, hiện vật còn lại ở Dục Thanh cùng kể một câu chuyện. Trước khi trở thành Chủ tịch Hồ Chí Minh, Người là một thanh niên hai mươi tuổi sống giản dị, làm nghề dạy học, yêu thương học trò, ham đọc sách và yêu cây cỏ thiên nhiên. Trong những điều ấy, chiếc giếng và cây khế là hai chứng tích cụ thể nhất cho tình yêu cây cỏ của người thầy trẻ.\n\nTình yêu ấy theo Người suốt cuộc đời. Nhiều năm sau, ở Phủ Chủ tịch, hàng rào quanh nhà sàn của Bác là hàng rào cây râm bụt, loại cây dân dã làng quê nào cũng có. GS.TS Mạch Quang Thắng kể rằng Bác không đồng ý khi thấy người ta định chặt cây trong khu Phủ Chủ tịch, ngay cả khi chỉ định cắt mấy cái rễ đa rủ xuống vướng lối đi. Từ gốc khế được tưới bằng nước giếng ở Phan Thiết đến vườn cây quanh nhà sàn ở Hà Nội, có thể thấy một nếp sống nhất quán: quý cây xanh và tự tay chăm sóc cây.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh.jpg","chu_thich":"Trường Dục Thanh, Phan Thiết – di tích còn giữ nguyên nếp nhà gỗ. Trong khuôn viên này, giếng nước và cây khế nằm ở khu vườn phía sau ngôi nhà Ngọa Du Sào. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Nửa thế kỷ sau: Tết trồng cây","text":"Ngày 28/11/1959, dưới bút danh Trần Lực, Chủ tịch Hồ Chí Minh viết bài Tết trồng cây đăng trên báo Nhân Dân. Nhân dịp kỷ niệm ba mươi năm thành lập Đảng, Người đề nghị tổ chức một ngày Tết trồng cây, vì việc này “tốn kém ít mà lợi ích rất nhiều”. Người tính toán cụ thể: miền Bắc khi ấy có độ 14 triệu dân, trong đó độ 11 triệu người từ tám tuổi trở lên đều có thể trồng cây. Mỗi người phụ trách trồng một hoặc vài ba cây và chăm sóc cho tốt.\n\nNhư vậy, mỗi Tết sẽ trồng được độ 15 triệu cây, và từ năm 1960 đến năm 1965 sẽ có 90 triệu cây, vừa cây ăn quả, cây có hoa, vừa cây làm cột nhà. Người gọi đó là một cuộc thi đua dài hạn nhưng nhẹ nhàng, từ các cụ phụ lão đến các em nhi đồng đều có thể tham gia. Hưởng ứng lời kêu gọi, Tết trồng cây đầu tiên được tổ chức vào dịp Tết Nguyên đán Canh Tý năm 1960. Từ đó, mỗi độ xuân về, trồng cây trở thành một nếp đẹp của người Việt.","doc":6},{"loai":"trich","text":"Và trong mươi năm, nước ta phong cảnh sẽ ngày càng tươi đẹp hơn, khí hậu điều hòa hơn, cây gỗ đầy đủ hơn. Điều đó sẽ góp phần quan trọng vào việc cải thiện đời sống của nhân dân ta.","nguoi":"Chủ tịch Hồ Chí Minh (bút danh Trần Lực)","nguon_ten":"Bài “Tết trồng cây”, báo Nhân Dân ngày 28/11/1959, in trong Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia; dẫn theo Quốc phòng Thủ đô – Nhớ Tết trồng cây đầu tiên do Bác Hồ phát động","doc":7},{"loai":"doan","tieu_de":"Mùa xuân là Tết trồng cây","text":"Nhiều thế hệ người Việt thuộc lòng hai câu thơ của Bác: “Mùa xuân là Tết trồng cây / Làm cho đất nước càng ngày càng xuân”. Bác không chỉ kêu gọi, mà tự tay trồng cây ở nhiều nơi Người đến thăm. Theo GS.TS Mạch Quang Thắng, Bác trồng thật, chứ không trồng để quay phim, chụp ảnh. Người hỏi kỹ các chuyên gia lâm nghiệp xem mỗi nơi nên trồng cây gì. Ở nơi công cộng, Bác hay trồng cây đa, vì cây sống lâu, tán rộng, nhiều bóng mát. Bác trồng cây nhỏ chứ không trồng cây đã lớn, và luôn nhắc trồng cây nào tốt cây ấy.\n\nSáng mồng 1 Tết Kỷ Dậu, ngày 16/2/1969, dù sức khỏe đã yếu, Bác vẫn về xã Vật Lại, huyện Ba Vì, tỉnh Hà Tây cũ, nay thuộc Hà Nội. Người trồng một cây đa lưu niệm trên đồi và chúc Tết bà con. Đó là lần cuối cùng Người dự Tết trồng cây; hơn sáu tháng sau, ngày 2/9/1969, Người từ trần. Từ gốc khế được tưới bằng nước giếng ở Phan Thiết năm 1910 đến cây đa trên đồi Vật Lại năm 1969, sợi dây nối là một thói quen giản dị mà bền bỉ.","doc":8},{"loai":"ban_co_biet","text":"Từ Tết Canh Tý năm 1960 cho đến Tết cuối cùng trong cuộc đời, năm nào Bác cũng viết bài về Tết trồng cây. Bài cuối cùng đăng trên báo Nhân Dân ngày 5/2/1969, chỉ hơn mười ngày trước Tết Kỷ Dậu.","nguon_ten":"Quốc phòng Thủ đô – Nhớ Tết trồng cây đầu tiên do Bác Hồ phát động; Báo Nhân Dân – Bác Hồ với “Tết trồng cây” và “Tết trồng người”","doc":9},{"loai":"anh","src":"textures/bang_w/G03_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước trong sân Trường Dục Thanh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Giếng nước sạch cho làng quê","text":"Chiếc giếng ở Dục Thanh còn gợi tới một mối quan tâm khác của Bác. GS.TS Mạch Quang Thắng kể rằng đi đến đâu, Bác cũng chú ý xem nhà tắm, nhà vệ sinh có bảo đảm vệ sinh không, nông thôn đã có giếng nước sạch chưa, trẻ em có bị bụng ỏng không. Với Người, một chiếc giếng sạch không phải chuyện nhỏ. Nó gắn với sức khỏe của cả một xóm làng, nhất là của trẻ em.\n\nTrồng cây và giữ gìn môi trường sống, trong suy nghĩ của Bác, đi liền với việc chăm lo con người. Bác thường dẫn ý người xưa: vì lợi ích mười năm thì trồng cây, vì lợi ích trăm năm thì trồng người (xem chuyên đề Gian nhà nơi Bác Hồ dạy học ở Dục Thanh). Sau khi nước nhà thống nhất, Tết trồng cây lan rộng khắp cả nước. Mỗi dịp xuân về, nhiều nơi tổ chức Tết trồng cây làm theo lời Bác, hay Tết trồng cây đời đời nhớ ơn Bác Hồ. Nếp đẹp ấy nay đã hơn sáu mươi năm tuổi.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, chiếc giếng gạch và cây khế vẫn nằm cạnh nhau trong khu vườn phía sau Ngọa Du Sào. Giữa những công trình được phục dựng, đây là những chứng tích gốc hiếm hoi còn lại từ thời thầy Thành dạy học. Các đoàn chiến sĩ mới, đoàn viên, học sinh thường được đưa tới thăm cây khế Dục Thanh sau khi xem lớp học. Trong không gian 3D của gian trưng bày này, chiếc giếng cũng được tái hiện ở một góc sân trường.\n\nMột du khách, chị Phan Thị Như, chia sẻ với VnExpress: “Thật xúc động khi được tận mắt thấy giếng nước và những kỷ vật lưu dấu thời Bác kính yêu của chúng ta dạy học ở đây. Bác sống quá giản dị, cả cuộc đời vì nước vì dân”. Chiếc giếng không nói gì về những sự kiện lớn. Nhưng nó giúp người xem hình dung những buổi sớm năm 1910, khi người thầy giáo trẻ múc nước tưới cho cây khế của bà Nguyễn Thông, trước giờ lên lớp.","doc":11},{"loai":"anh","src":"textures/bang_w/G03_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước trong sân Trường Dục Thanh”, nhìn từ trên cao."}],"nguon":["Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng – https://baovanhoa.vn/van-hoa/ky-2-dia-chi-do-ve-nguon-thieng-lieng-256668.html","VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Hội Bảo vệ thiên nhiên và môi trường Việt Nam – Cây khế trên trăm tuổi ở Phan Thiết – https://www.vacne.org.vn/cay-khe-tren-tram-tuoi-o-phan-thiet/24908.html","Báo Nhân Dân – Tết trồng cây, nhớ Bác! (GS.TS Mạch Quang Thắng) – https://nhandan.vn/thoi-su-chinh-tri/tet-trong-cay-nho-bac-449047/","Báo Nhân Dân – Bác Hồ với “Tết trồng cây” và “Tết trồng người” – https://special.nhandan.vn/Bac-Ho-voi-Tet-trong-cay-va-Tet-trong-nguoi/index.html","Quốc phòng Thủ đô – Nhớ Tết trồng cây đầu tiên do Bác Hồ phát động – https://quocphongthudo.vn/van-hoa-xa-hoi/nho-tet-trong-cay-dau-tien-do-bac-ho-phat-dong.html"],"doc":[{"t":"Chiếc giếng, cây khế và thói quen trồng cây suốt đời của Bác. Chiếc giếng gạch sâu chừng bốn mét trong sân Trường Dục Thanh đã hơn một trăm tuổi. Năm 1910, thầy giáo Thành thường ra đây múc nước, tưới cho cây khế của bà Nguyễn Thông. Gần nửa thế kỷ sau, người thầy ấy, khi đã là Chủ tịch nước, phát động cả miền Bắc đón Tết bằng cách trồng cây."},{"t":"Chiếc giếng có trước ngôi trường. Tấm ảnh do Bùi Thụy Đào Nguyên chụp, chia sẻ trên Wikimedia Commons theo giấy phép CC BY-SA 3.0, ghi lại chiếc giếng nước trong khuôn viên Trường Dục Thanh. Theo Báo Văn hóa, giếng sâu khoảng bốn mét, được xây bằng gạch và xi măng vào cuối thế kỷ XIX để phục vụ sinh hoạt của gia đình nhà thơ Nguyễn Thông. Như vậy, chiếc giếng có trước ngôi trường. Nó đã ở đó khi các con cụ Nguyễn Thông mở trường năm 1907, và khi người thầy giáo trẻ Nguyễn Tất Thành đến dạy học mùa thu năm 1910. Giếng nằm trong khu vườn phía sau ngôi nhà Ngọa Du Sào, gần cây khế cổ thụ. Phần lớn công trình của khu di tích hôm nay được phục dựng trong những năm 1978–1980. Theo tư liệu của bảo tàng được Báo Cần Thơ dẫn lại, phần di tích cũ còn nguyên vẹn gồm cây khế mà Bác từng chăm sóc và chiếc giếng mỗi ngày Người lấy nước tưới cây. Đứng bên thành giếng, người xem đang đứng trước một trong số ít chứng nhân thật sự của những tháng ngày năm 1910."},{"t":"Nước giếng cho cả một ngôi trường. Khu nhà cụ Nguyễn Thông nằm sát sông Cà Ty, không xa cửa biển. Trong văn của cụ, khi nước ròng, hai bờ sông lộ ra bãi cồn mọc đầy bần, đước, những loài cây quen với vùng nước lợ. Với một ngôi nhà bên cửa sông như thế, chiếc giếng trong vườn là nguồn nước sinh hoạt quen thuộc của cả gia đình. Khi Trường Dục Thanh ra đời và có nội trú, nguồn nước ấy phục vụ thêm thầy giáo và học trò ở xa đến học. Theo Báo Văn hóa, thầy giáo Nguyễn Tất Thành và các học trò thường múc nước ở giếng để dùng trong sinh hoạt, làm vệ sinh trường lớp và tưới cây trong vườn. Những việc ấy nghe bình thường, nhưng cho thấy nếp sống tự lo liệu của một ngôi trường nhỏ: thầy và trò cùng múc nước, cùng quét dọn, cùng chăm vườn. Đời sống nội trú của thầy trò quanh nhà Ngư được kể trong chuyên đề Giếng nước. Ở đây, chiếc giếng dẫn ta tới một thói quen khác của thầy Thành: chăm cây."},{"t":"Cây khế của bà Nguyễn Thông. Cách giếng không xa là cây khế cổ thụ do phu nhân cụ Nguyễn Thông trồng vào cuối thế kỷ XIX. Cũng như chiếc giếng, cây khế có mặt trước khi trường mở. Trong những tháng dạy học ở Dục Thanh, thầy Thành cùng học trò thường chăm sóc, tưới nước cho cây, lấy nước từ chính chiếc giếng gần đó. Vì thế, người dân quanh vùng trìu mến gọi nó là cây khế Bác Hồ, hay cây khế Dục Thanh. Cây khế cũng có số phận riêng. Năm 1993, phần thân chính của cây bị ngã đổ vì mục. Từ phần gốc còn lại, nhiều nhánh mới đâm lên, lớn dần và xanh tốt. Ngày nay, cây được cắt tỉa thành tán tròn như một cây nấm lớn, vẫn ra hoa, kết trái quanh năm nhờ nhân viên di tích chăm sóc cẩn thận. Một bài viết của Hội Bảo vệ thiên nhiên và môi trường Việt Nam cho biết quả khế khá to, mỗi quả trên dưới một trăm gam, nhưng rất ít hạt, chỉ ba đến bốn hạt. Tác giả bài viết cho rằng cây khế đáp ứng các tiêu chí của một Cây Di sản Việt Nam."},{"t":"Bạn có biết? Du khách đến Dục Thanh không được hái khế trên cành, nhưng có thể xin những quả chín rụng để lấy hạt về trồng. Nhờ vậy, giống khế trong sân trường xưa đã theo chân du khách về nhiều vùng đất nước."},{"t":"Người thầy trẻ yêu cây cỏ. Báo Văn hóa nhận xét rằng những không gian, hiện vật còn lại ở Dục Thanh cùng kể một câu chuyện. Trước khi trở thành Chủ tịch Hồ Chí Minh, Người là một thanh niên hai mươi tuổi sống giản dị, làm nghề dạy học, yêu thương học trò, ham đọc sách và yêu cây cỏ thiên nhiên. Trong những điều ấy, chiếc giếng và cây khế là hai chứng tích cụ thể nhất cho tình yêu cây cỏ của người thầy trẻ. Tình yêu ấy theo Người suốt cuộc đời. Nhiều năm sau, ở Phủ Chủ tịch, hàng rào quanh nhà sàn của Bác là hàng rào cây râm bụt, loại cây dân dã làng quê nào cũng có. GS.TS Mạch Quang Thắng kể rằng Bác không đồng ý khi thấy người ta định chặt cây trong khu Phủ Chủ tịch, ngay cả khi chỉ định cắt mấy cái rễ đa rủ xuống vướng lối đi. Từ gốc khế được tưới bằng nước giếng ở Phan Thiết đến vườn cây quanh nhà sàn ở Hà Nội, có thể thấy một nếp sống nhất quán: quý cây xanh và tự tay chăm sóc cây."},{"t":"Nửa thế kỷ sau: Tết trồng cây. Ngày 28/11/1959, dưới bút danh Trần Lực, Chủ tịch Hồ Chí Minh viết bài Tết trồng cây đăng trên báo Nhân Dân. Nhân dịp kỷ niệm ba mươi năm thành lập Đảng, Người đề nghị tổ chức một ngày Tết trồng cây, vì việc này “tốn kém ít mà lợi ích rất nhiều”. Người tính toán cụ thể: miền Bắc khi ấy có độ 14 triệu dân, trong đó độ 11 triệu người từ tám tuổi trở lên đều có thể trồng cây. Mỗi người phụ trách trồng một hoặc vài ba cây và chăm sóc cho tốt. Như vậy, mỗi Tết sẽ trồng được độ 15 triệu cây, và từ năm 1960 đến năm 1965 sẽ có 90 triệu cây, vừa cây ăn quả, cây có hoa, vừa cây làm cột nhà. Người gọi đó là một cuộc thi đua dài hạn nhưng nhẹ nhàng, từ các cụ phụ lão đến các em nhi đồng đều có thể tham gia. Hưởng ứng lời kêu gọi, Tết trồng cây đầu tiên được tổ chức vào dịp Tết Nguyên đán Canh Tý năm 1960. Từ đó, mỗi độ xuân về, trồng cây trở thành một nếp đẹp của người Việt."},{"t":"Và trong mươi năm, nước ta phong cảnh sẽ ngày càng tươi đẹp hơn, khí hậu điều hòa hơn, cây gỗ đầy đủ hơn. Điều đó sẽ góp phần quan trọng vào việc cải thiện đời sống của nhân dân ta. — Chủ tịch Hồ Chí Minh (bút danh Trần Lực)"},{"t":"Mùa xuân là Tết trồng cây. Nhiều thế hệ người Việt thuộc lòng hai câu thơ của Bác: “Mùa xuân là Tết trồng cây / Làm cho đất nước càng ngày càng xuân”. Bác không chỉ kêu gọi, mà tự tay trồng cây ở nhiều nơi Người đến thăm. Theo GS.TS Mạch Quang Thắng, Bác trồng thật, chứ không trồng để quay phim, chụp ảnh. Người hỏi kỹ các chuyên gia lâm nghiệp xem mỗi nơi nên trồng cây gì. Ở nơi công cộng, Bác hay trồng cây đa, vì cây sống lâu, tán rộng, nhiều bóng mát. Bác trồng cây nhỏ chứ không trồng cây đã lớn, và luôn nhắc trồng cây nào tốt cây ấy. Sáng mồng 1 Tết Kỷ Dậu, ngày 16/2/1969, dù sức khỏe đã yếu, Bác vẫn về xã Vật Lại, huyện Ba Vì, tỉnh Hà Tây cũ, nay thuộc Hà Nội. Người trồng một cây đa lưu niệm trên đồi và chúc Tết bà con. Đó là lần cuối cùng Người dự Tết trồng cây; hơn sáu tháng sau, ngày 2/9/1969, Người từ trần. Từ gốc khế được tưới bằng nước giếng ở Phan Thiết năm 1910 đến cây đa trên đồi Vật Lại năm 1969, sợi dây nối là một thói quen giản dị mà bền bỉ."},{"t":"Bạn có biết? Từ Tết Canh Tý năm 1960 cho đến Tết cuối cùng trong cuộc đời, năm nào Bác cũng viết bài về Tết trồng cây. Bài cuối cùng đăng trên báo Nhân Dân ngày 5/2/1969, chỉ hơn mười ngày trước Tết Kỷ Dậu."},{"t":"Giếng nước sạch cho làng quê. Chiếc giếng ở Dục Thanh còn gợi tới một mối quan tâm khác của Bác. GS.TS Mạch Quang Thắng kể rằng đi đến đâu, Bác cũng chú ý xem nhà tắm, nhà vệ sinh có bảo đảm vệ sinh không, nông thôn đã có giếng nước sạch chưa, trẻ em có bị bụng ỏng không. Với Người, một chiếc giếng sạch không phải chuyện nhỏ. Nó gắn với sức khỏe của cả một xóm làng, nhất là của trẻ em. Trồng cây và giữ gìn môi trường sống, trong suy nghĩ của Bác, đi liền với việc chăm lo con người. Bác thường dẫn ý người xưa: vì lợi ích mười năm thì trồng cây, vì lợi ích trăm năm thì trồng người (xem chuyên đề Gian nhà nơi Bác Hồ dạy học ở Dục Thanh). Sau khi nước nhà thống nhất, Tết trồng cây lan rộng khắp cả nước. Mỗi dịp xuân về, nhiều nơi tổ chức Tết trồng cây làm theo lời Bác, hay Tết trồng cây đời đời nhớ ơn Bác Hồ. Nếp đẹp ấy nay đã hơn sáu mươi năm tuổi."},{"t":"Dấu tích hôm nay. Ngày nay, chiếc giếng gạch và cây khế vẫn nằm cạnh nhau trong khu vườn phía sau Ngọa Du Sào. Giữa những công trình được phục dựng, đây là những chứng tích gốc hiếm hoi còn lại từ thời thầy Thành dạy học. Các đoàn chiến sĩ mới, đoàn viên, học sinh thường được đưa tới thăm cây khế Dục Thanh sau khi xem lớp học. Trong không gian 3D của gian trưng bày này, chiếc giếng cũng được tái hiện ở một góc sân trường. Một du khách, chị Phan Thị Như, chia sẻ với VnExpress: “Thật xúc động khi được tận mắt thấy giếng nước và những kỷ vật lưu dấu thời Bác kính yêu của chúng ta dạy học ở đây. Bác sống quá giản dị, cả cuộc đời vì nước vì dân”. Chiếc giếng không nói gì về những sự kiện lớn. Nhưng nó giúp người xem hình dung những buổi sớm năm 1910, khi người thầy giáo trẻ múc nước tưới cho cây khế của bà Nguyễn Thông, trước giờ lên lớp."}],"so_chu":1730},{"i":8,"tieu_de_bang":"Sông Cà Ty, Phan Thiết","tieu_de":"Bên dòng Cà Ty: nghề biển, xóm chài và những buổi học ngoài lớp của thầy Thành","sapo":"Con sông chảy qua lòng Phan Thiết đã nuôi nghề biển, nghề nước mắm, và nuôi cả một ngôi trường yêu nước dựng bên bờ nó. Năm 1910, người thầy giáo hai mươi tuổi của ngôi trường ấy thường dắt học trò ra khỏi lớp, tới tận những xóm chài nghèo. Thầy kể chuyện Hai Bà Trưng, Bà Triệu giữa cảnh sống vất vả của ngư dân. Vài tháng sau, cũng từ miền cửa sông này, người thầy lên đường vào Sài Gòn rồi ra biển lớn.","bia":{"src":"textures/ht/ht_anh_song_ca_ty.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một buổi sáng tháng Mười Một","text":"Tấm ảnh do Bùi Thụy Đào Nguyên chụp lúc 7 giờ 28 phút sáng ngày 9/11/2014, chia sẻ trên kho tư liệu Wikimedia Commons theo giấy phép CC BY-SA 4.0. Khung hình ghi lại sông Cà Ty, con sông chảy xuyên qua lòng Phan Thiết trước khi đổ ra biển. Với người Phan Thiết, đó không chỉ là một dòng nước. Hai bên bờ là phố xá, chợ búa, bến thuyền; nơi cửa sông, ghe thuyền đánh cá ra vào quanh năm.\n\nHơn một thế kỷ trước khi tấm ảnh ra đời, bên hữu ngạn dòng sông này, trên khu vườn của gia đình nhà thơ Nguyễn Thông, Trường Dục Thanh đón một thầy giáo mới. Từ tháng 9/1910 đến tháng 2/1911, Nguyễn Tất Thành đứng lớp nhì của trường. Ngày nay, khu di tích ở số 39 đường Trưng Nhị vẫn nằm sát dòng Cà Ty, cạnh Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Tấm ảnh mở ra một cách nhìn khác về di tích: không nhìn từ trong lớp học, mà từ con sông đã nuôi sống thị xã, nuôi nghề biển và gián tiếp nuôi cả ngôi trường. Chuyên đề này đi theo dòng sông ấy, ra tới những xóm chài nơi thầy Thành từng dắt học trò đến.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_song_ca_ty.jpg","chu_thich":"Sông Cà Ty chảy qua lòng Phan Thiết, ảnh chụp sáng ngày 9/11/2014. Trường Dục Thanh nằm bên hữu ngạn dòng sông này. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Thị xã bên cửa sông","text":"Năm 1910, Phan Thiết là tỉnh lỵ của Bình Thuận, một tỉnh thuộc Trung Kỳ dưới chế độ bảo hộ của Pháp. Thị xã được lập từ năm 1898, không lớn, và đời sống của nó xoay quanh con sông với biển. Ghe thuyền đánh cá cập bến ở cửa sông. Cá được đưa lên chợ hoặc vào những cơ sở làm nước mắm, rồi nước mắm lại theo ghe bầu đi Sài Gòn và nhiều nơi khác. Nhịp sống của thị xã gắn với mùa cá, với con nước lên xuống mỗi ngày.\n\nKhu vườn nhà cụ Nguyễn Thông, nơi Dục Thanh ra đời, nằm sát mép nước; theo văn của cụ, xưa kia có con rạch từ sông chảy vào tận nhà (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Nhờ vậy, ngôi trường không đứng tách khỏi đời sống thị xã mà ở ngay giữa nhịp sống ấy. Trước khi đến đây, Nguyễn Tất Thành đã sống ở Huế, ở Bình Định, học thêm tiếng Pháp ở Quy Nhơn. Nhưng chỉ ở Phan Thiết, người thanh niên mới sống giữa một cộng đồng mà cả cái ăn lẫn cái học đều trông vào nghề biển: ngay ngôi trường của anh cũng được nuôi bằng tiền nước mắm.","doc":2},{"loai":"doan","tieu_de":"Cá cơm, muối và những thùng gỗ lớn","text":"Phan Thiết từ lâu nổi tiếng về nước mắm. Nguyên liệu chính là cá cơm đánh bắt ngoài khơi và muối. Cá trộn muối được ủ trong những thùng gỗ lớn suốt nhiều tháng, thường tới cả năm, rồi mới rút ra thứ nước mắm màu cánh gián, thơm và đậm. Người địa phương gọi nơi đặt những thùng ủ ấy là nhà thùng. Quanh nghề nước mắm là cả một chuỗi nghề: người đi biển, người đóng thùng, người buôn muối, người chở hàng bằng ghe bầu dọc bờ biển.\n\nChính nghề này đã nuôi ngôi trường của thầy Thành. Tháng 3/1906, sáu nhà nho yêu nước ở Phan Thiết lập hội buôn Liên Thành, lấy lãi từ việc làm và bán nước mắm để trang trải cho việc học (xem chuyên đề Hội buôn nước mắm nuôi một ngôi trường). Ngay trong khuôn viên trường, nhà Ngư vốn là nơi gia đình cụ Nguyễn Thông chứa ngư cụ và làm nước mắm, trước khi thành chỗ ở nội trú của thầy trò (xem chuyên đề Giếng nước). Năm 1910, trên dòng Cà Ty là những chiếc thuyền nan, thuyền thúng của ngư dân. Có thể nói, học trò Dục Thanh lớn lên giữa tiếng sóng, mùi cá và mùi muối. Con chữ các em học được nuôi bằng chính sức lao động của những người đi biển quanh mình.","doc":3},{"loai":"anh","src":"textures/bang_w/G03_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Cà Ty, Phan Thiết”, nhìn từ xa."},{"loai":"doan","tieu_de":"Muối đắt, sưu cao","text":"Đời sống bên dòng sông không yên ả như mặt nước. Từ cuối thế kỷ XIX, dưới thời Toàn quyền Paul Doumer, chính quyền thuộc địa đặt độc quyền muối, rượu và thuốc phiện để tăng thu cho ngân sách Đông Dương. Muối, thứ người làm nước mắm cần nhiều nhất, trở nên đắt đỏ. Người đi biển, người làm muối còn phải gánh sưu cao thuế nặng, trong khi nghề biển vốn bấp bênh theo mùa cá, theo sóng gió.\n\nNăm 1908, phong trào chống sưu thuế bùng lên ở nhiều tỉnh Trung Kỳ và bị đàn áp khốc liệt. Nhiều nhà nho Duy Tân bị bắt; Phan Châu Trinh, Huỳnh Thúc Kháng bị đày ra Côn Lôn. Hai năm sau, khi thầy Thành đến Phan Thiết, không khí ấy vẫn còn nặng nề. Việc các nhà nho Phan Thiết vẫn giữ được hội buôn và ngôi trường là điều không dễ. Và khi người thầy trẻ dắt học trò ra xóm chài, các em được thấy tận mắt những gánh nặng đang đè lên vai đồng bào mình, điều mà không trang sách nào trong lớp nói hết.","doc":4},{"loai":"ban_co_biet","text":"Muối là nguyên liệu không thể thiếu của nghề nước mắm. Cuối thế kỷ XIX, chính quyền thuộc địa Pháp giành độc quyền muối ở Đông Dương, cùng với rượu và thuốc phiện; cả ba trở thành những nguồn thu lớn của ngân sách thuộc địa.","nguon_ten":"Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục","doc":5},{"loai":"doan","tieu_de":"Những buổi học ngoài bốn bức tường","text":"Theo lời kể của các học trò cũ, được Bảo tàng Hồ Chí Minh và báo chí nhiều lần ghi lại, thầy Thành không chỉ dạy trong lớp. Ngoài giờ lên lớp, thầy thường đưa học trò đi thăm thắng cảnh quanh thị xã, tìm hiểu đời sống người lao động, ghé cả những xóm chài nghèo ven biển. Trên đường đi, thầy kể chuyện Hai Bà Trưng, Bà Triệu, kể chuyện các anh hùng dân tộc, đọc cho trò nghe những vần thơ yêu nước.\n\nTư liệu hiện biết không ghi tên từng nơi thầy trò đã tới. Nhưng quanh một thị xã sống bằng nghề cá, xóm chài là nơi dễ tìm đến nhất. Có thể hình dung những mái nhà thấp, những tấm lưới phơi, những chiếc thuyền thúng kéo lên bãi cát. Bài học ở đó không có bảng đen, không có sách. Lịch sử dân tộc được kể giữa khung cảnh quê hương, trước mặt những con người thật. Câu chuyện Hai Bà Trưng, Bà Triệu vì thế không còn là chuyện của nghìn năm trước. Nó gắn với một câu hỏi rất gần: đất nước hôm nay ra sao, người dân hôm nay đang sống thế nào.","doc":6},{"loai":"anh","src":"textures/bang_w/G03_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Cà Ty, Phan Thiết”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Người thầy đứng gần người lao động","text":"Các học trò cũ nhớ ở thầy Thành nhiều điều, trong đó có một nét rất rõ: thầy luôn hòa đồng với cuộc sống của người lao động nghèo Phan Thiết. Dắt học trò tới xóm chài, người thầy muốn các em hiểu vì sao phải học, phải thương người nghèo khổ, phải yêu quê hương, đất nước. Học chữ để thi đỗ, làm quan là lối nghĩ của nhiều nhà nho xưa. Ở Dục Thanh, học chữ là để hiểu đời sống của đồng bào mình.\n\nBản thân người thầy giáo ấy cũng sắp bước vào đời người lao động. Chỉ vài tháng sau, Nguyễn Tất Thành làm phụ bếp trên một con tàu viễn dương. Những năm sau đó, ở nước ngoài, Người làm nhiều nghề nặng nhọc để sống và học: cào tuyết, đốt lò, rửa bát, làm thợ ảnh. Nhìn lại, những buổi tới xóm chài ở Phan Thiết cho thấy từ rất sớm, người thanh niên ấy đã muốn đứng gần người lao động và muốn học trò mình cũng như vậy. Sự gần gũi ấy về sau trở thành một nét xuyên suốt trong cuộc đời Hồ Chí Minh.","doc":7},{"loai":"doan","tieu_de":"Từ cửa sông ra biển lớn","text":"Tháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Phan Thiết vào Sài Gòn. Theo GS Lê Hữu Phước, Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Thành phố Hồ Chí Minh, Người rời Bình Thuận để tìm một nơi vừa có thể kiếm sống, vừa tìm được tàu ra nước ngoài. Người ở Sài Gòn khoảng bốn tháng, từ tháng 2 đến đầu tháng 6/1911. Ngày 5/6/1911, trên tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, người thanh niên rời bến Nhà Rồng, làm phụ bếp với tên gọi Văn Ba (xem chuyên đề Mốc thời gian).\n\nCon sông trước cửa lớp Dục Thanh chảy ra Biển Đông. Có lẽ không học trò nào của lớp nhì năm ấy ngờ rằng người thầy của mình sẽ đi xa đến thế. Ba mươi năm bôn ba qua nhiều châu lục, đến ngày 28/1/1941, Người mới trở về Tổ quốc qua cột mốc 108 ở Cao Bằng. Những tháng bên dòng Cà Ty vì thế là chặng dừng chân dài cuối cùng trước khi Người vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước.","doc":8},{"loai":"ban_co_biet","text":"Năm 1910, Bình Thuận thuộc Trung Kỳ, xứ bảo hộ của Pháp, còn Sài Gòn là thủ phủ của Nam Kỳ, xứ thuộc địa. Rời Phan Thiết vào Sài Gòn, người thanh niên bước sang một xứ có chế độ cai trị khác hẳn, nơi tàu buôn và tàu viễn dương ra vào thường xuyên.","nguon_ten":"Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục; Người Lao Động – Sài Gòn với Nguyễn Tất Thành (GS Lê Hữu Phước)","doc":9},{"loai":"anh","src":"textures/bang_w/G03_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Cà Ty, Phan Thiết”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dòng sông hôm nay","text":"Hơn một thế kỷ sau, sông Cà Ty vẫn chảy qua lòng Phan Thiết. Từ ngày 1/7/2025, sau khi sắp xếp lại địa giới hành chính, nơi đây thuộc phường Phan Thiết, tỉnh Lâm Đồng. Ở cửa sông, tàu thuyền đánh cá vẫn về bến. Bên bờ, tháp nước xây từ thời Pháp thuộc, nay gần trăm năm tuổi, đã thành biểu tượng quen thuộc của thành phố. Nghề nước mắm Phan Thiết vẫn còn, và cái tên Liên Thành, ra đời từ năm 1906, vẫn được nhắc tới như một trong những thương hiệu nước mắm lâu đời nhất Việt Nam.\n\nKhu di tích Trường Dục Thanh và Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận nằm cạnh nhau bên bờ sông. Du khách vào di tích từ phía bờ Cà Ty, qua cổng trường bằng gỗ rồi mới tới lớp học. Đứng ở bờ sông trước cổng, người xem có thể hình dung những buổi chiều thầy Thành dắt học trò ra khỏi cổng trường, đi về phía biển. Tấm ảnh chụp một buổi sáng năm 2014 không có bóng dáng người thầy giáo năm xưa. Nhưng con sông trong ảnh là một chứng nhân còn sống. Nó đã chảy qua đây khi Nguyễn Tất Thành hai mươi tuổi, và vẫn chảy khi hằng năm hàng vạn lượt học sinh, đoàn viên, du khách tìm về Dục Thanh.","doc":10}],"nguon":["Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","VnExpress (Tư Huynh, 2/9/2026) – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Người Lao Động (GS Lê Hữu Phước) – Sài Gòn với Nguyễn Tất Thành – https://tuoitre.vn/nld/thoi-su-trong-nuoc/sai-gon-voi-nguyen-tat-thanh-20110522115636410.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục","Wikimedia Commons – ảnh Sông Cà Ty (Bùi Thụy Đào Nguyên, CC BY-SA 4.0)"],"doc":[{"t":"Bên dòng Cà Ty: nghề biển, xóm chài và những buổi học ngoài lớp của thầy Thành. Con sông chảy qua lòng Phan Thiết đã nuôi nghề biển, nghề nước mắm, và nuôi cả một ngôi trường yêu nước dựng bên bờ nó. Năm 1910, người thầy giáo hai mươi tuổi của ngôi trường ấy thường dắt học trò ra khỏi lớp, tới tận những xóm chài nghèo. Thầy kể chuyện Hai Bà Trưng, Bà Triệu giữa cảnh sống vất vả của ngư dân. Vài tháng sau, cũng từ miền cửa sông này, người thầy lên đường vào Sài Gòn rồi ra biển lớn."},{"t":"Một buổi sáng tháng Mười Một. Tấm ảnh do Bùi Thụy Đào Nguyên chụp lúc 7 giờ 28 phút sáng ngày 9/11/2014, chia sẻ trên kho tư liệu Wikimedia Commons theo giấy phép CC BY-SA 4.0. Khung hình ghi lại sông Cà Ty, con sông chảy xuyên qua lòng Phan Thiết trước khi đổ ra biển. Với người Phan Thiết, đó không chỉ là một dòng nước. Hai bên bờ là phố xá, chợ búa, bến thuyền; nơi cửa sông, ghe thuyền đánh cá ra vào quanh năm. Hơn một thế kỷ trước khi tấm ảnh ra đời, bên hữu ngạn dòng sông này, trên khu vườn của gia đình nhà thơ Nguyễn Thông, Trường Dục Thanh đón một thầy giáo mới. Từ tháng 9/1910 đến tháng 2/1911, Nguyễn Tất Thành đứng lớp nhì của trường. Ngày nay, khu di tích ở số 39 đường Trưng Nhị vẫn nằm sát dòng Cà Ty, cạnh Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận. Tấm ảnh mở ra một cách nhìn khác về di tích: không nhìn từ trong lớp học, mà từ con sông đã nuôi sống thị xã, nuôi nghề biển và gián tiếp nuôi cả ngôi trường. Chuyên đề này đi theo dòng sông ấy, ra tới những xóm chài nơi thầy Thành từng dắt học trò đến."},{"t":"Thị xã bên cửa sông. Năm 1910, Phan Thiết là tỉnh lỵ của Bình Thuận, một tỉnh thuộc Trung Kỳ dưới chế độ bảo hộ của Pháp. Thị xã được lập từ năm 1898, không lớn, và đời sống của nó xoay quanh con sông với biển. Ghe thuyền đánh cá cập bến ở cửa sông. Cá được đưa lên chợ hoặc vào những cơ sở làm nước mắm, rồi nước mắm lại theo ghe bầu đi Sài Gòn và nhiều nơi khác. Nhịp sống của thị xã gắn với mùa cá, với con nước lên xuống mỗi ngày. Khu vườn nhà cụ Nguyễn Thông, nơi Dục Thanh ra đời, nằm sát mép nước; theo văn của cụ, xưa kia có con rạch từ sông chảy vào tận nhà (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Nhờ vậy, ngôi trường không đứng tách khỏi đời sống thị xã mà ở ngay giữa nhịp sống ấy. Trước khi đến đây, Nguyễn Tất Thành đã sống ở Huế, ở Bình Định, học thêm tiếng Pháp ở Quy Nhơn. Nhưng chỉ ở Phan Thiết, người thanh niên mới sống giữa một cộng đồng mà cả cái ăn lẫn cái học đều trông vào nghề biển: ngay ngôi trường của anh cũng được nuôi bằng tiền nước mắm."},{"t":"Cá cơm, muối và những thùng gỗ lớn. Phan Thiết từ lâu nổi tiếng về nước mắm. Nguyên liệu chính là cá cơm đánh bắt ngoài khơi và muối. Cá trộn muối được ủ trong những thùng gỗ lớn suốt nhiều tháng, thường tới cả năm, rồi mới rút ra thứ nước mắm màu cánh gián, thơm và đậm. Người địa phương gọi nơi đặt những thùng ủ ấy là nhà thùng. Quanh nghề nước mắm là cả một chuỗi nghề: người đi biển, người đóng thùng, người buôn muối, người chở hàng bằng ghe bầu dọc bờ biển. Chính nghề này đã nuôi ngôi trường của thầy Thành. Tháng 3/1906, sáu nhà nho yêu nước ở Phan Thiết lập hội buôn Liên Thành, lấy lãi từ việc làm và bán nước mắm để trang trải cho việc học (xem chuyên đề Hội buôn nước mắm nuôi một ngôi trường). Ngay trong khuôn viên trường, nhà Ngư vốn là nơi gia đình cụ Nguyễn Thông chứa ngư cụ và làm nước mắm, trước khi thành chỗ ở nội trú của thầy trò (xem chuyên đề Giếng nước). Năm 1910, trên dòng Cà Ty là những chiếc thuyền nan, thuyền thúng của ngư dân. Có thể nói, học trò Dục Thanh lớn lên giữa tiếng sóng, mùi cá và mùi muối. Con chữ các em học được nuôi bằng chính sức lao động của những người đi biển quanh mình."},{"t":"Muối đắt, sưu cao. Đời sống bên dòng sông không yên ả như mặt nước. Từ cuối thế kỷ XIX, dưới thời Toàn quyền Paul Doumer, chính quyền thuộc địa đặt độc quyền muối, rượu và thuốc phiện để tăng thu cho ngân sách Đông Dương. Muối, thứ người làm nước mắm cần nhiều nhất, trở nên đắt đỏ. Người đi biển, người làm muối còn phải gánh sưu cao thuế nặng, trong khi nghề biển vốn bấp bênh theo mùa cá, theo sóng gió. Năm 1908, phong trào chống sưu thuế bùng lên ở nhiều tỉnh Trung Kỳ và bị đàn áp khốc liệt. Nhiều nhà nho Duy Tân bị bắt; Phan Châu Trinh, Huỳnh Thúc Kháng bị đày ra Côn Lôn. Hai năm sau, khi thầy Thành đến Phan Thiết, không khí ấy vẫn còn nặng nề. Việc các nhà nho Phan Thiết vẫn giữ được hội buôn và ngôi trường là điều không dễ. Và khi người thầy trẻ dắt học trò ra xóm chài, các em được thấy tận mắt những gánh nặng đang đè lên vai đồng bào mình, điều mà không trang sách nào trong lớp nói hết."},{"t":"Bạn có biết? Muối là nguyên liệu không thể thiếu của nghề nước mắm. Cuối thế kỷ XIX, chính quyền thuộc địa Pháp giành độc quyền muối ở Đông Dương, cùng với rượu và thuốc phiện; cả ba trở thành những nguồn thu lớn của ngân sách thuộc địa."},{"t":"Những buổi học ngoài bốn bức tường. Theo lời kể của các học trò cũ, được Bảo tàng Hồ Chí Minh và báo chí nhiều lần ghi lại, thầy Thành không chỉ dạy trong lớp. Ngoài giờ lên lớp, thầy thường đưa học trò đi thăm thắng cảnh quanh thị xã, tìm hiểu đời sống người lao động, ghé cả những xóm chài nghèo ven biển. Trên đường đi, thầy kể chuyện Hai Bà Trưng, Bà Triệu, kể chuyện các anh hùng dân tộc, đọc cho trò nghe những vần thơ yêu nước. Tư liệu hiện biết không ghi tên từng nơi thầy trò đã tới. Nhưng quanh một thị xã sống bằng nghề cá, xóm chài là nơi dễ tìm đến nhất. Có thể hình dung những mái nhà thấp, những tấm lưới phơi, những chiếc thuyền thúng kéo lên bãi cát. Bài học ở đó không có bảng đen, không có sách. Lịch sử dân tộc được kể giữa khung cảnh quê hương, trước mặt những con người thật. Câu chuyện Hai Bà Trưng, Bà Triệu vì thế không còn là chuyện của nghìn năm trước. Nó gắn với một câu hỏi rất gần: đất nước hôm nay ra sao, người dân hôm nay đang sống thế nào."},{"t":"Người thầy đứng gần người lao động. Các học trò cũ nhớ ở thầy Thành nhiều điều, trong đó có một nét rất rõ: thầy luôn hòa đồng với cuộc sống của người lao động nghèo Phan Thiết. Dắt học trò tới xóm chài, người thầy muốn các em hiểu vì sao phải học, phải thương người nghèo khổ, phải yêu quê hương, đất nước. Học chữ để thi đỗ, làm quan là lối nghĩ của nhiều nhà nho xưa. Ở Dục Thanh, học chữ là để hiểu đời sống của đồng bào mình. Bản thân người thầy giáo ấy cũng sắp bước vào đời người lao động. Chỉ vài tháng sau, Nguyễn Tất Thành làm phụ bếp trên một con tàu viễn dương. Những năm sau đó, ở nước ngoài, Người làm nhiều nghề nặng nhọc để sống và học: cào tuyết, đốt lò, rửa bát, làm thợ ảnh. Nhìn lại, những buổi tới xóm chài ở Phan Thiết cho thấy từ rất sớm, người thanh niên ấy đã muốn đứng gần người lao động và muốn học trò mình cũng như vậy. Sự gần gũi ấy về sau trở thành một nét xuyên suốt trong cuộc đời Hồ Chí Minh."},{"t":"Từ cửa sông ra biển lớn. Tháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Phan Thiết vào Sài Gòn. Theo GS Lê Hữu Phước, Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Thành phố Hồ Chí Minh, Người rời Bình Thuận để tìm một nơi vừa có thể kiếm sống, vừa tìm được tàu ra nước ngoài. Người ở Sài Gòn khoảng bốn tháng, từ tháng 2 đến đầu tháng 6/1911. Ngày 5/6/1911, trên tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, người thanh niên rời bến Nhà Rồng, làm phụ bếp với tên gọi Văn Ba (xem chuyên đề Mốc thời gian). Con sông trước cửa lớp Dục Thanh chảy ra Biển Đông. Có lẽ không học trò nào của lớp nhì năm ấy ngờ rằng người thầy của mình sẽ đi xa đến thế. Ba mươi năm bôn ba qua nhiều châu lục, đến ngày 28/1/1941, Người mới trở về Tổ quốc qua cột mốc 108 ở Cao Bằng. Những tháng bên dòng Cà Ty vì thế là chặng dừng chân dài cuối cùng trước khi Người vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước."},{"t":"Bạn có biết? Năm 1910, Bình Thuận thuộc Trung Kỳ, xứ bảo hộ của Pháp, còn Sài Gòn là thủ phủ của Nam Kỳ, xứ thuộc địa. Rời Phan Thiết vào Sài Gòn, người thanh niên bước sang một xứ có chế độ cai trị khác hẳn, nơi tàu buôn và tàu viễn dương ra vào thường xuyên."},{"t":"Dòng sông hôm nay. Hơn một thế kỷ sau, sông Cà Ty vẫn chảy qua lòng Phan Thiết. Từ ngày 1/7/2025, sau khi sắp xếp lại địa giới hành chính, nơi đây thuộc phường Phan Thiết, tỉnh Lâm Đồng. Ở cửa sông, tàu thuyền đánh cá vẫn về bến. Bên bờ, tháp nước xây từ thời Pháp thuộc, nay gần trăm năm tuổi, đã thành biểu tượng quen thuộc của thành phố. Nghề nước mắm Phan Thiết vẫn còn, và cái tên Liên Thành, ra đời từ năm 1906, vẫn được nhắc tới như một trong những thương hiệu nước mắm lâu đời nhất Việt Nam. Khu di tích Trường Dục Thanh và Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận nằm cạnh nhau bên bờ sông. Du khách vào di tích từ phía bờ Cà Ty, qua cổng trường bằng gỗ rồi mới tới lớp học. Đứng ở bờ sông trước cổng, người xem có thể hình dung những buổi chiều thầy Thành dắt học trò ra khỏi cổng trường, đi về phía biển. Tấm ảnh chụp một buổi sáng năm 2014 không có bóng dáng người thầy giáo năm xưa. Nhưng con sông trong ảnh là một chứng nhân còn sống. Nó đã chảy qua đây khi Nguyễn Tất Thành hai mươi tuổi, và vẫn chảy khi hằng năm hàng vạn lượt học sinh, đoàn viên, du khách tìm về Dục Thanh."}],"so_chu":1863},{"i":9,"tieu_de_bang":"Lớp học Trường Dục Thanh","tieu_de":"Lớp học gỗ 137 mét vuông: đi một vòng quanh lớp của thầy Thành","sapo":"Hai tấm bảng đen, hai mươi mốt bộ bàn ghế chia ba dãy, một bộ trường kỷ cho bảy thầy giáo: lớp học Dục Thanh không có gì cầu kỳ. Nhưng đặt vào năm 1910, khi phần đông trẻ em được đi học ở Trung Kỳ vẫn ngồi chiếu học chữ Nho, mỗi món đồ ấy là một lựa chọn mới. Hãy đi một vòng quanh lớp học, từ mái ngói xuống nền gạch, để thấy một ngôi trường Duy Tân được bài trí thế nào và vì sao.","bia":{"src":"textures/bai/G03_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bước qua ngưỡng cửa","text":"Lớp học chính của Trường Dục Thanh là một ngôi nhà gỗ rộng khoảng 137 mét vuông, cao 4,4 mét, mái lợp ngói âm dương, tường bằng gỗ, nền lát gạch. Bước qua ngưỡng cửa, người xem thấy hai tấm bảng đen, 21 bộ bàn ghế học trò chia làm ba dãy, và một bộ họa đàn trường kỷ dành cho bảy thầy giáo. Không có gì cầu kỳ. Đó là lớp học mộc mạc của một ngôi trường tư ở tỉnh lẻ đầu thế kỷ XX, do chính những người Việt yêu nước bỏ công, bỏ của dựng nên.\n\nCần nói ngay một điều: ngôi nhà du khách thấy hôm nay được trùng tu, phục dựng từ tháng 11/1978 đến tháng 12/1980. Việc phục dựng dựa trên lời kể và bản vẽ phác họa của những học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Vì thế, lớp học vừa là một hiện vật, vừa là một bản ghi trí nhớ. Mỗi món đồ được đặt lại theo đúng chỗ mà các cụ, sau gần bảy mươi năm, vẫn còn nhớ. Chuyên đề này đi một vòng quanh lớp, dừng lại ở từng món đồ, để hỏi xem nó nói gì về ngôi trường năm 1910 và người thầy giáo trẻ từng đứng lớp ở đây.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","chu_thich":"Bên trong lớp học Trường Dục Thanh, nơi thầy Nguyễn Tất Thành đứng lớp nhì trong niên học 1910 – 1911. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Mái cao giữa đất nắng gió","text":"Chiều cao 4,4 mét là một con số đáng chú ý với một lớp học chỉ có một tầng. Bình Thuận là một trong những vùng khô hạn, nắng gió nhất nước ta; mùa khô kéo dài, trời nóng gần như quanh năm. Một mái nhà cao giúp khoảng không bên trong thoáng hơn, có lẽ cũng vì thế mà người xưa dựng lớp học cao như vậy. Mái ngói âm dương, với những viên ngói cong úp ngửa xen nhau, vừa chống được mưa vừa giữ mát cho lòng nhà. Vách gỗ có những song thưa để gió và ánh sáng lọt vào.\n\nĐó là lối nhà quen thuộc của người Việt ở miền Trung, được dùng cho một công năng mới. Không có phòng học riêng cho từng lớp; cả bốn lớp Tư, Ba, Nhì, Nhất cùng học dưới một mái nhà chung, với khoảng sáu mươi học trò. Nếu chia đều theo số bàn ghế hôm nay, mỗi bộ bàn ghế dành cho khoảng ba học trò. Lối bài trí ấy tiết kiệm, hợp với túi tiền của một ngôi trường sống nhờ lợi nhuận nước mắm. Nó cũng cho thấy một điều: các nhà Duy Tân Phan Thiết dồn sức cho việc dạy, chứ không cho sự bề thế của trường sở.","doc":2},{"loai":"doan","tieu_de":"Từ chiếu ngồi đến bàn ghế","text":"Để thấy 21 bộ bàn ghế có ý nghĩa gì, cần nhớ lại lớp học chữ Nho quen thuộc thời ấy. Ở trường làng, học trò thường ngồi xếp bằng trên chiếu hoặc trên phản, trước những chiếc bàn thấp, viết chữ Hán bằng bút lông trên giấy bản. Thầy đồ ngồi ở đầu lớp. Học trò đọc to, học thuộc lòng sách thánh hiền để mong một ngày lều chõng đi thi. Không có bảng đen, không có bàn ghế cao, cũng không có giờ thể dục.\n\nLớp học Dục Thanh chọn một lối khác: học trò ngồi ghế, viết trên bàn, nhìn lên bảng đen, như trong các trường học kiểu mới. Nguyễn Tất Thành hiểu rõ cả hai kiểu lớp học ấy. Thuở nhỏ, anh học chữ Hán với cha và với thầy đồ Vương Thúc Quý ở quê nhà Nghệ An. Ở Huế, anh học trường tiểu học Pháp – bản xứ Đông Ba, rồi Trường Quốc học. Khi đứng lớp ở Phan Thiết, người thầy trẻ mang theo cả vốn chữ Hán của lối học cũ lẫn nếp tổ chức lớp học của nhà trường mới. Đó chính là điều các nhà Duy Tân cần: một người vừa giảng được chữ Hán, vừa dạy được chữ Quốc ngữ, lại quen với lớp học có bàn ghế, bảng đen.","doc":3},{"loai":"ban_co_biet","text":"Khi Dục Thanh dạy chữ Quốc ngữ năm 1910, khoa cử chữ Hán vẫn còn tồn tại ở Trung Kỳ. Khoa thi Hương cuối cùng ở Trung Kỳ diễn ra năm 1918, và khoa thi Hội cuối cùng năm 1919.","nguon_ten":"Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục","doc":4},{"loai":"doan","tieu_de":"Hai tấm bảng đen","text":"Hai tấm bảng đen là món đồ mới mẻ nhất trong lớp học năm 1910. Với chữ Hán, người học phải nhớ mặt từng chữ, học nhiều năm mới đọc thông viết thạo. Chữ Quốc ngữ thì khác: chưa đầy ba mươi chữ cái và năm dấu thanh, ghép lại theo quy tắc, người học chăm chỉ có thể đọc, viết được sau một thời gian ngắn. Một tấm bảng đen và một viên phấn là đủ để thầy dạy cùng lúc cả lớp cách ghép vần, đánh dấu.\n\nCác nhà Duy Tân hiểu sức mạnh ấy. Họ coi chữ Quốc ngữ là công cụ để khai dân trí, vì nó giúp số đông nhanh chóng đọc được sách báo. Ở Dục Thanh, chữ Quốc ngữ được dạy làm chính, bên cạnh chữ Hán, chữ Pháp và thể dục. Thầy Thành dạy lớp nhì, chủ yếu chữ Quốc ngữ và chữ Hán. Ba mươi lăm năm sau, Người tin rằng biết chữ Quốc ngữ là bước đầu để dân mạnh, nước giàu. Trên cương vị Chủ tịch nước, Người phát động phong trào Bình dân học vụ (xem chuyên đề Gian nhà nơi Bác Hồ dạy học ở Dục Thanh). Tấm bảng đen ở Phan Thiết và những lớp học bình dân năm 1945 nằm trên cùng một con đường.","doc":5},{"loai":"anh","src":"textures/bang_w/G03_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Dục Thanh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Bộ trường kỷ của bảy thầy giáo","text":"Trong lớp học có một bộ họa đàn trường kỷ dành cho bảy thầy giáo. Trường kỷ là loại ghế dài bằng gỗ, có tựa và tay vịn, quen thuộc trong nhà những gia đình khá giả xưa. Ở Dục Thanh, đó là chỗ các thầy ngồi giảng bài, chấm bài. Bộ trường kỷ nằm trong số ít hiện vật gốc còn được lưu giữ từ thời thầy Thành dạy học, cùng với bộ ván gõ, án thư, tủ đứng, tráp văn thư và nghiên mài mực.\n\nBảy thầy cho khoảng sáu mươi học trò cho thấy một ngôi trường nhỏ nhưng được chăm chút. Hiệu trưởng là ông Nguyễn Quý Anh, con trai nhà thơ Nguyễn Thông. Trẻ nhất trong các thầy là Nguyễn Tất Thành, vừa tròn hai mươi tuổi. Ngồi chung một bộ trường kỷ, người thầy trẻ ở cạnh những bậc đàn anh là các nhà nho Duy Tân từng trải. Họ là đồng nghiệp, và cũng là những người giúp người thanh niên hiểu thêm về phong trào yêu nước ở Nam Trung Bộ. Bộ trường kỷ cũ kỹ vì thế không chỉ là chỗ ngồi. Nó là dấu tích của một tập thể thầy giáo nhỏ, cùng chung một chí hướng: dạy chữ để thức tỉnh lòng yêu nước.","doc":6},{"loai":"doan","tieu_de":"Bàn thầy và ngọn đèn dầu trong không gian 3D","text":"Trong gian trưng bày 3D của Bảo tàng Hành trình, lớp học được dựng lại theo tinh thần ấy. 21 bộ bàn ghế học trò xếp thành ba dãy, mỗi dãy bảy bộ, cùng hướng về phía hai tấm bảng đen. Ở đầu lớp là bàn thầy giáo, trên bàn có một ngọn đèn dầu. Người xem có thể bấm vào từng món đồ để đọc câu chuyện gắn với nó.\n\nNgọn đèn dầu là vật dụng minh họa, gợi lại cách thắp sáng của một ngôi trường nhỏ đầu thế kỷ XX. Theo cách gọi dân gian thời ấy, đèn thắp bằng dầu hỏa thường được gọi là đèn Hoa Kỳ. Đèn cần cho những buổi sinh hoạt tối của trường, như buổi thuyết trình tối thứ năm hằng tuần của học trò lớp nhất và lớp nhì (xem chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp). Đèn cũng cần cho người thầy trẻ soạn bài, đọc sách khi đêm xuống. Những món đồ trong không gian 3D không phải hiện vật gốc. Chúng được chọn để người xem hình dung đúng nếp sinh hoạt của lớp học năm 1910, và phân biệt rõ với những hiện vật thật đang được lưu giữ ở Phan Thiết.","doc":7},{"loai":"anh","src":"textures/bang_w/G03_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Dục Thanh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một lớp học tư giữa thời bắt bớ","text":"Nhìn những bộ bàn ghế mộc mạc, khó hình dung đây từng là một việc làm táo bạo. Sau phong trào chống sưu thuế năm 1908, nhiều trường học, thư xã, hội buôn theo tinh thần Duy Tân ở Trung Kỳ bị giải tán; nhiều nhà nho bị bắt, bị đày. Trong không khí ấy, một hội buôn ở Phan Thiết vẫn bỏ tiền nuôi thầy, dạy học trò chữ Quốc ngữ, kể chuyện anh hùng dân tộc, hát bài ca ái quốc. Chính quyền thuộc địa không thể không để mắt tới một ngôi trường như thế.\n\nNgôi trường còn hoạt động thêm ít lâu sau khi thầy Thành ra đi, rồi đóng cửa năm 1912. Điều đó cho thấy sức bền hiếm có của lớp học nhỏ bên sông Cà Ty. Mỗi bộ bàn ghế trong lớp vì thế gợi nhắc một chỗ ngồi của học trò Phan Thiết, được các bậc cha anh gìn giữ giữa thời bắt bớ. Người Việt tự mở trường, tự dạy con em mình, dạy bằng chữ của dân tộc mình: đó là thông điệp của lớp học gỗ, rõ ràng hơn mọi khẩu hiệu.","doc":8},{"loai":"ban_co_biet","text":"Đông Kinh Nghĩa Thục ở Hà Nội mở tháng 3/1907 và bị thực dân Pháp đóng cửa ngay cuối năm ấy. Trường Dục Thanh ra đời cùng thời nhưng còn hoạt động tới năm 1912, tức là vẫn mở cửa khi thầy Nguyễn Tất Thành đến dạy.","nguon_ten":"Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục; Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","doc":9},{"loai":"anh","src":"textures/bang_w/G03_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học Trường Dục Thanh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Lớp học hôm nay","text":"Ngày nay, lớp học là điểm dừng chân chính của du khách khi vào khu di tích. Theo VnExpress, trong tám tháng đầu năm 2026, khu di tích đón gần 1.600 đoàn khách với khoảng 117.000 lượt người. Khách có thể ngồi vào bàn học trò, nhìn lên bảng đen và bộ trường kỷ, nghe thuyết minh viên kể về người thầy giáo năm 1910. Nhiều trường học chọn nơi đây để sinh hoạt truyền thống, nhất là dịp tháng Năm và Ngày Nhà giáo Việt Nam 20/11.\n\nCó lẽ điều đặc biệt nhất của lớp học không nằm ở một món đồ nào. Nó nằm ở cảm giác được ngồi đúng chỗ học trò Phan Thiết từng ngồi, trong căn phòng mà một thầy giáo hai mươi tuổi từng giảng bài, rồi dừng lại hỏi trò đã hiểu chưa. Trong gian trưng bày 3D, người xem ở bất cứ đâu cũng có thể bước vào không gian ấy. Hai mươi mốt bộ bàn ghế vẫn để trống, như đang chờ những người học trò mới.","doc":10}],"nguon":["VnExpress (Tư Huynh, 2/9/2026) – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục"],"doc":[{"t":"Lớp học gỗ 137 mét vuông: đi một vòng quanh lớp của thầy Thành. Hai tấm bảng đen, hai mươi mốt bộ bàn ghế chia ba dãy, một bộ trường kỷ cho bảy thầy giáo: lớp học Dục Thanh không có gì cầu kỳ. Nhưng đặt vào năm 1910, khi phần đông trẻ em được đi học ở Trung Kỳ vẫn ngồi chiếu học chữ Nho, mỗi món đồ ấy là một lựa chọn mới. Hãy đi một vòng quanh lớp học, từ mái ngói xuống nền gạch, để thấy một ngôi trường Duy Tân được bài trí thế nào và vì sao."},{"t":"Bước qua ngưỡng cửa. Lớp học chính của Trường Dục Thanh là một ngôi nhà gỗ rộng khoảng 137 mét vuông, cao 4,4 mét, mái lợp ngói âm dương, tường bằng gỗ, nền lát gạch. Bước qua ngưỡng cửa, người xem thấy hai tấm bảng đen, 21 bộ bàn ghế học trò chia làm ba dãy, và một bộ họa đàn trường kỷ dành cho bảy thầy giáo. Không có gì cầu kỳ. Đó là lớp học mộc mạc của một ngôi trường tư ở tỉnh lẻ đầu thế kỷ XX, do chính những người Việt yêu nước bỏ công, bỏ của dựng nên. Cần nói ngay một điều: ngôi nhà du khách thấy hôm nay được trùng tu, phục dựng từ tháng 11/1978 đến tháng 12/1980. Việc phục dựng dựa trên lời kể và bản vẽ phác họa của những học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Vì thế, lớp học vừa là một hiện vật, vừa là một bản ghi trí nhớ. Mỗi món đồ được đặt lại theo đúng chỗ mà các cụ, sau gần bảy mươi năm, vẫn còn nhớ. Chuyên đề này đi một vòng quanh lớp, dừng lại ở từng món đồ, để hỏi xem nó nói gì về ngôi trường năm 1910 và người thầy giáo trẻ từng đứng lớp ở đây."},{"t":"Mái cao giữa đất nắng gió. Chiều cao 4,4 mét là một con số đáng chú ý với một lớp học chỉ có một tầng. Bình Thuận là một trong những vùng khô hạn, nắng gió nhất nước ta; mùa khô kéo dài, trời nóng gần như quanh năm. Một mái nhà cao giúp khoảng không bên trong thoáng hơn, có lẽ cũng vì thế mà người xưa dựng lớp học cao như vậy. Mái ngói âm dương, với những viên ngói cong úp ngửa xen nhau, vừa chống được mưa vừa giữ mát cho lòng nhà. Vách gỗ có những song thưa để gió và ánh sáng lọt vào. Đó là lối nhà quen thuộc của người Việt ở miền Trung, được dùng cho một công năng mới. Không có phòng học riêng cho từng lớp; cả bốn lớp Tư, Ba, Nhì, Nhất cùng học dưới một mái nhà chung, với khoảng sáu mươi học trò. Nếu chia đều theo số bàn ghế hôm nay, mỗi bộ bàn ghế dành cho khoảng ba học trò. Lối bài trí ấy tiết kiệm, hợp với túi tiền của một ngôi trường sống nhờ lợi nhuận nước mắm. Nó cũng cho thấy một điều: các nhà Duy Tân Phan Thiết dồn sức cho việc dạy, chứ không cho sự bề thế của trường sở."},{"t":"Từ chiếu ngồi đến bàn ghế. Để thấy 21 bộ bàn ghế có ý nghĩa gì, cần nhớ lại lớp học chữ Nho quen thuộc thời ấy. Ở trường làng, học trò thường ngồi xếp bằng trên chiếu hoặc trên phản, trước những chiếc bàn thấp, viết chữ Hán bằng bút lông trên giấy bản. Thầy đồ ngồi ở đầu lớp. Học trò đọc to, học thuộc lòng sách thánh hiền để mong một ngày lều chõng đi thi. Không có bảng đen, không có bàn ghế cao, cũng không có giờ thể dục. Lớp học Dục Thanh chọn một lối khác: học trò ngồi ghế, viết trên bàn, nhìn lên bảng đen, như trong các trường học kiểu mới. Nguyễn Tất Thành hiểu rõ cả hai kiểu lớp học ấy. Thuở nhỏ, anh học chữ Hán với cha và với thầy đồ Vương Thúc Quý ở quê nhà Nghệ An. Ở Huế, anh học trường tiểu học Pháp – bản xứ Đông Ba, rồi Trường Quốc học. Khi đứng lớp ở Phan Thiết, người thầy trẻ mang theo cả vốn chữ Hán của lối học cũ lẫn nếp tổ chức lớp học của nhà trường mới. Đó chính là điều các nhà Duy Tân cần: một người vừa giảng được chữ Hán, vừa dạy được chữ Quốc ngữ, lại quen với lớp học có bàn ghế, bảng đen."},{"t":"Bạn có biết? Khi Dục Thanh dạy chữ Quốc ngữ năm 1910, khoa cử chữ Hán vẫn còn tồn tại ở Trung Kỳ. Khoa thi Hương cuối cùng ở Trung Kỳ diễn ra năm 1918, và khoa thi Hội cuối cùng năm 1919."},{"t":"Hai tấm bảng đen. Hai tấm bảng đen là món đồ mới mẻ nhất trong lớp học năm 1910. Với chữ Hán, người học phải nhớ mặt từng chữ, học nhiều năm mới đọc thông viết thạo. Chữ Quốc ngữ thì khác: chưa đầy ba mươi chữ cái và năm dấu thanh, ghép lại theo quy tắc, người học chăm chỉ có thể đọc, viết được sau một thời gian ngắn. Một tấm bảng đen và một viên phấn là đủ để thầy dạy cùng lúc cả lớp cách ghép vần, đánh dấu. Các nhà Duy Tân hiểu sức mạnh ấy. Họ coi chữ Quốc ngữ là công cụ để khai dân trí, vì nó giúp số đông nhanh chóng đọc được sách báo. Ở Dục Thanh, chữ Quốc ngữ được dạy làm chính, bên cạnh chữ Hán, chữ Pháp và thể dục. Thầy Thành dạy lớp nhì, chủ yếu chữ Quốc ngữ và chữ Hán. Ba mươi lăm năm sau, Người tin rằng biết chữ Quốc ngữ là bước đầu để dân mạnh, nước giàu. Trên cương vị Chủ tịch nước, Người phát động phong trào Bình dân học vụ (xem chuyên đề Gian nhà nơi Bác Hồ dạy học ở Dục Thanh). Tấm bảng đen ở Phan Thiết và những lớp học bình dân năm 1945 nằm trên cùng một con đường."},{"t":"Bộ trường kỷ của bảy thầy giáo. Trong lớp học có một bộ họa đàn trường kỷ dành cho bảy thầy giáo. Trường kỷ là loại ghế dài bằng gỗ, có tựa và tay vịn, quen thuộc trong nhà những gia đình khá giả xưa. Ở Dục Thanh, đó là chỗ các thầy ngồi giảng bài, chấm bài. Bộ trường kỷ nằm trong số ít hiện vật gốc còn được lưu giữ từ thời thầy Thành dạy học, cùng với bộ ván gõ, án thư, tủ đứng, tráp văn thư và nghiên mài mực. Bảy thầy cho khoảng sáu mươi học trò cho thấy một ngôi trường nhỏ nhưng được chăm chút. Hiệu trưởng là ông Nguyễn Quý Anh, con trai nhà thơ Nguyễn Thông. Trẻ nhất trong các thầy là Nguyễn Tất Thành, vừa tròn hai mươi tuổi. Ngồi chung một bộ trường kỷ, người thầy trẻ ở cạnh những bậc đàn anh là các nhà nho Duy Tân từng trải. Họ là đồng nghiệp, và cũng là những người giúp người thanh niên hiểu thêm về phong trào yêu nước ở Nam Trung Bộ. Bộ trường kỷ cũ kỹ vì thế không chỉ là chỗ ngồi. Nó là dấu tích của một tập thể thầy giáo nhỏ, cùng chung một chí hướng: dạy chữ để thức tỉnh lòng yêu nước."},{"t":"Bàn thầy và ngọn đèn dầu trong không gian 3D. Trong gian trưng bày 3D của Bảo tàng Hành trình, lớp học được dựng lại theo tinh thần ấy. 21 bộ bàn ghế học trò xếp thành ba dãy, mỗi dãy bảy bộ, cùng hướng về phía hai tấm bảng đen. Ở đầu lớp là bàn thầy giáo, trên bàn có một ngọn đèn dầu. Người xem có thể bấm vào từng món đồ để đọc câu chuyện gắn với nó. Ngọn đèn dầu là vật dụng minh họa, gợi lại cách thắp sáng của một ngôi trường nhỏ đầu thế kỷ XX. Theo cách gọi dân gian thời ấy, đèn thắp bằng dầu hỏa thường được gọi là đèn Hoa Kỳ. Đèn cần cho những buổi sinh hoạt tối của trường, như buổi thuyết trình tối thứ năm hằng tuần của học trò lớp nhất và lớp nhì (xem chuyên đề Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp). Đèn cũng cần cho người thầy trẻ soạn bài, đọc sách khi đêm xuống. Những món đồ trong không gian 3D không phải hiện vật gốc. Chúng được chọn để người xem hình dung đúng nếp sinh hoạt của lớp học năm 1910, và phân biệt rõ với những hiện vật thật đang được lưu giữ ở Phan Thiết."},{"t":"Một lớp học tư giữa thời bắt bớ. Nhìn những bộ bàn ghế mộc mạc, khó hình dung đây từng là một việc làm táo bạo. Sau phong trào chống sưu thuế năm 1908, nhiều trường học, thư xã, hội buôn theo tinh thần Duy Tân ở Trung Kỳ bị giải tán; nhiều nhà nho bị bắt, bị đày. Trong không khí ấy, một hội buôn ở Phan Thiết vẫn bỏ tiền nuôi thầy, dạy học trò chữ Quốc ngữ, kể chuyện anh hùng dân tộc, hát bài ca ái quốc. Chính quyền thuộc địa không thể không để mắt tới một ngôi trường như thế. Ngôi trường còn hoạt động thêm ít lâu sau khi thầy Thành ra đi, rồi đóng cửa năm 1912. Điều đó cho thấy sức bền hiếm có của lớp học nhỏ bên sông Cà Ty. Mỗi bộ bàn ghế trong lớp vì thế gợi nhắc một chỗ ngồi của học trò Phan Thiết, được các bậc cha anh gìn giữ giữa thời bắt bớ. Người Việt tự mở trường, tự dạy con em mình, dạy bằng chữ của dân tộc mình: đó là thông điệp của lớp học gỗ, rõ ràng hơn mọi khẩu hiệu."},{"t":"Bạn có biết? Đông Kinh Nghĩa Thục ở Hà Nội mở tháng 3/1907 và bị thực dân Pháp đóng cửa ngay cuối năm ấy. Trường Dục Thanh ra đời cùng thời nhưng còn hoạt động tới năm 1912, tức là vẫn mở cửa khi thầy Nguyễn Tất Thành đến dạy."},{"t":"Lớp học hôm nay. Ngày nay, lớp học là điểm dừng chân chính của du khách khi vào khu di tích. Theo VnExpress, trong tám tháng đầu năm 2026, khu di tích đón gần 1.600 đoàn khách với khoảng 117.000 lượt người. Khách có thể ngồi vào bàn học trò, nhìn lên bảng đen và bộ trường kỷ, nghe thuyết minh viên kể về người thầy giáo năm 1910. Nhiều trường học chọn nơi đây để sinh hoạt truyền thống, nhất là dịp tháng Năm và Ngày Nhà giáo Việt Nam 20/11. Có lẽ điều đặc biệt nhất của lớp học không nằm ở một món đồ nào. Nó nằm ở cảm giác được ngồi đúng chỗ học trò Phan Thiết từng ngồi, trong căn phòng mà một thầy giáo hai mươi tuổi từng giảng bài, rồi dừng lại hỏi trò đã hiểu chưa. Trong gian trưng bày 3D, người xem ở bất cứ đâu cũng có thể bước vào không gian ấy. Hai mươi mốt bộ bàn ghế vẫn để trống, như đang chờ những người học trò mới."}],"so_chu":1856},{"i":10,"tieu_de_bang":"Nhà Ngọa Du Sào","tieu_de":"Ngọa Du Sào – “cái tổ để nằm mà ngao du” và thư viện nhỏ của thầy Thành","sapo":"Trong khuôn viên Trường Dục Thanh có một ngôi nhà ba gian nhiều tuổi hơn cả ngôi trường. Người dựng nó là một nhà thơ đã rời quê Nam Kỳ khi giặc tới, và đặt cho nó cái tên gợi một điển cố xưa. Ba mươi năm sau, dưới mái nhà ấy, một thầy giáo hai mươi tuổi lui tới đọc sách, làm thơ, bàn chuyện thời cuộc.","bia":{"src":"textures/bai/G03_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Ngôi nhà phía sau lớp học","text":"Đi qua lớp học và nhà Ngư, người xem gặp một ngôi nhà ba gian nằm phía sau trường. Đó là Ngọa Du Sào, do nhà thơ, nhà yêu nước Nguyễn Thông dựng năm 1880. Bên trong có tủ sách, án thư, bộ ván và một chiếc thang gỗ leo lên gác. Trên cột, trên vách treo những câu liễn, câu đối chữ Hán khắc trên gỗ. Không gian ấy mang đúng dáng một thư phòng của nhà nho xưa: nơi đọc sách, viết văn, tiếp bạn.\n\nNgọa Du Sào có trước Trường Dục Thanh gần ba mươi năm. Khi ngôi trường ra đời trên khu vườn của gia đình cụ Nguyễn Thông, căn nhà được dùng làm thư viện. Theo tư liệu của khu di tích, đây là nơi thầy Thành thường lui tới đọc sách, làm thơ, bình luận thơ văn, trao đổi thời cuộc và soạn bài. Sau năm 1975, khi phần lớn công trình của trường xưa không còn, Ngọa Du Sào là một trong số ít công trình còn đứng lại trong khuôn viên. Căn nhà được trùng tu theo dáng xưa trong những năm 1978 – 1980, cùng với lớp học và nhà Ngư.","doc":1},{"loai":"anh","src":"textures/bang_w/G03_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà Ngọa Du Sào”, nhìn từ xa."},{"loai":"doan","tieu_de":"Kỳ Xuyên Nguyễn Thông, người dựng nhà","text":"Người dựng Ngọa Du Sào là Nguyễn Thông (1827 – 1884), hiệu Kỳ Xuyên, quê ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An. Ông đỗ cử nhân năm 1849, rồi theo con đường của một nhà nho vừa làm quan, vừa lo việc học. Khi làm Đốc học Vĩnh Long, ông là một trong những người khởi xướng việc dựng Văn Thánh miếu Vĩnh Long, nơi thờ Khổng Tử và các bậc tiên hiền, nay là một di tích nổi tiếng của miền Tây Nam Bộ.\n\nKhi thực dân Pháp lần lượt chiếm Nam Kỳ, Nguyễn Thông không chịu sống dưới ách cai trị của giặc. Ông cùng nhiều sĩ phu Nam Kỳ ra Bình Thuận, vùng đất khi ấy còn thuộc quyền triều đình Huế. Việc bỏ đất bị chiếm để giữ khí tiết ấy thường được sử sách gọi là tị địa. Ở Bình Thuận, ông lo việc khai hoang, lập ấp, từng giữ chức Bố chánh (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Rồi ông chọn khu vườn bên sông Cà Ty làm nơi an cư, và năm 1880 dựng ngôi nhà nhỏ Ngọa Du Sào. Bốn năm sau, ông qua đời.","doc":2},{"loai":"doan","tieu_de":"Đọc tên nhà: Ngọa – Du – Sào","text":"Tên nhà gồm ba chữ Hán. Đọc theo âm Hán Việt, “ngọa” (臥) là nằm, “du” (遊) là đi chơi, ngao du, “sào” (巢) là cái tổ. Ghép lại, Ngọa Du Sào có thể hiểu là “cái tổ để nằm mà ngao du”. Chữ “sào” rất khiêm nhường. Chủ nhân không gọi nhà mình là dinh, là phủ hay là đường, mà chỉ là một cái tổ, nhỏ bé như tổ chim giữa vườn.\n\nHai chữ “ngọa du” lại là một điển cố quen thuộc với giới nho sĩ, nói về thú ngao du bằng tâm tưởng khi thân không còn đi xa được. Có thể hiểu Nguyễn Thông mượn ý ấy để gửi vào tên nhà một tâm sự. Rời việc quan, sống ở đất khách, ông thả hồn theo sách vở, theo non sông trong căn nhà nhỏ. Với một nhà nho đã bỏ lại mảnh đất Nam Kỳ bị chiếm, cái tên còn mang một nỗi niềm riêng: quê hương giờ chỉ còn đến được bằng trí nhớ và văn chương. Nằm mà ngao du, nhưng không phải để quên đời. Ngay trên mảnh vườn ấy, về sau, các con ông mở một ngôi trường để đánh thức lớp trẻ.","doc":3},{"loai":"ban_co_biet","text":"Hai chữ “ngọa du” (nằm mà ngao du) gắn với chuyện họa sĩ Tông Bính thời Nam triều Tống bên Trung Hoa. Về già, sợ không còn đi thăm hết núi non được nữa, ông vẽ những nơi từng đi qua lên vách nhà để nằm mà ngắm.","nguon_ten":"Tống thư, phần Tông Bính truyện","doc":4},{"loai":"doan","tieu_de":"Căn nhà của một nhà thơ","text":"Nguyễn Thông để lại nhiều thơ văn chữ Hán, sau được tập hợp trong những tập như Kỳ Xuyên văn sao, Ngọa Du Sào văn tập. Ông còn là người khảo cứu lịch sử, với sách Việt sử cương giám khảo lược. Trong văn, ông tả nơi ở bên sông Cà Ty với con rạch chảy vào tận nhà. Có những buổi sáng chim quốc kêu, những bãi bần, bãi đước lộ ra khi nước ròng (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ngọa Du Sào là nơi ông sống những năm cuối đời, đọc sách, viết văn, tiếp bạn.\n\nÔng mất năm 1884. Khu vườn và ngôi nhà được con cháu gìn giữ. Hai người con trai của ông, Nguyễn Trọng Lội và Nguyễn Quý Anh, về sau trở thành những nhà Duy Tân của Phan Thiết. Tinh thần của người cha, không chịu sống dưới ách giặc và rất coi trọng việc học, được hai người con tiếp nối bằng một cách mới. Họ cùng các bạn đồng chí lập hội buôn Liên Thành năm 1906, rồi mở Trường Dục Thanh ngay trên khu vườn của gia đình. Ngôi nhà của cha trở thành thư viện của trường.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh.jpg","chu_thich":"Những nếp nhà gỗ của khu di tích Trường Dục Thanh, Phan Thiết. Ngọa Du Sào nằm phía sau lớp học, trong cùng khuôn viên. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ thư phòng thành thư viện","text":"Khi Trường Dục Thanh ra đời, tủ sách của một nhà nho trở thành tủ sách chung của thầy trò. Trong phong trào Duy Tân, đọc sách là một việc hệ trọng. Các nhà nho cấp tiến truyền tay nhau những “tân thư”, tức sách báo mới, phần nhiều viết bằng chữ Hán. Những sách ấy giới thiệu học thuyết phương Tây và những cuộc duy tân ở Nhật Bản, Trung Hoa. Qua đó, nhà nho Việt biết tới tư tưởng dân quyền của Rousseau, Montesquieu, hay các bài viết của Khang Hữu Vi, Lương Khải Siêu.\n\nTư liệu hiện biết không cho biết cụ thể thư viện Dục Thanh có những cuốn sách nào. Nhưng với một ngôi trường do các nhà Duy Tân lập ra, lấy chương trình theo khuôn Đông Kinh Nghĩa Thục, có thể hình dung trên giá có sách chữ Hán của gia đình cụ Nguyễn Thông bên cạnh những sách báo mới. Đó là một thư viện nhỏ ở tỉnh lẻ. Nhưng với người thầy giáo trẻ đang tự hỏi làm thế nào để cứu nước, nó là một ô cửa sổ nhìn ra thế giới, ngay giữa khu vườn bên sông.","doc":6},{"loai":"ban_co_biet","text":"Nguyễn Thông mất năm 1884, sáu năm trước khi Nguyễn Tất Thành ra đời. Người thầy giáo trẻ chưa từng gặp chủ nhân Ngọa Du Sào, nhưng đã đọc sách dưới mái nhà ông và dạy học trên mảnh vườn của gia đình ông.","nguon_ten":"Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng; VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết","doc":7},{"loai":"doan","tieu_de":"Đọc sách, làm thơ, bàn thời cuộc","text":"Theo tư liệu của khu di tích, được VnExpress ghi lại, Ngọa Du Sào là nơi thầy Thành thường lui tới đọc sách, làm thơ, bình luận thơ văn và trao đổi thời cuộc. Chi tiết “làm thơ” cho thấy một nét ít được nhắc tới ở người thanh niên hai mươi tuổi: vốn Hán học đủ để cùng các nhà nho lớn tuổi bình văn, luận thơ. Người con của cụ Phó bảng Nguyễn Sinh Sắc lớn lên giữa sách vở, và thói quen ấy theo Người suốt đời. Hơn ba mươi năm sau, trong nhà tù của chính quyền Tưởng Giới Thạch, Người viết tập thơ chữ Hán Nhật ký trong tù.\n\nThời cuộc năm 1910 là những chuyện gì? Đó là những năm Nhật Bản vừa thắng Nga năm 1905, khơi dậy hy vọng ở nhiều nhà nho châu Á. Phong trào Đông Du của Phan Bội Châu đưa thanh niên sang Nhật học, rồi tan rã năm 1909. Phong trào Duy Tân ở Trung Kỳ bị đàn áp sau năm 1908. Ngồi trong thư viện nhỏ, người thanh niên nghe, đọc và nghĩ về những con đường cứu nước ấy. Không lâu sau, Người chọn một hướng khác: sang phương Tây, tận mắt xem các nước ấy làm thế nào.","doc":8},{"loai":"anh","src":"textures/bang_w/G03_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà Ngọa Du Sào”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Căn gác gỗ và bộ ván","text":"Ngọa Du Sào có một chi tiết kiến trúc dễ gây chú ý: căn gác gỗ, lên bằng một chiếc thang. Dưới gác, ba gian nhà bày án thư, tủ sách và bộ ván, những món đồ quen thuộc của thư phòng nhà nho. Án thư là chiếc bàn dài, hẹp, để đặt sách vở, bút nghiên. Bộ ván là tấm phản gỗ lớn, ban ngày ngồi đọc sách, tiếp khách, khi mỏi có thể ngả lưng. Những câu liễn, câu đối chữ Hán khắc gỗ trên cột, trên vách cho biết đây là nhà của người trọng chữ nghĩa.\n\nCần phân biệt rõ một điều. Có bài viết phổ thông ghi Ngọa Du Sào là nơi thầy Thành ở. Nhưng theo tư liệu của khu di tích, chỗ ở nội trú của thầy trò Dục Thanh là nhà Ngư (xem chuyên đề Giếng nước). Ngọa Du Sào là thư viện, nơi thầy lui tới những lúc ngoài giờ lên lớp. Trong gian trưng bày 3D, góc Ngọa Du Sào được tái hiện với chiếc phản gỗ và chiếc bàn đọc sách. Đó là những vật dụng minh họa, không phải hiện vật gốc, được chọn để gợi lại không khí thư phòng nơi người thầy trẻ ngồi đọc sách, soạn bài cho lớp nhì của mình.","doc":9},{"loai":"anh","src":"textures/bang_w/G03_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà Ngọa Du Sào”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Ngọa Du Sào hôm nay","text":"Ngày nay, Ngọa Du Sào nằm trong khu di tích Trường Dục Thanh, rộng khoảng 4.090 mét vuông, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận quản lý. Khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986. Du khách thường ghé ngôi nhà ba gian sau khi xem lớp học, rồi ra khu vườn phía sau, nơi có giếng nước và cây khế. Trong khuôn viên còn có nhà thờ cụ Nguyễn Thông và dòng họ.\n\nNgôi nhà nhỏ nối ba thế hệ người yêu nước. Người cha dựng nó khi đã bỏ lại quê hương bị chiếm, gửi chí vào thơ văn. Hai người con mở trường ngay bên cạnh, biến thư phòng thành thư viện. Rồi một người thanh niên xứ Nghệ đến, đọc sách dưới mái nhà ấy, trước khi ra đi tìm một con đường mới cho cả dân tộc. Đứng trước Ngọa Du Sào, người xem hôm nay có thể thấy ba lớp thời gian chồng lên nhau trong một căn nhà ba gian: nỗi đau mất đất, khát vọng duy tân, và buổi đầu của một hành trình lớn.","doc":10}],"nguon":["VnExpress (Tư Huynh, 2/9/2026) – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành","Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","Đại cương lịch sử Việt Nam, tập II, NXB Giáo dục","Tống thư, phần Tông Bính truyện"],"doc":[{"t":"Ngọa Du Sào – “cái tổ để nằm mà ngao du” và thư viện nhỏ của thầy Thành. Trong khuôn viên Trường Dục Thanh có một ngôi nhà ba gian nhiều tuổi hơn cả ngôi trường. Người dựng nó là một nhà thơ đã rời quê Nam Kỳ khi giặc tới, và đặt cho nó cái tên gợi một điển cố xưa. Ba mươi năm sau, dưới mái nhà ấy, một thầy giáo hai mươi tuổi lui tới đọc sách, làm thơ, bàn chuyện thời cuộc."},{"t":"Ngôi nhà phía sau lớp học. Đi qua lớp học và nhà Ngư, người xem gặp một ngôi nhà ba gian nằm phía sau trường. Đó là Ngọa Du Sào, do nhà thơ, nhà yêu nước Nguyễn Thông dựng năm 1880. Bên trong có tủ sách, án thư, bộ ván và một chiếc thang gỗ leo lên gác. Trên cột, trên vách treo những câu liễn, câu đối chữ Hán khắc trên gỗ. Không gian ấy mang đúng dáng một thư phòng của nhà nho xưa: nơi đọc sách, viết văn, tiếp bạn. Ngọa Du Sào có trước Trường Dục Thanh gần ba mươi năm. Khi ngôi trường ra đời trên khu vườn của gia đình cụ Nguyễn Thông, căn nhà được dùng làm thư viện. Theo tư liệu của khu di tích, đây là nơi thầy Thành thường lui tới đọc sách, làm thơ, bình luận thơ văn, trao đổi thời cuộc và soạn bài. Sau năm 1975, khi phần lớn công trình của trường xưa không còn, Ngọa Du Sào là một trong số ít công trình còn đứng lại trong khuôn viên. Căn nhà được trùng tu theo dáng xưa trong những năm 1978 – 1980, cùng với lớp học và nhà Ngư."},{"t":"Kỳ Xuyên Nguyễn Thông, người dựng nhà. Người dựng Ngọa Du Sào là Nguyễn Thông (1827 – 1884), hiệu Kỳ Xuyên, quê ở phủ Tân An, tỉnh Gia Định cũ, nay thuộc Long An. Ông đỗ cử nhân năm 1849, rồi theo con đường của một nhà nho vừa làm quan, vừa lo việc học. Khi làm Đốc học Vĩnh Long, ông là một trong những người khởi xướng việc dựng Văn Thánh miếu Vĩnh Long, nơi thờ Khổng Tử và các bậc tiên hiền, nay là một di tích nổi tiếng của miền Tây Nam Bộ. Khi thực dân Pháp lần lượt chiếm Nam Kỳ, Nguyễn Thông không chịu sống dưới ách cai trị của giặc. Ông cùng nhiều sĩ phu Nam Kỳ ra Bình Thuận, vùng đất khi ấy còn thuộc quyền triều đình Huế. Việc bỏ đất bị chiếm để giữ khí tiết ấy thường được sử sách gọi là tị địa. Ở Bình Thuận, ông lo việc khai hoang, lập ấp, từng giữ chức Bố chánh (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Rồi ông chọn khu vườn bên sông Cà Ty làm nơi an cư, và năm 1880 dựng ngôi nhà nhỏ Ngọa Du Sào. Bốn năm sau, ông qua đời."},{"t":"Đọc tên nhà: Ngọa – Du – Sào. Tên nhà gồm ba chữ Hán. Đọc theo âm Hán Việt, “ngọa” (臥) là nằm, “du” (遊) là đi chơi, ngao du, “sào” (巢) là cái tổ. Ghép lại, Ngọa Du Sào có thể hiểu là “cái tổ để nằm mà ngao du”. Chữ “sào” rất khiêm nhường. Chủ nhân không gọi nhà mình là dinh, là phủ hay là đường, mà chỉ là một cái tổ, nhỏ bé như tổ chim giữa vườn. Hai chữ “ngọa du” lại là một điển cố quen thuộc với giới nho sĩ, nói về thú ngao du bằng tâm tưởng khi thân không còn đi xa được. Có thể hiểu Nguyễn Thông mượn ý ấy để gửi vào tên nhà một tâm sự. Rời việc quan, sống ở đất khách, ông thả hồn theo sách vở, theo non sông trong căn nhà nhỏ. Với một nhà nho đã bỏ lại mảnh đất Nam Kỳ bị chiếm, cái tên còn mang một nỗi niềm riêng: quê hương giờ chỉ còn đến được bằng trí nhớ và văn chương. Nằm mà ngao du, nhưng không phải để quên đời. Ngay trên mảnh vườn ấy, về sau, các con ông mở một ngôi trường để đánh thức lớp trẻ."},{"t":"Bạn có biết? Hai chữ “ngọa du” (nằm mà ngao du) gắn với chuyện họa sĩ Tông Bính thời Nam triều Tống bên Trung Hoa. Về già, sợ không còn đi thăm hết núi non được nữa, ông vẽ những nơi từng đi qua lên vách nhà để nằm mà ngắm."},{"t":"Căn nhà của một nhà thơ. Nguyễn Thông để lại nhiều thơ văn chữ Hán, sau được tập hợp trong những tập như Kỳ Xuyên văn sao, Ngọa Du Sào văn tập. Ông còn là người khảo cứu lịch sử, với sách Việt sử cương giám khảo lược. Trong văn, ông tả nơi ở bên sông Cà Ty với con rạch chảy vào tận nhà. Có những buổi sáng chim quốc kêu, những bãi bần, bãi đước lộ ra khi nước ròng (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ). Ngọa Du Sào là nơi ông sống những năm cuối đời, đọc sách, viết văn, tiếp bạn. Ông mất năm 1884. Khu vườn và ngôi nhà được con cháu gìn giữ. Hai người con trai của ông, Nguyễn Trọng Lội và Nguyễn Quý Anh, về sau trở thành những nhà Duy Tân của Phan Thiết. Tinh thần của người cha, không chịu sống dưới ách giặc và rất coi trọng việc học, được hai người con tiếp nối bằng một cách mới. Họ cùng các bạn đồng chí lập hội buôn Liên Thành năm 1906, rồi mở Trường Dục Thanh ngay trên khu vườn của gia đình. Ngôi nhà của cha trở thành thư viện của trường."},{"t":"Từ thư phòng thành thư viện. Khi Trường Dục Thanh ra đời, tủ sách của một nhà nho trở thành tủ sách chung của thầy trò. Trong phong trào Duy Tân, đọc sách là một việc hệ trọng. Các nhà nho cấp tiến truyền tay nhau những “tân thư”, tức sách báo mới, phần nhiều viết bằng chữ Hán. Những sách ấy giới thiệu học thuyết phương Tây và những cuộc duy tân ở Nhật Bản, Trung Hoa. Qua đó, nhà nho Việt biết tới tư tưởng dân quyền của Rousseau, Montesquieu, hay các bài viết của Khang Hữu Vi, Lương Khải Siêu. Tư liệu hiện biết không cho biết cụ thể thư viện Dục Thanh có những cuốn sách nào. Nhưng với một ngôi trường do các nhà Duy Tân lập ra, lấy chương trình theo khuôn Đông Kinh Nghĩa Thục, có thể hình dung trên giá có sách chữ Hán của gia đình cụ Nguyễn Thông bên cạnh những sách báo mới. Đó là một thư viện nhỏ ở tỉnh lẻ. Nhưng với người thầy giáo trẻ đang tự hỏi làm thế nào để cứu nước, nó là một ô cửa sổ nhìn ra thế giới, ngay giữa khu vườn bên sông."},{"t":"Bạn có biết? Nguyễn Thông mất năm 1884, sáu năm trước khi Nguyễn Tất Thành ra đời. Người thầy giáo trẻ chưa từng gặp chủ nhân Ngọa Du Sào, nhưng đã đọc sách dưới mái nhà ông và dạy học trên mảnh vườn của gia đình ông."},{"t":"Đọc sách, làm thơ, bàn thời cuộc. Theo tư liệu của khu di tích, được VnExpress ghi lại, Ngọa Du Sào là nơi thầy Thành thường lui tới đọc sách, làm thơ, bình luận thơ văn và trao đổi thời cuộc. Chi tiết “làm thơ” cho thấy một nét ít được nhắc tới ở người thanh niên hai mươi tuổi: vốn Hán học đủ để cùng các nhà nho lớn tuổi bình văn, luận thơ. Người con của cụ Phó bảng Nguyễn Sinh Sắc lớn lên giữa sách vở, và thói quen ấy theo Người suốt đời. Hơn ba mươi năm sau, trong nhà tù của chính quyền Tưởng Giới Thạch, Người viết tập thơ chữ Hán Nhật ký trong tù. Thời cuộc năm 1910 là những chuyện gì? Đó là những năm Nhật Bản vừa thắng Nga năm 1905, khơi dậy hy vọng ở nhiều nhà nho châu Á. Phong trào Đông Du của Phan Bội Châu đưa thanh niên sang Nhật học, rồi tan rã năm 1909. Phong trào Duy Tân ở Trung Kỳ bị đàn áp sau năm 1908. Ngồi trong thư viện nhỏ, người thanh niên nghe, đọc và nghĩ về những con đường cứu nước ấy. Không lâu sau, Người chọn một hướng khác: sang phương Tây, tận mắt xem các nước ấy làm thế nào."},{"t":"Căn gác gỗ và bộ ván. Ngọa Du Sào có một chi tiết kiến trúc dễ gây chú ý: căn gác gỗ, lên bằng một chiếc thang. Dưới gác, ba gian nhà bày án thư, tủ sách và bộ ván, những món đồ quen thuộc của thư phòng nhà nho. Án thư là chiếc bàn dài, hẹp, để đặt sách vở, bút nghiên. Bộ ván là tấm phản gỗ lớn, ban ngày ngồi đọc sách, tiếp khách, khi mỏi có thể ngả lưng. Những câu liễn, câu đối chữ Hán khắc gỗ trên cột, trên vách cho biết đây là nhà của người trọng chữ nghĩa. Cần phân biệt rõ một điều. Có bài viết phổ thông ghi Ngọa Du Sào là nơi thầy Thành ở. Nhưng theo tư liệu của khu di tích, chỗ ở nội trú của thầy trò Dục Thanh là nhà Ngư (xem chuyên đề Giếng nước). Ngọa Du Sào là thư viện, nơi thầy lui tới những lúc ngoài giờ lên lớp. Trong gian trưng bày 3D, góc Ngọa Du Sào được tái hiện với chiếc phản gỗ và chiếc bàn đọc sách. Đó là những vật dụng minh họa, không phải hiện vật gốc, được chọn để gợi lại không khí thư phòng nơi người thầy trẻ ngồi đọc sách, soạn bài cho lớp nhì của mình."},{"t":"Ngọa Du Sào hôm nay. Ngày nay, Ngọa Du Sào nằm trong khu di tích Trường Dục Thanh, rộng khoảng 4.090 mét vuông, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận quản lý. Khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986. Du khách thường ghé ngôi nhà ba gian sau khi xem lớp học, rồi ra khu vườn phía sau, nơi có giếng nước và cây khế. Trong khuôn viên còn có nhà thờ cụ Nguyễn Thông và dòng họ. Ngôi nhà nhỏ nối ba thế hệ người yêu nước. Người cha dựng nó khi đã bỏ lại quê hương bị chiếm, gửi chí vào thơ văn. Hai người con mở trường ngay bên cạnh, biến thư phòng thành thư viện. Rồi một người thanh niên xứ Nghệ đến, đọc sách dưới mái nhà ấy, trước khi ra đi tìm một con đường mới cho cả dân tộc. Đứng trước Ngọa Du Sào, người xem hôm nay có thể thấy ba lớp thời gian chồng lên nhau trong một căn nhà ba gian: nỗi đau mất đất, khát vọng duy tân, và buổi đầu của một hành trình lớn."}],"so_chu":1802},{"i":11,"tieu_de_bang":"Giếng nước","tieu_de":"Giếng gạch giữa sân và nếp sống nội trú của thầy trò Dục Thanh","sapo":"Ở Dục Thanh, chiếc giếng gạch giữa sân là hiện vật gần với đời thường của thầy Thành hơn cả. Quanh nó là cả một nếp sống nội trú: thầy trò cùng ở, cùng dậy sớm, cùng lo liệu việc chung. Ở một thị xã nắng gió bên cửa biển, nơi khoảng hai mươi năm sau mới có tháp nước, giếng nước ngọt là thứ quý. Câu chuyện của chiếc giếng vì thế cũng là câu chuyện về một lối sống giản dị theo Người suốt đời.","bia":{"src":"textures/bai/G03_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Chiếc giếng giữa khu vườn trường","text":"Trong sân Trường Dục Thanh, phía sau ngôi nhà Ngọa Du Sào, có một chiếc giếng xây bằng gạch, nằm gần cây khế cổ thụ. Theo tư liệu của khu di tích, đây là nguồn nước sinh hoạt của thầy trò Dục Thanh ngày ấy, và cũng là chiếc giếng thầy Thành dùng nước hằng ngày. Cùng với cây khế và Ngọa Du Sào, chiếc giếng thuộc số ít chứng tích gốc còn lại từ thời thầy Thành dạy học; lớp học và nhà Ngư hôm nay đều được phục dựng về sau.\n\nTuổi đời của chiếc giếng, thói quen thầy Thành múc nước tưới cây khế và tình yêu cây xanh suốt đời của Bác đã được kể trong chuyên đề Giếng nước trong sân Trường Dục Thanh. Ở đây, chiếc giếng dẫn ta tới một câu chuyện khác: đời sống nội trú của một ngôi trường nhỏ, và giá trị của nước ngọt ở một thị xã bên cửa biển đầu thế kỷ XX. Nếu lớp học cho biết thầy Thành dạy gì, thư viện Ngọa Du Sào cho biết thầy đọc gì, thì chiếc giếng nhắc tới phần đời thường nhất: thầy đã sống ra sao trong những tháng ở Phan Thiết.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_gieng_truong_duc_thanh.jpg","chu_thich":"Chiếc giếng gạch trong sân Trường Dục Thanh, nguồn nước sinh hoạt của thầy trò nội trú năm 1910. Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Nước ngọt ở đất nắng gió","text":"Bình Thuận là một trong những vùng khô hạn nhất nước ta. Mùa khô kéo dài nhiều tháng, nắng gắt, gió mạnh, lượng mưa ít hơn hẳn nhiều nơi khác. Phan Thiết lại nằm ở cửa sông, sát biển; khi triều lên, nước mặn theo dòng Cà Ty ngược vào thị xã. Nước sông vùng cửa biển vì thế thường lợ, khó dùng để ăn uống. Với các gia đình ở đây, một chiếc giếng nước ngọt trong vườn là tài sản quý.\n\nNăm 1910, Phan Thiết chưa có tháp nước và hệ thống cấp nước như sau này. Tháp nước, nay là biểu tượng của thành phố, được dựng vào khoảng những năm 1928 – 1934, tức khoảng hai mươi năm sau khi thầy Thành rời Dục Thanh. Trước đó, mọi việc từ nấu ăn, tắm giặt đến tưới cây đều trông vào giếng và nước mưa. Chiếc giếng trong vườn nhà cụ Nguyễn Thông vì thế không chỉ phục vụ một gia đình. Khi trường mở và có nội trú, nó trở thành nguồn nước hằng ngày của cả một cộng đồng thầy trò. Mỗi gàu nước kéo lên từ lòng giếng là một phần của nếp sinh hoạt chung ấy.","doc":2},{"loai":"doan","tieu_de":"Nhà Ngư: từ kho ngư cụ thành chỗ ở nội trú","text":"Chỗ ở của thầy trò Dục Thanh là nhà Ngư, dựng năm 1906. Chữ “ngư” nghĩa là cá. Đúng như tên gọi, ban đầu gia đình cụ Nguyễn Thông dùng ngôi nhà để chứa ngư cụ và làm nước mắm. Khi trường mở, nhà Ngư được sửa sang thành chỗ ở nội trú cho thầy giáo và những học trò ở xa đến học. Một ngôi nhà từng chứa lưới, chứa thùng nay thành chỗ ngả lưng của thầy trò. Cách dùng lại ấy nói lên nếp tiết kiệm của những nhà nho đi buôn để nuôi trường.\n\nTrong những tháng dạy học ở Phan Thiết, thầy Thành sống ngay trong khuôn viên trường. Thầy là người trẻ nhất trong số các thầy giáo. Sống nội trú, thầy không chỉ gặp học trò trong giờ học, mà cả lúc sáng sớm ra sân tập, lúc chiều muộn sau giờ tan lớp. Có lẽ vì thế mà học trò cũ, mấy chục năm sau, vẫn nhớ thầy như một người vừa nghiêm vừa gần gũi, như một người bạn lớn. Nhà Ngư hôm nay là công trình được phục dựng trong những năm 1978 – 1980, theo lời kể của những học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ).","doc":3},{"loai":"anh","src":"textures/bang_w/G03_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước”, nhìn từ xa."},{"loai":"doan","tieu_de":"Giếng nước trong tâm thức người Việt","text":"Với người Việt, giếng nước không chỉ là chỗ lấy nước. Hình ảnh cây đa, giếng nước, sân đình từ lâu là biểu tượng của làng quê. Giếng làng là nơi người ta gặp nhau mỗi sớm mỗi chiều, nơi chuyện làng chuyện xóm được kể cho nhau nghe. Trong nhiều gia đình, chiếc giếng được đào, được xây từ đời ông bà, rồi con cháu dùng tiếp qua nhiều thế hệ. Nước giếng vì thế gắn với ý niệm về nguồn cội.\n\nChiếc giếng ở Dục Thanh cũng mang dáng dấp ấy. Nó được gia đình nhà thơ Nguyễn Thông xây để dùng, rồi phục vụ ngôi trường do các con ông lập ra, rồi cho người thầy giáo trẻ từ xứ Nghệ nước dùng hằng ngày. Bên cạnh là cây khế do phu nhân cụ Nguyễn Thông trồng. Người xưa dạy “uống nước nhớ nguồn”, “ăn quả nhớ kẻ trồng cây”. Hiếm có nơi nào hai câu tục ngữ ấy hiện ra cụ thể như ở góc vườn này: một chiếc giếng và một cây khế, cả hai đều do người đi trước để lại cho người đến sau.","doc":4},{"loai":"ban_co_biet","text":"Ở làng Sen, quê nội của Bác thuộc xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, giếng Cốc được gìn giữ như một chứng tích gắn với những kỷ niệm thời niên thiếu của Người.","nguon_ten":"Báo Nghệ An – Giếng Cốc, nơi gắn bó những kỷ niệm thời niên thiếu của Bác","doc":5},{"loai":"doan","tieu_de":"Từ giếng làng Sen đến bờ suối Pác Bó","text":"Nước gắn với nhiều chặng trong đời Người. Thuở nhỏ, cậu bé Nguyễn Sinh Cung lớn lên ở làng Sen, bên những giếng làng, ao sen của một làng quê xứ Nghệ. Năm 1910, ở Phan Thiết, người thầy giáo trẻ dùng nước từ chiếc giếng gạch trong vườn trường. Ba mươi năm sau, ngày 28/1/1941, Người về nước qua cột mốc 108 và sống ở Pác Bó, Cao Bằng. Ở đó, Người ở trong hang Cốc Bó, làm việc bên bờ suối, ăn cháo bẹ, rau măng, vẫn giữ nếp sinh hoạt đều đặn, giản dị.\n\nChính những ngày gian khổ ấy đã đi vào bài thơ Tức cảnh Pác Bó, sáng tác năm 1941. Bài thơ không than thở. Nó ghi lại cuộc sống hằng ngày bằng một giọng vui, thậm chí hóm hỉnh: sáng ra bờ suối, tối vào hang, ngồi bàn đá chông chênh mà dịch sử Đảng. Từ chiếc giếng ở Dục Thanh đến dòng suối ở Pác Bó, có thể thấy một điều không đổi. Dù ở đâu, người thanh niên năm nào vẫn sống giản dị giữa những gì thiên nhiên và người lao động quanh mình có.","doc":6},{"loai":"trich","text":"Sáng ra bờ suối, tối vào hang,\nCháo bẹ rau măng vẫn sẵn sàng.\nBàn đá chông chênh dịch sử Đảng,\nCuộc đời cách mạng thật là sang.","nguoi":"Hồ Chí Minh","nguon_ten":"Bài thơ Tức cảnh Pác Bó, năm 1941 – in trong Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":7},{"loai":"ban_co_biet","text":"Về sống ở Pác Bó năm 1941, Bác đặt tên cho dòng suối trước hang Cốc Bó là suối Lê-nin, và ngọn núi bên cạnh là núi Các Mác.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","doc":8},{"loai":"doan","tieu_de":"Một nếp sống giản dị","text":"Lối sống nội trú ở Dục Thanh, cùng ở với học trò, tự lo lấy việc hằng ngày bên chiếc giếng giữa sân, là một trong những dấu vết sớm của nếp sống giản dị ở Hồ Chí Minh. Trên cương vị Chủ tịch nước, Người vẫn giữ nếp ấy. Cuối năm 1954, khi về làm việc ở khu Phủ Chủ tịch, Người không ở trong tòa nhà lớn của Phủ Toàn quyền cũ, mà chọn một ngôi nhà nhỏ vốn dành cho người thợ điện trong khuôn viên. Từ tháng 5/1958, Người sống và làm việc trong ngôi nhà sàn gỗ đơn sơ bên ao cá, quanh nhà là vườn cây và hàng râm bụt.\n\nKhông thể nói nếp sống ấy bắt đầu từ Phan Thiết. Nó có gốc từ gia đình nhà nho thanh bạch ở xứ Nghệ, và được rèn qua ba mươi năm lao động, bôn ba ở nước ngoài. Nhưng chiếc giếng gạch ở Dục Thanh là một chứng tích cụ thể, hiếm hoi còn lại, cho thấy người thanh niên hai mươi tuổi đã sống thế nào. Thầy tự múc nước, tự lo việc thường ngày, ở chung với học trò dưới một mái nhà đơn sơ vốn là kho chứa ngư cụ.","doc":9},{"loai":"anh","src":"textures/bang_w/G03_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chiếc giếng trong không gian 3D","text":"Trong gian trưng bày 3D, chiếc giếng được đặt ở một góc sân, cách bảng chuyên đề này chỉ vài bước chân, tách khỏi dãy bàn ghế của lớp học. Người xem có thể bấm vào giếng để đọc câu chuyện về nguồn nước sinh hoạt của thầy trò Dục Thanh. Mô hình giếng là vật minh họa. Chiếc giếng thật vẫn nằm trong khu vườn phía sau Ngọa Du Sào, ở khu di tích Trường Dục Thanh, Phan Thiết.\n\nĐể hình dung trọn một ngày của thầy Thành, người xem có thể đi theo một vòng nhỏ trong gian trưng bày. Bắt đầu từ lớp học với hai tấm bảng đen và hai mươi mốt bộ bàn ghế, nơi thầy đứng lớp nhì. Sang góc Ngọa Du Sào với chiếc phản và bàn đọc sách, nơi thầy lui tới đọc sách, soạn bài. Rồi dừng lại bên chiếc giếng, nơi thầy trở về với những việc thường ngày. Ba điểm dừng ấy ghép lại thành chân dung đầy đủ hơn của người thầy giáo trẻ: dạy học, tự học và sống giản dị.","doc":10},{"loai":"anh","src":"textures/bang_w/G03_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Giếng nước”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: về nguồn","text":"Ngày nay, chiếc giếng gạch vẫn nằm yên trong khu di tích Trường Dục Thanh, cạnh cây khế cổ thụ, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận gìn giữ. Du khách được ngắm giếng, chụp ảnh bên thành giếng, nghe thuyết minh viên kể về những tháng ngày thầy Thành sống nội trú ở đây. Không phải ngẫu nhiên mà nhiều trường học, đoàn thanh niên chọn Dục Thanh làm điểm đến về nguồn, nhất là dịp tháng Năm, tháng sinh của Bác.\n\nChiếc giếng nhỏ nhắc các thế hệ sau về một nguồn cội đặc biệt. Ở đây, người thanh niên Nguyễn Tất Thành, trước khi mang tên Nguyễn Ái Quốc rồi Hồ Chí Minh, đã sống những ngày bình dị của một thầy giáo ở ngôi trường nhỏ ven biển. Trong những ngày ấy không có sự kiện lớn nào. Chỉ có những sớm dậy tập thể dục, những giờ đứng lớp, những buổi đọc sách và những gàu nước kéo lên từ lòng giếng. Nhưng chính từ những ngày bình dị ấy, người xem hôm nay hiểu hơn tuổi trẻ của Người, và hiểu vì sao người thanh niên ấy đủ sức cho một hành trình dài ba mươi năm.","doc":11}],"nguon":["Dân Việt – Trường Dục Thanh, nơi thầy giáo Nguyễn Tất Thành dạy học","Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","VnExpress (Tư Huynh, 2/9/2026) – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết – https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html","VnExpress – Tháp nước Phan Thiết gần 90 năm tuổi","Báo Nghệ An – Giếng Cốc, nơi gắn bó những kỷ niệm thời niên thiếu của Bác","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia; Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia"],"doc":[{"t":"Giếng gạch giữa sân và nếp sống nội trú của thầy trò Dục Thanh. Ở Dục Thanh, chiếc giếng gạch giữa sân là hiện vật gần với đời thường của thầy Thành hơn cả. Quanh nó là cả một nếp sống nội trú: thầy trò cùng ở, cùng dậy sớm, cùng lo liệu việc chung. Ở một thị xã nắng gió bên cửa biển, nơi khoảng hai mươi năm sau mới có tháp nước, giếng nước ngọt là thứ quý. Câu chuyện của chiếc giếng vì thế cũng là câu chuyện về một lối sống giản dị theo Người suốt đời."},{"t":"Chiếc giếng giữa khu vườn trường. Trong sân Trường Dục Thanh, phía sau ngôi nhà Ngọa Du Sào, có một chiếc giếng xây bằng gạch, nằm gần cây khế cổ thụ. Theo tư liệu của khu di tích, đây là nguồn nước sinh hoạt của thầy trò Dục Thanh ngày ấy, và cũng là chiếc giếng thầy Thành dùng nước hằng ngày. Cùng với cây khế và Ngọa Du Sào, chiếc giếng thuộc số ít chứng tích gốc còn lại từ thời thầy Thành dạy học; lớp học và nhà Ngư hôm nay đều được phục dựng về sau. Tuổi đời của chiếc giếng, thói quen thầy Thành múc nước tưới cây khế và tình yêu cây xanh suốt đời của Bác đã được kể trong chuyên đề Giếng nước trong sân Trường Dục Thanh. Ở đây, chiếc giếng dẫn ta tới một câu chuyện khác: đời sống nội trú của một ngôi trường nhỏ, và giá trị của nước ngọt ở một thị xã bên cửa biển đầu thế kỷ XX. Nếu lớp học cho biết thầy Thành dạy gì, thư viện Ngọa Du Sào cho biết thầy đọc gì, thì chiếc giếng nhắc tới phần đời thường nhất: thầy đã sống ra sao trong những tháng ở Phan Thiết."},{"t":"Nước ngọt ở đất nắng gió. Bình Thuận là một trong những vùng khô hạn nhất nước ta. Mùa khô kéo dài nhiều tháng, nắng gắt, gió mạnh, lượng mưa ít hơn hẳn nhiều nơi khác. Phan Thiết lại nằm ở cửa sông, sát biển; khi triều lên, nước mặn theo dòng Cà Ty ngược vào thị xã. Nước sông vùng cửa biển vì thế thường lợ, khó dùng để ăn uống. Với các gia đình ở đây, một chiếc giếng nước ngọt trong vườn là tài sản quý. Năm 1910, Phan Thiết chưa có tháp nước và hệ thống cấp nước như sau này. Tháp nước, nay là biểu tượng của thành phố, được dựng vào khoảng những năm 1928 – 1934, tức khoảng hai mươi năm sau khi thầy Thành rời Dục Thanh. Trước đó, mọi việc từ nấu ăn, tắm giặt đến tưới cây đều trông vào giếng và nước mưa. Chiếc giếng trong vườn nhà cụ Nguyễn Thông vì thế không chỉ phục vụ một gia đình. Khi trường mở và có nội trú, nó trở thành nguồn nước hằng ngày của cả một cộng đồng thầy trò. Mỗi gàu nước kéo lên từ lòng giếng là một phần của nếp sinh hoạt chung ấy."},{"t":"Nhà Ngư: từ kho ngư cụ thành chỗ ở nội trú. Chỗ ở của thầy trò Dục Thanh là nhà Ngư, dựng năm 1906. Chữ “ngư” nghĩa là cá. Đúng như tên gọi, ban đầu gia đình cụ Nguyễn Thông dùng ngôi nhà để chứa ngư cụ và làm nước mắm. Khi trường mở, nhà Ngư được sửa sang thành chỗ ở nội trú cho thầy giáo và những học trò ở xa đến học. Một ngôi nhà từng chứa lưới, chứa thùng nay thành chỗ ngả lưng của thầy trò. Cách dùng lại ấy nói lên nếp tiết kiệm của những nhà nho đi buôn để nuôi trường. Trong những tháng dạy học ở Phan Thiết, thầy Thành sống ngay trong khuôn viên trường. Thầy là người trẻ nhất trong số các thầy giáo. Sống nội trú, thầy không chỉ gặp học trò trong giờ học, mà cả lúc sáng sớm ra sân tập, lúc chiều muộn sau giờ tan lớp. Có lẽ vì thế mà học trò cũ, mấy chục năm sau, vẫn nhớ thầy như một người vừa nghiêm vừa gần gũi, như một người bạn lớn. Nhà Ngư hôm nay là công trình được phục dựng trong những năm 1978 – 1980, theo lời kể của những học trò cũ (xem chuyên đề Trường Dục Thanh – di tích giữ nguyên nếp nhà gỗ)."},{"t":"Giếng nước trong tâm thức người Việt. Với người Việt, giếng nước không chỉ là chỗ lấy nước. Hình ảnh cây đa, giếng nước, sân đình từ lâu là biểu tượng của làng quê. Giếng làng là nơi người ta gặp nhau mỗi sớm mỗi chiều, nơi chuyện làng chuyện xóm được kể cho nhau nghe. Trong nhiều gia đình, chiếc giếng được đào, được xây từ đời ông bà, rồi con cháu dùng tiếp qua nhiều thế hệ. Nước giếng vì thế gắn với ý niệm về nguồn cội. Chiếc giếng ở Dục Thanh cũng mang dáng dấp ấy. Nó được gia đình nhà thơ Nguyễn Thông xây để dùng, rồi phục vụ ngôi trường do các con ông lập ra, rồi cho người thầy giáo trẻ từ xứ Nghệ nước dùng hằng ngày. Bên cạnh là cây khế do phu nhân cụ Nguyễn Thông trồng. Người xưa dạy “uống nước nhớ nguồn”, “ăn quả nhớ kẻ trồng cây”. Hiếm có nơi nào hai câu tục ngữ ấy hiện ra cụ thể như ở góc vườn này: một chiếc giếng và một cây khế, cả hai đều do người đi trước để lại cho người đến sau."},{"t":"Bạn có biết? Ở làng Sen, quê nội của Bác thuộc xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, giếng Cốc được gìn giữ như một chứng tích gắn với những kỷ niệm thời niên thiếu của Người."},{"t":"Từ giếng làng Sen đến bờ suối Pác Bó. Nước gắn với nhiều chặng trong đời Người. Thuở nhỏ, cậu bé Nguyễn Sinh Cung lớn lên ở làng Sen, bên những giếng làng, ao sen của một làng quê xứ Nghệ. Năm 1910, ở Phan Thiết, người thầy giáo trẻ dùng nước từ chiếc giếng gạch trong vườn trường. Ba mươi năm sau, ngày 28/1/1941, Người về nước qua cột mốc 108 và sống ở Pác Bó, Cao Bằng. Ở đó, Người ở trong hang Cốc Bó, làm việc bên bờ suối, ăn cháo bẹ, rau măng, vẫn giữ nếp sinh hoạt đều đặn, giản dị. Chính những ngày gian khổ ấy đã đi vào bài thơ Tức cảnh Pác Bó, sáng tác năm 1941. Bài thơ không than thở. Nó ghi lại cuộc sống hằng ngày bằng một giọng vui, thậm chí hóm hỉnh: sáng ra bờ suối, tối vào hang, ngồi bàn đá chông chênh mà dịch sử Đảng. Từ chiếc giếng ở Dục Thanh đến dòng suối ở Pác Bó, có thể thấy một điều không đổi. Dù ở đâu, người thanh niên năm nào vẫn sống giản dị giữa những gì thiên nhiên và người lao động quanh mình có."},{"t":"Sáng ra bờ suối, tối vào hang, Cháo bẹ rau măng vẫn sẵn sàng. Bàn đá chông chênh dịch sử Đảng, Cuộc đời cách mạng thật là sang. — Hồ Chí Minh"},{"t":"Bạn có biết? Về sống ở Pác Bó năm 1941, Bác đặt tên cho dòng suối trước hang Cốc Bó là suối Lê-nin, và ngọn núi bên cạnh là núi Các Mác."},{"t":"Một nếp sống giản dị. Lối sống nội trú ở Dục Thanh, cùng ở với học trò, tự lo lấy việc hằng ngày bên chiếc giếng giữa sân, là một trong những dấu vết sớm của nếp sống giản dị ở Hồ Chí Minh. Trên cương vị Chủ tịch nước, Người vẫn giữ nếp ấy. Cuối năm 1954, khi về làm việc ở khu Phủ Chủ tịch, Người không ở trong tòa nhà lớn của Phủ Toàn quyền cũ, mà chọn một ngôi nhà nhỏ vốn dành cho người thợ điện trong khuôn viên. Từ tháng 5/1958, Người sống và làm việc trong ngôi nhà sàn gỗ đơn sơ bên ao cá, quanh nhà là vườn cây và hàng râm bụt. Không thể nói nếp sống ấy bắt đầu từ Phan Thiết. Nó có gốc từ gia đình nhà nho thanh bạch ở xứ Nghệ, và được rèn qua ba mươi năm lao động, bôn ba ở nước ngoài. Nhưng chiếc giếng gạch ở Dục Thanh là một chứng tích cụ thể, hiếm hoi còn lại, cho thấy người thanh niên hai mươi tuổi đã sống thế nào. Thầy tự múc nước, tự lo việc thường ngày, ở chung với học trò dưới một mái nhà đơn sơ vốn là kho chứa ngư cụ."},{"t":"Chiếc giếng trong không gian 3D. Trong gian trưng bày 3D, chiếc giếng được đặt ở một góc sân, cách bảng chuyên đề này chỉ vài bước chân, tách khỏi dãy bàn ghế của lớp học. Người xem có thể bấm vào giếng để đọc câu chuyện về nguồn nước sinh hoạt của thầy trò Dục Thanh. Mô hình giếng là vật minh họa. Chiếc giếng thật vẫn nằm trong khu vườn phía sau Ngọa Du Sào, ở khu di tích Trường Dục Thanh, Phan Thiết. Để hình dung trọn một ngày của thầy Thành, người xem có thể đi theo một vòng nhỏ trong gian trưng bày. Bắt đầu từ lớp học với hai tấm bảng đen và hai mươi mốt bộ bàn ghế, nơi thầy đứng lớp nhì. Sang góc Ngọa Du Sào với chiếc phản và bàn đọc sách, nơi thầy lui tới đọc sách, soạn bài. Rồi dừng lại bên chiếc giếng, nơi thầy trở về với những việc thường ngày. Ba điểm dừng ấy ghép lại thành chân dung đầy đủ hơn của người thầy giáo trẻ: dạy học, tự học và sống giản dị."},{"t":"Dấu tích hôm nay: về nguồn. Ngày nay, chiếc giếng gạch vẫn nằm yên trong khu di tích Trường Dục Thanh, cạnh cây khế cổ thụ, do Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận gìn giữ. Du khách được ngắm giếng, chụp ảnh bên thành giếng, nghe thuyết minh viên kể về những tháng ngày thầy Thành sống nội trú ở đây. Không phải ngẫu nhiên mà nhiều trường học, đoàn thanh niên chọn Dục Thanh làm điểm đến về nguồn, nhất là dịp tháng Năm, tháng sinh của Bác. Chiếc giếng nhỏ nhắc các thế hệ sau về một nguồn cội đặc biệt. Ở đây, người thanh niên Nguyễn Tất Thành, trước khi mang tên Nguyễn Ái Quốc rồi Hồ Chí Minh, đã sống những ngày bình dị của một thầy giáo ở ngôi trường nhỏ ven biển. Trong những ngày ấy không có sự kiện lớn nào. Chỉ có những sớm dậy tập thể dục, những giờ đứng lớp, những buổi đọc sách và những gàu nước kéo lên từ lòng giếng. Nhưng chính từ những ngày bình dị ấy, người xem hôm nay hiểu hơn tuổi trẻ của Người, và hiểu vì sao người thanh niên ấy đủ sức cho một hành trình dài ba mươi năm."}],"so_chu":1791}],"do_vat":[{"id":"schoolDesk@-3.2,-2.2","x":-3.2,"y":0.71,"z":-2.25,"loai":"schoolDesk","ten":"Bàn ghế học trò","tieu_de":"Hai mươi mốt bộ bàn ghế của lớp học xưa","text":"Trong gian nhà gỗ lợp ngói, năm gian rộng khoảng một trăm ba mươi bảy mét vuông, cao bốn mét bốn, hai mươi mốt bộ bàn ghế gỗ mộc xếp thành từng dãy ngay ngắn, quay mặt về phía bục giảng và tấm bảng đen treo trên vách. Bàn liền ghế, mặt bàn bào nhẵn, không sơn son thếp vàng, đúng kiểu bàn ghế trường làng đầu thế kỷ hai mươi. Không gian ba chiều phục dựng ở đây giữ nguyên con số ấy — hai mươi mốt bộ — như lớp học chính của Trường Dục Thanh, Phan Thiết, vẫn còn giữ đến hôm nay.\n\nNgôi trường sinh ra từ một hội buôn nước mắm. Tháng 3/1906, sáu nhà yêu nước theo tinh thần Duy Tân ở Phan Thiết — Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng — lập ra hội buôn Liên Thành, làm nước mắm rồi dùng lợi nhuận nuôi việc học. Năm 1907, hai anh em Nguyễn Trọng Lội và Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông, đứng ra vận động dựng Trường Dục Thanh ngay trên đất nhà mình, bên bờ sông Cà Ty. Tên trường mang ý nghĩa giáo dục lớp thanh thiếu niên; buôn bán để nuôi trường, mở trường để thức tỉnh lòng yêu nước — đó là cách các nhà Duy Tân ở đây hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”.\n\nTrường khi ấy chỉ có chừng năm, sáu mươi học trò, chia làm bốn lớp Tư, Ba, Nhì, Nhất, chương trình lấy chữ Quốc ngữ làm chính, học thêm chữ Hán, chữ Pháp và thể dục — mới mẻ hẳn so với lối học khoa cử còn thịnh hành lúc bấy giờ. Tháng 9/1910, một thanh niên vừa tròn hai mươi tuổi tên Nguyễn Tất Thành, sau khi từ Bình Định qua Phan Rang tới Phan Thiết nhờ cụ Trương Gia Mô giới thiệu, được các nhà Duy Tân của hội Liên Thành nhận vào dạy lớp nhì. Những học trò lớp nhì hẳn đã ngồi trên chính những bộ bàn ghế kiểu này, nghe thầy giảng chữ Quốc ngữ, chữ Hán, có khi cả tiếng Pháp khi trường cần người dạy thay.\n\nNgay sát lớp học là Nhà Ngư, dựng năm 1906 vốn để chứa ngư cụ của vùng biển Phan Thiết, sau được cải làm nơi ở nội trú cho thầy và một số trò. Nhiều học trò ở xa nhà vì thế không chỉ đến lớp rồi về, mà ăn ở ngay trong khuôn viên trường, sáng tối đều quanh quẩn bên dãy bàn ghế này trước khi ra sông Cà Ty gánh nước, phụ giúp việc bếp núc. Một ngôi trường nhỏ nuôi bằng nghề nước mắm, vì vậy, còn mang dáng dấp một mái nhà chung cho thầy trò xa xứ.\n\nGần nửa năm đứng lớp, đến tháng 2/1911 thầy Thành rời Dục Thanh vào Sài Gòn, để rồi bốn tháng sau xuống tàu sang Pháp, mở đầu ba mươi năm tìm đường cứu nước. Từ tháng 11/1978 đến tháng 12/1980, lớp học cùng các công trình trong khuôn viên được trùng tu theo đúng dáng xưa; năm 1986 khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia, và ngày 19/5/1986, nhân kỷ niệm chín mươi sáu năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận khánh thành ngay bên cạnh, tại số 39 Trưng Nhị, thành phố Phan Thiết. Lớp học hôm nay vẫn kê đúng hai mươi mốt bộ bàn ghế ấy; nhiều đoàn học sinh, sinh viên chọn nơi này làm điểm về nguồn, ngồi vào những dãy bàn cũ để hình dung một buổi học tám mươi năm trước.","nguon":"Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết; Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành; Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành","doc":[{"t":"Hai mươi mốt bộ bàn ghế của lớp học xưa. Trong gian nhà gỗ lợp ngói, năm gian rộng khoảng một trăm ba mươi bảy mét vuông, cao bốn mét bốn, hai mươi mốt bộ bàn ghế gỗ mộc xếp thành từng dãy ngay ngắn, quay mặt về phía bục giảng và tấm bảng đen treo trên vách. Bàn liền ghế, mặt bàn bào nhẵn, không sơn son thếp vàng, đúng kiểu bàn ghế trường làng đầu thế kỷ hai mươi. Không gian ba chiều phục dựng ở đây giữ nguyên con số ấy — hai mươi mốt bộ — như lớp học chính của Trường Dục Thanh, Phan Thiết, vẫn còn giữ đến hôm nay."},{"t":"Ngôi trường sinh ra từ một hội buôn nước mắm. Tháng 3/1906, sáu nhà yêu nước theo tinh thần Duy Tân ở Phan Thiết — Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng — lập ra hội buôn Liên Thành, làm nước mắm rồi dùng lợi nhuận nuôi việc học. Năm 1907, hai anh em Nguyễn Trọng Lội và Nguyễn Quý Anh, con trai nhà thơ yêu nước Nguyễn Thông, đứng ra vận động dựng Trường Dục Thanh ngay trên đất nhà mình, bên bờ sông Cà Ty. Tên trường mang ý nghĩa giáo dục lớp thanh thiếu niên; buôn bán để nuôi trường, mở trường để thức tỉnh lòng yêu nước — đó là cách các nhà Duy Tân ở đây hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”."},{"t":"Trường khi ấy chỉ có chừng năm, sáu mươi học trò, chia làm bốn lớp Tư, Ba, Nhì, Nhất, chương trình lấy chữ Quốc ngữ làm chính, học thêm chữ Hán, chữ Pháp và thể dục — mới mẻ hẳn so với lối học khoa cử còn thịnh hành lúc bấy giờ. Tháng 9/1910, một thanh niên vừa tròn hai mươi tuổi tên Nguyễn Tất Thành, sau khi từ Bình Định qua Phan Rang tới Phan Thiết nhờ cụ Trương Gia Mô giới thiệu, được các nhà Duy Tân của hội Liên Thành nhận vào dạy lớp nhì. Những học trò lớp nhì hẳn đã ngồi trên chính những bộ bàn ghế kiểu này, nghe thầy giảng chữ Quốc ngữ, chữ Hán, có khi cả tiếng Pháp khi trường cần người dạy thay."},{"t":"Ngay sát lớp học là Nhà Ngư, dựng năm 1906 vốn để chứa ngư cụ của vùng biển Phan Thiết, sau được cải làm nơi ở nội trú cho thầy và một số trò. Nhiều học trò ở xa nhà vì thế không chỉ đến lớp rồi về, mà ăn ở ngay trong khuôn viên trường, sáng tối đều quanh quẩn bên dãy bàn ghế này trước khi ra sông Cà Ty gánh nước, phụ giúp việc bếp núc. Một ngôi trường nhỏ nuôi bằng nghề nước mắm, vì vậy, còn mang dáng dấp một mái nhà chung cho thầy trò xa xứ."},{"t":"Gần nửa năm đứng lớp, đến tháng 2/1911 thầy Thành rời Dục Thanh vào Sài Gòn, để rồi bốn tháng sau xuống tàu sang Pháp, mở đầu ba mươi năm tìm đường cứu nước. Từ tháng 11/1978 đến tháng 12/1980, lớp học cùng các công trình trong khuôn viên được trùng tu theo đúng dáng xưa; năm 1986 khu di tích được xếp hạng di tích lịch sử – văn hóa cấp quốc gia, và ngày 19/5/1986, nhân kỷ niệm chín mươi sáu năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận khánh thành ngay bên cạnh, tại số 39 Trưng Nhị, thành phố Phan Thiết. Lớp học hôm nay vẫn kê đúng hai mươi mốt bộ bàn ghế ấy; nhiều đoàn học sinh, sinh viên chọn nơi này làm điểm về nguồn, ngồi vào những dãy bàn cũ để hình dung một buổi học tám mươi năm trước."},{"t":"Bạn có biết? Trường Dục Thanh khi ấy chỉ có khoảng 60 học trò, chia bốn lớp Tư, Ba, Nhì, Nhất; thầy Nguyễn Tất Thành phụ trách lớp nhì (Báo Cần Thơ)."}],"ban_co_biet":"Trường Dục Thanh khi ấy chỉ có khoảng 60 học trò, chia bốn lớp Tư, Ba, Nhì, Nhất; thầy Nguyễn Tất Thành phụ trách lớp nhì (Báo Cần Thơ)."},{"id":"schoolDesk@-3.2,-4.0","x":-3.2,"y":0.71,"z":-4,"loai":"schoolDesk","ten":"Chỗ ngồi của học trò lớp nhì","tieu_de":"Thầy hỏi lại: “Các trò đã hiểu chưa?”","text":"Ngồi ở bộ bàn ghế này, một học trò lớp nhì Trường Dục Thanh năm 1910 sẽ nhìn thấy phía trên bục giảng một thầy giáo còn rất trẻ — Nguyễn Tất Thành, khi ấy vừa tròn hai mươi tuổi, chỉ hơn học trò lớn nhất trong lớp vài tuổi. Thầy được phân dạy lớp nhì, môn chính là chữ Quốc ngữ và chữ Hán, kiêm luôn môn thể dục; khi trường thiếu người, thầy còn đứng ra dạy thay cả tiếng Pháp.\n\nHọc trò cũ của trường về sau vẫn nhớ rõ cách thầy đứng lớp: giảng bài nhiệt tình, dễ hiểu, không nói suông một chiều. Giảng xong một ý, thầy dừng lại, hỏi lại xem cả lớp đã hiểu chưa rồi mới chuyển sang ý kế tiếp — một cách dạy khá lạ với lối học thuộc lòng, đọc theo của trường làng thời ấy. Ai tiến bộ, thầy khen ngợi trước lớp; ai mắc lỗi, thầy ân cần chỉ bảo chứ không quở trách nặng lời. Với học trò ngồi ở dãy bàn này, người thầy hai mươi tuổi vừa nghiêm khắc trong giờ học vừa gần gũi như một người anh, người bạn lớn.\n\nVốn liếng chữ nghĩa giúp thầy đứng vững trên bục giảng ấy đến từ một hành trình học tập trước đó: chữ Hán được cha, cụ Phó bảng Nguyễn Sinh Sắc, cùng thầy đồ Vương Thúc Quý dạy dỗ từ nhỏ ở quê nhà Nghệ An; chữ Quốc ngữ và những bài tiếng Pháp đầu tiên học ở các trường Pháp – Việt tại Huế, rồi được bồi thêm khi cha gửi xuống Quy Nhơn học tiếp tiếng Pháp trong thời gian cụ Sắc làm tri huyện Bình Khê. Từng ấy năm học chữ của người thầy trẻ hóa thành từng bài giảng cho lớp nhì bên dòng Cà Ty.\n\nKhông ít bạn học ngồi cùng dãy bàn này là học trò ở xa, ăn ở ngay trong khuôn viên trường tại Nhà Ngư — ngôi nhà dựng năm 1906 để chứa ngư cụ, sau được cải làm chỗ nội trú cho thầy và trò. Ngày đến lớp nghe giảng, tối về chung một mái nhà, thầy trò Dục Thanh vì thế gần gũi nhau hơn cả một quan hệ thầy trò thông thường; chính sự gần gũi ấy có lẽ là lý do vì sao mấy mươi năm sau, những học trò cũ vẫn nhớ rành rọt từng cử chỉ, từng câu hỏi của người thầy hai mươi tuổi năm nào.\n\nNgồi ở lớp nhì — bậc học thứ ba trong bốn bậc Tư, Ba, Nhì, Nhất của trường, chỉ đứng sau lớp Nhất — học trò tại dãy bàn này còn được học một môn hiếm trường làng nào có: thể dục. Lối học khoa cử cũ trọng việc ngồi yên đọc sách, viết chữ, ít khi để tâm tới việc rèn luyện thân thể; các nhà Duy Tân đứng sau Dục Thanh lại muốn đào tạo những người trẻ khỏe mạnh cả thân thể lẫn trí tuệ, nên đưa hẳn thể dục vào chương trình, do chính thầy Thành phụ trách.\n\nDấu tích hôm nay: gian lớp học năm gian của Trường Dục Thanh được trùng tu năm 1978–1980 theo đúng dáng xưa và xếp hạng di tích quốc gia năm 1986. Bộ bàn ghế phục dựng trong không gian này vẫn đặt đúng vị trí một chỗ ngồi học trò, để khách đến thăm có thể ngồi xuống, hình dung lại khoảnh khắc một thầy giáo trẻ dừng lời, hỏi cả lớp: “Các trò đã hiểu chưa?”","nguon":"Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành","doc":[{"t":"Thầy hỏi lại: “Các trò đã hiểu chưa?”. Ngồi ở bộ bàn ghế này, một học trò lớp nhì Trường Dục Thanh năm 1910 sẽ nhìn thấy phía trên bục giảng một thầy giáo còn rất trẻ — Nguyễn Tất Thành, khi ấy vừa tròn hai mươi tuổi, chỉ hơn học trò lớn nhất trong lớp vài tuổi. Thầy được phân dạy lớp nhì, môn chính là chữ Quốc ngữ và chữ Hán, kiêm luôn môn thể dục; khi trường thiếu người, thầy còn đứng ra dạy thay cả tiếng Pháp."},{"t":"Học trò cũ của trường về sau vẫn nhớ rõ cách thầy đứng lớp: giảng bài nhiệt tình, dễ hiểu, không nói suông một chiều. Giảng xong một ý, thầy dừng lại, hỏi lại xem cả lớp đã hiểu chưa rồi mới chuyển sang ý kế tiếp — một cách dạy khá lạ với lối học thuộc lòng, đọc theo của trường làng thời ấy. Ai tiến bộ, thầy khen ngợi trước lớp; ai mắc lỗi, thầy ân cần chỉ bảo chứ không quở trách nặng lời. Với học trò ngồi ở dãy bàn này, người thầy hai mươi tuổi vừa nghiêm khắc trong giờ học vừa gần gũi như một người anh, người bạn lớn."},{"t":"Vốn liếng chữ nghĩa giúp thầy đứng vững trên bục giảng ấy đến từ một hành trình học tập trước đó: chữ Hán được cha, cụ Phó bảng Nguyễn Sinh Sắc, cùng thầy đồ Vương Thúc Quý dạy dỗ từ nhỏ ở quê nhà Nghệ An; chữ Quốc ngữ và những bài tiếng Pháp đầu tiên học ở các trường Pháp – Việt tại Huế, rồi được bồi thêm khi cha gửi xuống Quy Nhơn học tiếp tiếng Pháp trong thời gian cụ Sắc làm tri huyện Bình Khê. Từng ấy năm học chữ của người thầy trẻ hóa thành từng bài giảng cho lớp nhì bên dòng Cà Ty."},{"t":"Không ít bạn học ngồi cùng dãy bàn này là học trò ở xa, ăn ở ngay trong khuôn viên trường tại Nhà Ngư — ngôi nhà dựng năm 1906 để chứa ngư cụ, sau được cải làm chỗ nội trú cho thầy và trò. Ngày đến lớp nghe giảng, tối về chung một mái nhà, thầy trò Dục Thanh vì thế gần gũi nhau hơn cả một quan hệ thầy trò thông thường; chính sự gần gũi ấy có lẽ là lý do vì sao mấy mươi năm sau, những học trò cũ vẫn nhớ rành rọt từng cử chỉ, từng câu hỏi của người thầy hai mươi tuổi năm nào."},{"t":"Ngồi ở lớp nhì — bậc học thứ ba trong bốn bậc Tư, Ba, Nhì, Nhất của trường, chỉ đứng sau lớp Nhất — học trò tại dãy bàn này còn được học một môn hiếm trường làng nào có: thể dục. Lối học khoa cử cũ trọng việc ngồi yên đọc sách, viết chữ, ít khi để tâm tới việc rèn luyện thân thể; các nhà Duy Tân đứng sau Dục Thanh lại muốn đào tạo những người trẻ khỏe mạnh cả thân thể lẫn trí tuệ, nên đưa hẳn thể dục vào chương trình, do chính thầy Thành phụ trách."},{"t":"Dấu tích hôm nay: gian lớp học năm gian của Trường Dục Thanh được trùng tu năm 1978–1980 theo đúng dáng xưa và xếp hạng di tích quốc gia năm 1986. Bộ bàn ghế phục dựng trong không gian này vẫn đặt đúng vị trí một chỗ ngồi học trò, để khách đến thăm có thể ngồi xuống, hình dung lại khoảnh khắc một thầy giáo trẻ dừng lời, hỏi cả lớp: “Các trò đã hiểu chưa?”"},{"t":"Bạn có biết? Khi đứng lớp ở Dục Thanh, thầy Nguyễn Tất Thành mới vừa tròn hai mươi tuổi — chỉ lớn hơn những học trò nhiều tuổi nhất trong lớp vài năm (Bảo tàng Hồ Chí Minh)."}],"ban_co_biet":"Khi đứng lớp ở Dục Thanh, thầy Nguyễn Tất Thành mới vừa tròn hai mươi tuổi — chỉ lớn hơn những học trò nhiều tuổi nhất trong lớp vài năm (Bảo tàng Hồ Chí Minh)."},{"id":"schoolDesk@5.5,-0.5","x":5.5,"y":0.71,"z":-0.5,"loai":"schoolDesk","ten":"Bàn học cuối lớp","tieu_de":"Những buổi học ngoài lớp","text":"Bộ bàn học cuối lớp này thường vắng người vào những buổi chiều thầy Thành cho học trò rời khuôn viên trường, đi bộ dọc dòng Cà Ty ra phía biển. Ở Trường Dục Thanh năm 1910, việc học không chỉ đóng khung trong bốn bức vách có bảng đen và bàn ghế; thầy giáo trẻ còn đưa học trò ra ngoài, đến với chính đời sống của quê hương mình.\n\nThầy dẫn học trò đi thăm cảnh vật Phan Thiết, tìm hiểu công việc của người lao động quanh vùng, ghé cả những xóm chài nghèo ven biển nơi ngư dân quanh năm bám vào con nước để sống. Trên đường đi, thầy kể cho học trò nghe chuyện Hai Bà Trưng cưỡi voi ra trận, chuyện Bà Triệu cưỡi voi đánh giặc phương Bắc, đọc cho các em nghe những vần thơ yêu nước. Một buổi học ngoài trời như thế gói trong đó cả bài học chữ lẫn bài học về lòng yêu nước, về tình thương với người nghèo khổ — điều sách vở trong lớp khó truyền tải trọn vẹn.\n\nCách dạy ấy khớp với con người thầy giáo hai mươi tuổi mà học trò Dục Thanh còn nhớ: giảng bài nhiệt tình, hỏi lại xem trò đã hiểu chưa, khen khi trò tiến bộ, ân cần khi trò sai sót — nghiêm khắc trong giờ học nhưng gần gũi như một người anh lớn ngoài giờ lên lớp. Cũng chính từ những buổi đi thực tế ấy, hình ảnh người dân lao động nghèo khó của một thị xã ven biển miền Trung đã in dấu vào những năm tháng đầu đời hoạt động của người thanh niên sau này trở thành Chủ tịch Hồ Chí Minh.\n\nNhững buổi ra khỏi lớp như vậy cũng nối liền với chính điều mà những người sáng lập Trường Dục Thanh theo đuổi. Hội buôn Liên Thành nuôi trường bằng nghề làm nước mắm — đặc sản gắn liền với đời sống ngư dân Phan Thiết — và các nhà Duy Tân đứng sau ngôi trường vẫn tin rằng “khai dân trí” phải đi cùng “hậu dân sinh”, nghĩa là mở mang hiểu biết cho dân không thể tách rời việc chăm lo đời sống của chính những người dân ấy. Đưa học trò về với xóm chài nghèo, vì thế, không chỉ là một buổi dã ngoại, mà là một cách dạy cho các em nhìn thấy tận mắt điều mà cả ngôi trường đang muốn hướng tới.\n\nTrên dòng Cà Ty những ngày ấy, thuyền nan, thuyền thúng của ngư dân qua lại tấp nập, chở về những mẻ cá để làm nên thứ nước mắm đã nuôi sống cả hội buôn Liên Thành lẫn ngôi trường nhỏ. Đi cùng học trò dọc bờ sông, thầy Thành hẳn cũng nhìn thấy chính guồng quay ấy: người dân lao động cực nhọc trên biển, trên sông, để rồi một phần lợi nhuận từ công sức của họ quay về nuôi những đứa trẻ ngồi học chữ trong ngôi trường ven sông.\n\nTháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Dục Thanh vào Sài Gòn. Đúng bốn tháng sau, ngày 5/6/1911, từ bến Nhà Rồng, người thanh niên ấy xuống tàu Amiral Latouche-Tréville sang Pháp với tên gọi Văn Ba, bắt đầu hành trình ba mươi năm tìm đường cứu nước. Dòng Cà Ty hôm nay vẫn chảy qua lòng thành phố Phan Thiết như một chứng nhân lặng lẽ; ngay bên bờ sông ấy là Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, nơi những tấm ảnh tư liệu về dòng sông, về ngôi trường vẫn được lưu giữ để kể lại cho khách tham quan về những buổi học ngoài lớp năm xưa.","nguon":"Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; Báo Chính phủ – Ngày Bác đến Trường Dục Thanh; Thanh Niên – Thầy Thành ở trường Dục Thanh","doc":[{"t":"Những buổi học ngoài lớp. Bộ bàn học cuối lớp này thường vắng người vào những buổi chiều thầy Thành cho học trò rời khuôn viên trường, đi bộ dọc dòng Cà Ty ra phía biển. Ở Trường Dục Thanh năm 1910, việc học không chỉ đóng khung trong bốn bức vách có bảng đen và bàn ghế; thầy giáo trẻ còn đưa học trò ra ngoài, đến với chính đời sống của quê hương mình."},{"t":"Thầy dẫn học trò đi thăm cảnh vật Phan Thiết, tìm hiểu công việc của người lao động quanh vùng, ghé cả những xóm chài nghèo ven biển nơi ngư dân quanh năm bám vào con nước để sống. Trên đường đi, thầy kể cho học trò nghe chuyện Hai Bà Trưng cưỡi voi ra trận, chuyện Bà Triệu cưỡi voi đánh giặc phương Bắc, đọc cho các em nghe những vần thơ yêu nước. Một buổi học ngoài trời như thế gói trong đó cả bài học chữ lẫn bài học về lòng yêu nước, về tình thương với người nghèo khổ — điều sách vở trong lớp khó truyền tải trọn vẹn."},{"t":"Cách dạy ấy khớp với con người thầy giáo hai mươi tuổi mà học trò Dục Thanh còn nhớ: giảng bài nhiệt tình, hỏi lại xem trò đã hiểu chưa, khen khi trò tiến bộ, ân cần khi trò sai sót — nghiêm khắc trong giờ học nhưng gần gũi như một người anh lớn ngoài giờ lên lớp. Cũng chính từ những buổi đi thực tế ấy, hình ảnh người dân lao động nghèo khó của một thị xã ven biển miền Trung đã in dấu vào những năm tháng đầu đời hoạt động của người thanh niên sau này trở thành Chủ tịch Hồ Chí Minh."},{"t":"Những buổi ra khỏi lớp như vậy cũng nối liền với chính điều mà những người sáng lập Trường Dục Thanh theo đuổi. Hội buôn Liên Thành nuôi trường bằng nghề làm nước mắm — đặc sản gắn liền với đời sống ngư dân Phan Thiết — và các nhà Duy Tân đứng sau ngôi trường vẫn tin rằng “khai dân trí” phải đi cùng “hậu dân sinh”, nghĩa là mở mang hiểu biết cho dân không thể tách rời việc chăm lo đời sống của chính những người dân ấy. Đưa học trò về với xóm chài nghèo, vì thế, không chỉ là một buổi dã ngoại, mà là một cách dạy cho các em nhìn thấy tận mắt điều mà cả ngôi trường đang muốn hướng tới."},{"t":"Trên dòng Cà Ty những ngày ấy, thuyền nan, thuyền thúng của ngư dân qua lại tấp nập, chở về những mẻ cá để làm nên thứ nước mắm đã nuôi sống cả hội buôn Liên Thành lẫn ngôi trường nhỏ. Đi cùng học trò dọc bờ sông, thầy Thành hẳn cũng nhìn thấy chính guồng quay ấy: người dân lao động cực nhọc trên biển, trên sông, để rồi một phần lợi nhuận từ công sức của họ quay về nuôi những đứa trẻ ngồi học chữ trong ngôi trường ven sông."},{"t":"Tháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Dục Thanh vào Sài Gòn. Đúng bốn tháng sau, ngày 5/6/1911, từ bến Nhà Rồng, người thanh niên ấy xuống tàu Amiral Latouche-Tréville sang Pháp với tên gọi Văn Ba, bắt đầu hành trình ba mươi năm tìm đường cứu nước. Dòng Cà Ty hôm nay vẫn chảy qua lòng thành phố Phan Thiết như một chứng nhân lặng lẽ; ngay bên bờ sông ấy là Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, nơi những tấm ảnh tư liệu về dòng sông, về ngôi trường vẫn được lưu giữ để kể lại cho khách tham quan về những buổi học ngoài lớp năm xưa."},{"t":"Bạn có biết? Trên những buổi đi thực tế cùng học trò, thầy Thành thường kể chuyện Hai Bà Trưng, Bà Triệu và đọc thơ yêu nước cho các em nghe (Bảo tàng Hồ Chí Minh)."}],"ban_co_biet":"Trên những buổi đi thực tế cùng học trò, thầy Thành thường kể chuyện Hai Bà Trưng, Bà Triệu và đọc thơ yêu nước cho các em nghe (Bảo tàng Hồ Chí Minh)."},{"id":"table@-5.1,-2.3","x":-5.1,"y":0.96,"z":-2.3,"loai":"table","ten":"Bàn thầy giáo","tieu_de":"Người thầy hai mươi tuổi","text":"Đặt trên bục giảng, quay mặt xuống hai mươi mốt bộ bàn ghế học trò, chiếc bàn thầy giáo là nơi Nguyễn Tất Thành soạn bài, chấm bài và đứng giảng suốt gần nửa năm ở Trường Dục Thanh. Tháng 9/1910, khi ngồi xuống sau chiếc bàn này lần đầu, người thầy giáo ấy vừa tròn hai mươi tuổi.\n\nCon đường đưa anh tới đây khá dài. Giữa năm 1909, Nguyễn Tất Thành theo cha là cụ Phó bảng Nguyễn Sinh Sắc rời Huế vào Bình Định, khi cụ được cử làm tri huyện Bình Khê; từ tháng 9 năm ấy, người con trai mười chín tuổi được cha gửi xuống Quy Nhơn học thêm tiếng Pháp. Khoảng tháng 8/1910, anh rời Bình Định, một mình tiếp tục đi về phương Nam, qua Phan Rang rồi tới Phan Thiết. Nhờ cụ Trương Gia Mô, một nhà nho yêu nước quen biết cụ Nguyễn Sinh Sắc, đứng ra giới thiệu, anh được các nhà Duy Tân của hội Liên Thành đón nhận và mời dạy học tại Trường Dục Thanh.\n\nVốn liếng để đứng lớp, thầy Thành có được từ nhiều năm trước đó: chữ Hán học từ cha và thầy đồ Vương Thúc Quý ở quê nhà Nam Đàn, Nghệ An; chữ Quốc ngữ và tiếng Pháp học ở các trường Pháp – Việt tại Huế rồi học thêm ở Quy Nhơn. Nhờ vậy, ngoài môn chính là chữ Quốc ngữ, chữ Hán và thể dục dành cho lớp nhì, khi trường thiếu người, thầy còn có thể đứng lớp dạy thay tiếng Pháp — điều không phải giáo viên trẻ nào ở một trường làng nhỏ cũng làm được.\n\nNgoài giờ đứng sau chiếc bàn này, thầy Thành sống ngay trong khuôn viên trường, tại Nhà Ngư — ngôi nhà dựng năm 1906 để chứa ngư cụ, được cải làm nơi ở nội trú cho thầy và một số học trò xa nhà. Một thầy giáo hai mươi tuổi, chưa vợ con, ăn ở cùng học trò dưới một mái nhà, hẳn đã có một quãng thời gian sống giản dị, gắn bó với ngôi trường nhiều hơn là quan hệ giữa một người dạy và những người học thông thường. Gần nửa năm đứng lớp bên dòng Cà Ty, như chính lời kể về ngôi trường vẫn nhắc, là chặng dừng chân dài cuối cùng của người thanh niên ấy trên đất nước trước khi vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước.\n\nSau chiếc bàn ấy, thầy Thành cũng là người đưa ra một lối dạy mới: giảng xong một ý, dừng lại hỏi học trò đã hiểu chưa rồi mới đi tiếp, khen ngợi khi trò tiến bộ, ân cần khi trò mắc lỗi. Tháng 2/1911, thầy đứng dậy rời chiếc bàn này lần cuối, rời Dục Thanh vào Sài Gòn; bốn tháng sau xuống tàu sang Pháp, khép lại chặng dừng chân dài cuối cùng trên đất nước trước khi bắt đầu ba mươi năm bôn ba tìm đường cứu nước. Khu di tích Trường Dục Thanh, được trùng tu năm 1978–1980 và xếp hạng di tích quốc gia năm 1986, đến nay vẫn giữ nguyên vị trí chiếc bàn giáo viên ấy trên bục giảng, như một lời nhắc về người thầy giáo hai mươi tuổi từng đứng đó.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; Tuổi Trẻ – Thầy giáo Nguyễn Tất Thành","doc":[{"t":"Người thầy hai mươi tuổi. Đặt trên bục giảng, quay mặt xuống hai mươi mốt bộ bàn ghế học trò, chiếc bàn thầy giáo là nơi Nguyễn Tất Thành soạn bài, chấm bài và đứng giảng suốt gần nửa năm ở Trường Dục Thanh. Tháng 9/1910, khi ngồi xuống sau chiếc bàn này lần đầu, người thầy giáo ấy vừa tròn hai mươi tuổi."},{"t":"Con đường đưa anh tới đây khá dài. Giữa năm 1909, Nguyễn Tất Thành theo cha là cụ Phó bảng Nguyễn Sinh Sắc rời Huế vào Bình Định, khi cụ được cử làm tri huyện Bình Khê; từ tháng 9 năm ấy, người con trai mười chín tuổi được cha gửi xuống Quy Nhơn học thêm tiếng Pháp. Khoảng tháng 8/1910, anh rời Bình Định, một mình tiếp tục đi về phương Nam, qua Phan Rang rồi tới Phan Thiết. Nhờ cụ Trương Gia Mô, một nhà nho yêu nước quen biết cụ Nguyễn Sinh Sắc, đứng ra giới thiệu, anh được các nhà Duy Tân của hội Liên Thành đón nhận và mời dạy học tại Trường Dục Thanh."},{"t":"Vốn liếng để đứng lớp, thầy Thành có được từ nhiều năm trước đó: chữ Hán học từ cha và thầy đồ Vương Thúc Quý ở quê nhà Nam Đàn, Nghệ An; chữ Quốc ngữ và tiếng Pháp học ở các trường Pháp – Việt tại Huế rồi học thêm ở Quy Nhơn. Nhờ vậy, ngoài môn chính là chữ Quốc ngữ, chữ Hán và thể dục dành cho lớp nhì, khi trường thiếu người, thầy còn có thể đứng lớp dạy thay tiếng Pháp — điều không phải giáo viên trẻ nào ở một trường làng nhỏ cũng làm được."},{"t":"Ngoài giờ đứng sau chiếc bàn này, thầy Thành sống ngay trong khuôn viên trường, tại Nhà Ngư — ngôi nhà dựng năm 1906 để chứa ngư cụ, được cải làm nơi ở nội trú cho thầy và một số học trò xa nhà. Một thầy giáo hai mươi tuổi, chưa vợ con, ăn ở cùng học trò dưới một mái nhà, hẳn đã có một quãng thời gian sống giản dị, gắn bó với ngôi trường nhiều hơn là quan hệ giữa một người dạy và những người học thông thường. Gần nửa năm đứng lớp bên dòng Cà Ty, như chính lời kể về ngôi trường vẫn nhắc, là chặng dừng chân dài cuối cùng của người thanh niên ấy trên đất nước trước khi vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước."},{"t":"Sau chiếc bàn ấy, thầy Thành cũng là người đưa ra một lối dạy mới: giảng xong một ý, dừng lại hỏi học trò đã hiểu chưa rồi mới đi tiếp, khen ngợi khi trò tiến bộ, ân cần khi trò mắc lỗi. Tháng 2/1911, thầy đứng dậy rời chiếc bàn này lần cuối, rời Dục Thanh vào Sài Gòn; bốn tháng sau xuống tàu sang Pháp, khép lại chặng dừng chân dài cuối cùng trên đất nước trước khi bắt đầu ba mươi năm bôn ba tìm đường cứu nước. Khu di tích Trường Dục Thanh, được trùng tu năm 1978–1980 và xếp hạng di tích quốc gia năm 1986, đến nay vẫn giữ nguyên vị trí chiếc bàn giáo viên ấy trên bục giảng, như một lời nhắc về người thầy giáo hai mươi tuổi từng đứng đó."},{"t":"Bạn có biết? Ngoài chữ Quốc ngữ, chữ Hán và thể dục, khi trường cần, thầy Nguyễn Tất Thành còn dạy thay cả tiếng Pháp cho học trò Dục Thanh (Hồ Chí Minh – Biên niên tiểu sử, tập 1)."}],"ban_co_biet":"Ngoài chữ Quốc ngữ, chữ Hán và thể dục, khi trường cần, thầy Nguyễn Tất Thành còn dạy thay cả tiếng Pháp cho học trò Dục Thanh (Hồ Chí Minh – Biên niên tiểu sử, tập 1)."},{"id":"vintage_oil_lamp@-5.1,-1.9","x":-5.1,"y":1.74,"z":-1.95,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ánh đèn của những buổi soạn bài","text":"Ngọn đèn dầu đặt trên bàn thầy giáo trong không gian phục dựng là vật dụng minh họa, không phải hiện vật gốc còn giữ lại từ Trường Dục Thanh; nó được dựng lên để gợi lại cách chiếu sáng quen thuộc của một ngôi trường làng nhỏ đầu thế kỷ hai mươi, khi ánh đèn dầu leo lét thay cho ánh điện. Đặt cạnh chồng sách, quyển giáo án, ngọn đèn ấy muốn kể một câu chuyện: câu chuyện về những buổi tối một thầy giáo trẻ ngồi lại một mình sau giờ lên lớp.\n\nTheo tư liệu của khu di tích, người thực sự ngồi soạn bài, đọc sách báo trong những tháng dạy học ở Dục Thanh không phải ở ngay bàn giáo viên trong lớp, mà tại Ngọa Du Sào — ngôi nhà nhỏ trong khuôn viên trường được dùng làm thư viện. Ngọa Du Sào vốn do nhà thơ, nhà yêu nước Nguyễn Thông dựng từ năm 1880, trước khi Trường Dục Thanh ra đời gần ba mươi năm; khi trường hoạt động, người ta cải dùng ngôi nhà ấy để chứa sách báo, làm nơi cho thầy trò tra cứu, đọc thêm ngoài giờ học chính khóa.\n\nNgôi trường nhỏ bên sông Cà Ty ấy ra đời giữa lúc phong trào Duy Tân, do Phan Châu Trinh khởi xướng với chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”, đang lan rộng khắp Trung Kỳ. Cùng thời với Dục Thanh, ở Hà Nội có Đông Kinh Nghĩa Thục, mở tháng 3/1907 nhưng bị chính quyền thực dân đóng cửa ngay cuối năm ấy. Dục Thanh, xa kinh đô hơn, lặng lẽ hơn, vẫn tồn tại và đang hoạt động khi thầy Nguyễn Tất Thành đến dạy năm 1910 — nhờ vậy mà ngọn đèn trong lớp học, và ngọn đèn thật sự bên trang sách ở Ngọa Du Sào, còn có dịp thắp sáng cho một thế hệ học trò khác.\n\nCác nhà Duy Tân đầu thế kỷ hai mươi, trong đó có những người sáng lập Trường Dục Thanh, rất coi trọng “tân thư” — loại sách báo mới giới thiệu tư tưởng, học thuật phương Tây và các cuộc duy tân đang diễn ra ở châu Á. Trong ánh đèn dầu tại Ngọa Du Sào, thầy giáo trẻ Nguyễn Tất Thành hẳn đã có những giờ đọc thêm như thế, bên cạnh việc soạn bài giảng chữ Quốc ngữ, chữ Hán cho học trò lớp nhì vào sáng hôm sau.\n\nMột ngày của thầy giáo hai mươi tuổi ở Dục Thanh, vì thế, có thể hình dung theo một nhịp quen thuộc: ban ngày đứng lớp bên tấm bảng đen, tối về Nhà Ngư — nơi ở nội trú của thầy và trò — rồi sang Ngọa Du Sào bên ánh đèn dầu để đọc thêm, soạn bài cho hôm sau. Ba không gian nhỏ bé ấy, lớp học, chỗ ở và thư viện, đều nằm gọn trong khuôn viên một ngôi trường làng, nhưng đã đủ để nuôi dưỡng thói quen tự học của một người sau này đi khắp năm châu bốn biển vẫn không ngừng đọc, không ngừng viết.\n\nNhà Ngọa Du Sào, cùng với lớp học và nhà Ngư, được trùng tu từ tháng 11/1978 đến tháng 12/1980 theo đúng dáng xưa, rồi được xếp vào khu di tích lịch sử – văn hóa cấp quốc gia năm 1986. Ngọn đèn dầu trong lớp học phục dựng, vì vậy, nên được hiểu như một chi tiết gợi không khí chung của thời đại, còn câu chuyện thật về ánh đèn soạn bài của thầy Thành thuộc về gian nhà nhỏ mang tên Ngọa Du Sào, nơi khách tham quan hôm nay vẫn có thể bước vào.","nguon":"Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành; VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","doc":[{"t":"Ánh đèn của những buổi soạn bài. Ngọn đèn dầu đặt trên bàn thầy giáo trong không gian phục dựng là vật dụng minh họa, không phải hiện vật gốc còn giữ lại từ Trường Dục Thanh; nó được dựng lên để gợi lại cách chiếu sáng quen thuộc của một ngôi trường làng nhỏ đầu thế kỷ hai mươi, khi ánh đèn dầu leo lét thay cho ánh điện. Đặt cạnh chồng sách, quyển giáo án, ngọn đèn ấy muốn kể một câu chuyện: câu chuyện về những buổi tối một thầy giáo trẻ ngồi lại một mình sau giờ lên lớp."},{"t":"Theo tư liệu của khu di tích, người thực sự ngồi soạn bài, đọc sách báo trong những tháng dạy học ở Dục Thanh không phải ở ngay bàn giáo viên trong lớp, mà tại Ngọa Du Sào — ngôi nhà nhỏ trong khuôn viên trường được dùng làm thư viện. Ngọa Du Sào vốn do nhà thơ, nhà yêu nước Nguyễn Thông dựng từ năm 1880, trước khi Trường Dục Thanh ra đời gần ba mươi năm; khi trường hoạt động, người ta cải dùng ngôi nhà ấy để chứa sách báo, làm nơi cho thầy trò tra cứu, đọc thêm ngoài giờ học chính khóa."},{"t":"Ngôi trường nhỏ bên sông Cà Ty ấy ra đời giữa lúc phong trào Duy Tân, do Phan Châu Trinh khởi xướng với chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”, đang lan rộng khắp Trung Kỳ. Cùng thời với Dục Thanh, ở Hà Nội có Đông Kinh Nghĩa Thục, mở tháng 3/1907 nhưng bị chính quyền thực dân đóng cửa ngay cuối năm ấy. Dục Thanh, xa kinh đô hơn, lặng lẽ hơn, vẫn tồn tại và đang hoạt động khi thầy Nguyễn Tất Thành đến dạy năm 1910 — nhờ vậy mà ngọn đèn trong lớp học, và ngọn đèn thật sự bên trang sách ở Ngọa Du Sào, còn có dịp thắp sáng cho một thế hệ học trò khác."},{"t":"Các nhà Duy Tân đầu thế kỷ hai mươi, trong đó có những người sáng lập Trường Dục Thanh, rất coi trọng “tân thư” — loại sách báo mới giới thiệu tư tưởng, học thuật phương Tây và các cuộc duy tân đang diễn ra ở châu Á. Trong ánh đèn dầu tại Ngọa Du Sào, thầy giáo trẻ Nguyễn Tất Thành hẳn đã có những giờ đọc thêm như thế, bên cạnh việc soạn bài giảng chữ Quốc ngữ, chữ Hán cho học trò lớp nhì vào sáng hôm sau."},{"t":"Một ngày của thầy giáo hai mươi tuổi ở Dục Thanh, vì thế, có thể hình dung theo một nhịp quen thuộc: ban ngày đứng lớp bên tấm bảng đen, tối về Nhà Ngư — nơi ở nội trú của thầy và trò — rồi sang Ngọa Du Sào bên ánh đèn dầu để đọc thêm, soạn bài cho hôm sau. Ba không gian nhỏ bé ấy, lớp học, chỗ ở và thư viện, đều nằm gọn trong khuôn viên một ngôi trường làng, nhưng đã đủ để nuôi dưỡng thói quen tự học của một người sau này đi khắp năm châu bốn biển vẫn không ngừng đọc, không ngừng viết."},{"t":"Nhà Ngọa Du Sào, cùng với lớp học và nhà Ngư, được trùng tu từ tháng 11/1978 đến tháng 12/1980 theo đúng dáng xưa, rồi được xếp vào khu di tích lịch sử – văn hóa cấp quốc gia năm 1986. Ngọn đèn dầu trong lớp học phục dựng, vì vậy, nên được hiểu như một chi tiết gợi không khí chung của thời đại, còn câu chuyện thật về ánh đèn soạn bài của thầy Thành thuộc về gian nhà nhỏ mang tên Ngọa Du Sào, nơi khách tham quan hôm nay vẫn có thể bước vào."},{"t":"Bạn có biết? Ngọa Du Sào có trước Trường Dục Thanh gần ba mươi năm: nhà thơ Nguyễn Thông dựng ngôi nhà này từ năm 1880, sau trở thành thư viện của trường (VnExpress)."}],"ban_co_biet":"Ngọa Du Sào có trước Trường Dục Thanh gần ba mươi năm: nhà thơ Nguyễn Thông dựng ngôi nhà này từ năm 1880, sau trở thành thư viện của trường (VnExpress)."},{"id":"blackboard@-6.3,-3.4","x":-6.27,"y":1.66,"z":-3.4,"loai":"blackboard","ten":"Bảng đen","tieu_de":"Chữ Quốc ngữ – môn học chính","text":"Treo trên vách gỗ đối diện hai mươi mốt bộ bàn ghế học trò, tấm bảng đen là nơi mỗi buổi sáng thầy Nguyễn Tất Thành viết lên những dòng chữ Quốc ngữ đầu tiên cho học trò lớp nhì đọc theo. Ở Trường Dục Thanh năm 1910, chữ Quốc ngữ được dạy làm môn chính, bên cạnh chữ Hán, chữ Pháp và thể dục — một chương trình khá mới mẻ so với lối học khoa cử nặng về kinh sử chữ Hán còn phổ biến ở nhiều nơi khi đó.\n\nViệc chọn chữ Quốc ngữ làm trọng tâm không phải ngẫu nhiên. Đầu thế kỷ hai mươi, phong trào Duy Tân do Phan Châu Trinh khởi xướng, với chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”, lan rộng khắp Trung Kỳ. Những người sáng lập Trường Dục Thanh — Nguyễn Trọng Lội, Nguyễn Quý Anh cùng các đồng sự trong hội buôn Liên Thành — chính là những nhà nho hưởng ứng tinh thần ấy. Họ tin rằng thứ chữ dễ học, dễ phổ biến này là công cụ để “khai dân trí”: giúp người dân nhanh chóng biết đọc, biết viết, từ đó tiếp cận được tri thức mới, ý thức mới về vận mệnh đất nước. Trên tấm bảng này, mỗi nét chữ Quốc ngữ thầy Thành viết ra vì thế mang theo cả một chủ trương của phong trào Duy Tân đương thời.\n\nHơn ba mươi năm sau những buổi đứng lớp ở Dục Thanh, người thầy giáo trẻ năm nào, trên cương vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa, đã coi việc dạy chữ là một trong những nhiệm vụ cấp bách nhất của chính quyền non trẻ. Ngay tại phiên họp đầu tiên của Chính phủ lâm thời, ngày 3/9/1945, Người nêu chống nạn dốt lên hàng đầu, chỉ sau chống giặc đói. Năm ngày sau, 8/9/1945, Chủ tịch Hồ Chí Minh ký sắc lệnh thành lập Nha Bình dân học vụ, phát động phong trào xóa nạn mù chữ trên khắp cả nước. Cũng trong tháng chín năm ấy, nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, Người còn gửi thư cho học sinh cả nước. Trong thư có câu được nhắc lại mãi về sau: “Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em”. Tấm bảng đen nhỏ ở một trường làng bên sông Cà Ty, theo cách nào đó, đã báo trước cho một phong trào học chữ Quốc ngữ có quy mô toàn quốc nhiều năm về sau, cùng chung một niềm tin rằng biết chữ là bước đầu để một dân tộc tự cường.\n\nGần nửa thế kỷ sau ngày rời bục giảng Dục Thanh, khi nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc ngày 13/9/1958, Người vẫn nhắc các thầy cô giáo bằng một câu nói giản dị mà về sau trở thành kim chỉ nam cho ngành giáo dục: “Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người”. Câu nói ấy, so với những dòng chữ Quốc ngữ đầu tiên viết trên tấm bảng đen này năm 1910, cho thấy một mạch suy nghĩ xuyên suốt: việc dạy chữ, dạy người không bao giờ là chuyện của một sớm một chiều.\n\nLớp học chứa tấm bảng đen này được trùng tu năm 1978–1980 theo dáng xưa và xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986. Ngày nay, đứng trước tấm bảng đen phục dựng, khách tham quan có thể hình dung lại cảnh một thầy giáo hai mươi tuổi viết từng chữ Quốc ngữ, mở đầu cho một hành trình giáo dục mà chính người sẽ còn theo đuổi suốt cả cuộc đời sau này.","nguon":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh; Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành","doc":[{"t":"Chữ Quốc ngữ – môn học chính. Treo trên vách gỗ đối diện hai mươi mốt bộ bàn ghế học trò, tấm bảng đen là nơi mỗi buổi sáng thầy Nguyễn Tất Thành viết lên những dòng chữ Quốc ngữ đầu tiên cho học trò lớp nhì đọc theo. Ở Trường Dục Thanh năm 1910, chữ Quốc ngữ được dạy làm môn chính, bên cạnh chữ Hán, chữ Pháp và thể dục — một chương trình khá mới mẻ so với lối học khoa cử nặng về kinh sử chữ Hán còn phổ biến ở nhiều nơi khi đó."},{"t":"Việc chọn chữ Quốc ngữ làm trọng tâm không phải ngẫu nhiên. Đầu thế kỷ hai mươi, phong trào Duy Tân do Phan Châu Trinh khởi xướng, với chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”, lan rộng khắp Trung Kỳ. Những người sáng lập Trường Dục Thanh — Nguyễn Trọng Lội, Nguyễn Quý Anh cùng các đồng sự trong hội buôn Liên Thành — chính là những nhà nho hưởng ứng tinh thần ấy. Họ tin rằng thứ chữ dễ học, dễ phổ biến này là công cụ để “khai dân trí”: giúp người dân nhanh chóng biết đọc, biết viết, từ đó tiếp cận được tri thức mới, ý thức mới về vận mệnh đất nước. Trên tấm bảng này, mỗi nét chữ Quốc ngữ thầy Thành viết ra vì thế mang theo cả một chủ trương của phong trào Duy Tân đương thời."},{"t":"Hơn ba mươi năm sau những buổi đứng lớp ở Dục Thanh, người thầy giáo trẻ năm nào, trên cương vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa, đã coi việc dạy chữ là một trong những nhiệm vụ cấp bách nhất của chính quyền non trẻ. Ngay tại phiên họp đầu tiên của Chính phủ lâm thời, ngày 3/9/1945, Người nêu chống nạn dốt lên hàng đầu, chỉ sau chống giặc đói. Năm ngày sau, 8/9/1945, Chủ tịch Hồ Chí Minh ký sắc lệnh thành lập Nha Bình dân học vụ, phát động phong trào xóa nạn mù chữ trên khắp cả nước. Cũng trong tháng chín năm ấy, nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, Người còn gửi thư cho học sinh cả nước. Trong thư có câu được nhắc lại mãi về sau: “Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em”. Tấm bảng đen nhỏ ở một trường làng bên sông Cà Ty, theo cách nào đó, đã báo trước cho một phong trào học chữ Quốc ngữ có quy mô toàn quốc nhiều năm về sau, cùng chung một niềm tin rằng biết chữ là bước đầu để một dân tộc tự cường."},{"t":"Gần nửa thế kỷ sau ngày rời bục giảng Dục Thanh, khi nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc ngày 13/9/1958, Người vẫn nhắc các thầy cô giáo bằng một câu nói giản dị mà về sau trở thành kim chỉ nam cho ngành giáo dục: “Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người”. Câu nói ấy, so với những dòng chữ Quốc ngữ đầu tiên viết trên tấm bảng đen này năm 1910, cho thấy một mạch suy nghĩ xuyên suốt: việc dạy chữ, dạy người không bao giờ là chuyện của một sớm một chiều."},{"t":"Lớp học chứa tấm bảng đen này được trùng tu năm 1978–1980 theo dáng xưa và xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986. Ngày nay, đứng trước tấm bảng đen phục dựng, khách tham quan có thể hình dung lại cảnh một thầy giáo hai mươi tuổi viết từng chữ Quốc ngữ, mở đầu cho một hành trình giáo dục mà chính người sẽ còn theo đuổi suốt cả cuộc đời sau này."},{"t":"Bạn có biết? Ngày 8/9/1945, chỉ vài ngày sau khi đọc Tuyên ngôn Độc lập, Chủ tịch Hồ Chí Minh ký sắc lệnh lập Nha Bình dân học vụ, mở phong trào xóa nạn mù chữ trong cả nước (Hồ Chí Minh Toàn tập)."}],"ban_co_biet":"Ngày 8/9/1945, chỉ vài ngày sau khi đọc Tuyên ngôn Độc lập, Chủ tịch Hồ Chí Minh ký sắc lệnh lập Nha Bình dân học vụ, mở phong trào xóa nạn mù chữ trong cả nước (Hồ Chí Minh Toàn tập)."},{"id":"blackboard@-6.3,-0.6","x":-6.27,"y":1.66,"z":-0.6,"loai":"blackboard","ten":"Bảng đen thứ hai","tieu_de":"Một chương trình học rất mới","text":"Cách tấm bảng đen chính vài bước, tấm bảng thứ hai trong lớp học Trường Dục Thanh cũng được dùng để ghi bài, ôn tập cho học trò lớp nhì. Sự có mặt của hai tấm bảng trong một lớp học chỉ chừng vài chục học trò cho thấy nhà trường khá chú trọng việc dạy chữ — điều dễ hiểu, bởi Dục Thanh không phải một trường làng bình thường mà ra đời từ một chủ trương cải cách rõ ràng.\n\nĐầu thế kỷ hai mươi, phần đông con em trong nước vẫn theo lối học khoa cử, lấy kinh sử chữ Hán làm gốc để thi cử, tiến thân. Ở Phan Thiết, nhóm nhà nho yêu nước quanh nhà thơ Nguyễn Thông chọn một con đường khác. Tháng 3/1906, sáu người trong số họ — Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi, Ngô Văn Nhượng — lập ra hội buôn Liên Thành, làm nước mắm, lấy lợi nhuận nuôi việc học. Năm 1907, họ dựng nên Trường Dục Thanh, dạy chữ Quốc ngữ làm chính, thêm chữ Hán, chữ Pháp và cả môn thể dục.\n\nChương trình ấy là cách những người theo phong trào Duy Tân ở Bình Thuận hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh” mà Phan Châu Trinh khởi xướng: mở mang hiểu biết cho dân, chấn chỉnh khí phách dân tộc, lo cho đời sống của dân. Trên hai tấm bảng đen của lớp học nhỏ này, chữ Quốc ngữ, chữ Hán, tiếng Pháp được dạy song song, không đối lập nhau, miễn là giúp học trò mở mang kiến thức để phụng sự đất nước sau này.\n\nBản thân việc sáu nhà nho đứng ra lập hội buôn Liên Thành cũng đã là một điều khác thường: trong một xã hội còn xếp “sĩ, nông, công, thương” theo thứ bậc, coi nghề buôn bán đứng sau cùng, thì việc nhà nho tự bỏ vốn đi buôn nước mắm để lấy tiền mở trường là một lựa chọn táo bạo, đi ngược nếp nghĩ quen thuộc. Chính từ sự táo bạo ấy mới có được hai tấm bảng đen trong gian lớp học nhỏ này, cùng một chương trình dạy chữ vượt xa khuôn khổ của một trường làng bình thường.\n\nMô hình lấy việc buôn bán nuôi việc học ấy tỏ ra bền bỉ: hội buôn Liên Thành, chỗ dựa tài chính cho Trường Dục Thanh, còn tồn tại và hoạt động đến tận năm 1975, đi từ một hội buôn nước mắm của các nhà Duy Tân thành một doanh nghiệp có tiếng ở Nam Trung Bộ. Chương trình học mới mẻ được ghi trên hai tấm bảng đen này, vì vậy, không phải một thử nghiệm ngắn ngủi, mà gắn liền với một tổ chức kinh tế – giáo dục tồn tại suốt gần bảy thập niên.\n\nTháng 9/1910, thầy giáo trẻ Nguyễn Tất Thành, khi ấy vừa tròn hai mươi tuổi, đứng vào đúng chương trình mới mẻ ấy, phụ trách lớp nhì, dạy chữ Quốc ngữ, chữ Hán, thể dục và thay tiếng Pháp khi trường cần. Khu di tích Trường Dục Thanh, với gian lớp học còn giữ hai tấm bảng đen, được trùng tu năm 1978–1980 và xếp hạng di tích quốc gia năm 1986, đến nay vẫn là nơi kể lại câu chuyện về một chương trình giáo dục đi trước thời đại ở một thị xã nhỏ ven biển miền Trung.","nguon":"Báo Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành; VUSTA – Công ty Liên Thành (1906–1975): Từ hội Duy Tân đến doanh nghiệp hiện đại; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","doc":[{"t":"Một chương trình học rất mới. Cách tấm bảng đen chính vài bước, tấm bảng thứ hai trong lớp học Trường Dục Thanh cũng được dùng để ghi bài, ôn tập cho học trò lớp nhì. Sự có mặt của hai tấm bảng trong một lớp học chỉ chừng vài chục học trò cho thấy nhà trường khá chú trọng việc dạy chữ — điều dễ hiểu, bởi Dục Thanh không phải một trường làng bình thường mà ra đời từ một chủ trương cải cách rõ ràng."},{"t":"Đầu thế kỷ hai mươi, phần đông con em trong nước vẫn theo lối học khoa cử, lấy kinh sử chữ Hán làm gốc để thi cử, tiến thân. Ở Phan Thiết, nhóm nhà nho yêu nước quanh nhà thơ Nguyễn Thông chọn một con đường khác. Tháng 3/1906, sáu người trong số họ — Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi, Ngô Văn Nhượng — lập ra hội buôn Liên Thành, làm nước mắm, lấy lợi nhuận nuôi việc học. Năm 1907, họ dựng nên Trường Dục Thanh, dạy chữ Quốc ngữ làm chính, thêm chữ Hán, chữ Pháp và cả môn thể dục."},{"t":"Chương trình ấy là cách những người theo phong trào Duy Tân ở Bình Thuận hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh” mà Phan Châu Trinh khởi xướng: mở mang hiểu biết cho dân, chấn chỉnh khí phách dân tộc, lo cho đời sống của dân. Trên hai tấm bảng đen của lớp học nhỏ này, chữ Quốc ngữ, chữ Hán, tiếng Pháp được dạy song song, không đối lập nhau, miễn là giúp học trò mở mang kiến thức để phụng sự đất nước sau này."},{"t":"Bản thân việc sáu nhà nho đứng ra lập hội buôn Liên Thành cũng đã là một điều khác thường: trong một xã hội còn xếp “sĩ, nông, công, thương” theo thứ bậc, coi nghề buôn bán đứng sau cùng, thì việc nhà nho tự bỏ vốn đi buôn nước mắm để lấy tiền mở trường là một lựa chọn táo bạo, đi ngược nếp nghĩ quen thuộc. Chính từ sự táo bạo ấy mới có được hai tấm bảng đen trong gian lớp học nhỏ này, cùng một chương trình dạy chữ vượt xa khuôn khổ của một trường làng bình thường."},{"t":"Mô hình lấy việc buôn bán nuôi việc học ấy tỏ ra bền bỉ: hội buôn Liên Thành, chỗ dựa tài chính cho Trường Dục Thanh, còn tồn tại và hoạt động đến tận năm 1975, đi từ một hội buôn nước mắm của các nhà Duy Tân thành một doanh nghiệp có tiếng ở Nam Trung Bộ. Chương trình học mới mẻ được ghi trên hai tấm bảng đen này, vì vậy, không phải một thử nghiệm ngắn ngủi, mà gắn liền với một tổ chức kinh tế – giáo dục tồn tại suốt gần bảy thập niên."},{"t":"Tháng 9/1910, thầy giáo trẻ Nguyễn Tất Thành, khi ấy vừa tròn hai mươi tuổi, đứng vào đúng chương trình mới mẻ ấy, phụ trách lớp nhì, dạy chữ Quốc ngữ, chữ Hán, thể dục và thay tiếng Pháp khi trường cần. Khu di tích Trường Dục Thanh, với gian lớp học còn giữ hai tấm bảng đen, được trùng tu năm 1978–1980 và xếp hạng di tích quốc gia năm 1986, đến nay vẫn là nơi kể lại câu chuyện về một chương trình giáo dục đi trước thời đại ở một thị xã nhỏ ven biển miền Trung."},{"t":"Bạn có biết? Hội buôn Liên Thành ra đời tháng 3/1906, trước cả khi có Trường Dục Thanh, và dùng lợi nhuận từ nghề làm nước mắm để trang trải chi phí cho nhà trường (Người Lao Động)."}],"ban_co_biet":"Hội buôn Liên Thành ra đời tháng 3/1906, trước cả khi có Trường Dục Thanh, và dùng lợi nhuận từ nghề làm nước mắm để trang trải chi phí cho nhà trường (Người Lao Động)."},{"id":"phan@23.3,-11.9","x":23.34,"y":0.66,"z":-11.88,"loai":"phan","ten":"Phản gỗ","tieu_de":"Góc nhà nho trong Ngọa Du Sào","text":"Chiếc phản gỗ kê trong gian nhà Ngọa Du Sào là vật dụng minh họa, dựng lên để gợi nếp sinh hoạt của một ngôi nhà nho xưa ở Nam Trung Bộ đầu thế kỷ hai mươi, chứ không phải hiện vật gốc còn giữ lại nguyên trạng. Trên phản, có thể hình dung một chồng sách, một ấm trà — hình ảnh quen thuộc trong không gian sống của những nhà nho yêu nước từng lui tới nơi này.\n\nNgọa Du Sào do chính chủ nhân khu đất, nhà thơ, nhà yêu nước Nguyễn Thông, dựng lên từ năm 1880 — trước khi Trường Dục Thanh ra đời gần ba mươi năm. Tên ngôi nhà gồm ba chữ Hán: “ngọa” (臥) là nằm, “du” (遊) là đi chơi, ngao du, “sào” (巢) là cái tổ; ghép lại, “Ngọa Du Sào” có thể hiểu là “cái tổ để nằm mà ngao du” — nằm trong căn nhà nhỏ mà thả hồn theo sách vở, theo chuyện non sông.\n\nNguyễn Thông vốn quê ở Nam Kỳ. Khi đất Nam Kỳ lần lượt rơi vào tay thực dân Pháp, ông không chịu sống dưới ách cai trị của giặc mà ra Bình Thuận lập nghiệp, mang theo cả gia quyến. Là một nhà thơ, nhà nho có tiếng, từng làm quan rồi lui về sống những năm cuối đời bên dòng Cà Ty, ông để lại nhiều thơ văn và được xem là một trong những gương mặt tiêu biểu của giới sĩ phu yêu nước Nam Kỳ cuối thế kỷ mười chín. Chiếc phản gỗ trong gian nhà nhỏ này, vì vậy, gợi lại không chỉ nếp sống một nhà nho, mà cả khí tiết của một người trí thức thà bỏ quê hương chứ không chịu sống chung với giặc.\n\nKhi Trường Dục Thanh đi vào hoạt động từ năm 1907, con cháu cụ Nguyễn Thông là Nguyễn Trọng Lội, Nguyễn Quý Anh đã dùng lại chính ngôi nhà Ngọa Du Sào của cha mình làm thư viện cho trường. Theo tư liệu của khu di tích, đây là nơi thầy giáo trẻ Nguyễn Tất Thành thường đọc sách báo, soạn bài trong những tháng dạy học tại Dục Thanh — tiếp nối một không gian vốn đã mang hồn cốt của một nhà nho yêu nước từ ba mươi năm trước đó.\n\nCó một mạch nối âm thầm giữa ba thế hệ trong gian nhà nhỏ này. Nguyễn Thông, nhà nho từng làm quan rồi lui về ở ẩn, dựng Ngọa Du Sào để tìm một chốn riêng đọc sách, ngẫm sự đời theo lối người xưa. Con trai ông, Nguyễn Trọng Lội và Nguyễn Quý Anh, lại mang tinh thần Duy Tân, biến gian nhà của cha thành thư viện công cộng cho một ngôi trường dạy chữ Quốc ngữ. Rồi đến lượt một thầy giáo trẻ từ xứ Nghệ vào, ngồi đọc sách trong chính gian nhà ấy, để chỉ ít năm sau chọn một con đường cứu nước khác hẳn hai thế hệ trước — không phải ở ẩn, không dừng ở Duy Tân trong nước, mà ra đi khắp năm châu tìm đường giải phóng dân tộc.\n\nNhà Ngọa Du Sào, cùng lớp học và nhà Ngư, được trùng tu từ tháng 11/1978 đến tháng 12/1980 theo đúng dáng xưa, nằm trong khu di tích được xếp hạng lịch sử – văn hóa cấp quốc gia năm 1986. Chiếc phản gỗ minh họa trong gian nhà nhỏ ấy, vì thế, là một cách để khách tham quan hôm nay hình dung lại không gian sống giản dị mà thâm trầm của một ngôi nhà nho từng nuôi dưỡng cả một thế hệ Duy Tân ở Phan Thiết.","nguon":"VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết; Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","doc":[{"t":"Góc nhà nho trong Ngọa Du Sào. Chiếc phản gỗ kê trong gian nhà Ngọa Du Sào là vật dụng minh họa, dựng lên để gợi nếp sinh hoạt của một ngôi nhà nho xưa ở Nam Trung Bộ đầu thế kỷ hai mươi, chứ không phải hiện vật gốc còn giữ lại nguyên trạng. Trên phản, có thể hình dung một chồng sách, một ấm trà — hình ảnh quen thuộc trong không gian sống của những nhà nho yêu nước từng lui tới nơi này."},{"t":"Ngọa Du Sào do chính chủ nhân khu đất, nhà thơ, nhà yêu nước Nguyễn Thông, dựng lên từ năm 1880 — trước khi Trường Dục Thanh ra đời gần ba mươi năm. Tên ngôi nhà gồm ba chữ Hán: “ngọa” (臥) là nằm, “du” (遊) là đi chơi, ngao du, “sào” (巢) là cái tổ; ghép lại, “Ngọa Du Sào” có thể hiểu là “cái tổ để nằm mà ngao du” — nằm trong căn nhà nhỏ mà thả hồn theo sách vở, theo chuyện non sông."},{"t":"Nguyễn Thông vốn quê ở Nam Kỳ. Khi đất Nam Kỳ lần lượt rơi vào tay thực dân Pháp, ông không chịu sống dưới ách cai trị của giặc mà ra Bình Thuận lập nghiệp, mang theo cả gia quyến. Là một nhà thơ, nhà nho có tiếng, từng làm quan rồi lui về sống những năm cuối đời bên dòng Cà Ty, ông để lại nhiều thơ văn và được xem là một trong những gương mặt tiêu biểu của giới sĩ phu yêu nước Nam Kỳ cuối thế kỷ mười chín. Chiếc phản gỗ trong gian nhà nhỏ này, vì vậy, gợi lại không chỉ nếp sống một nhà nho, mà cả khí tiết của một người trí thức thà bỏ quê hương chứ không chịu sống chung với giặc."},{"t":"Khi Trường Dục Thanh đi vào hoạt động từ năm 1907, con cháu cụ Nguyễn Thông là Nguyễn Trọng Lội, Nguyễn Quý Anh đã dùng lại chính ngôi nhà Ngọa Du Sào của cha mình làm thư viện cho trường. Theo tư liệu của khu di tích, đây là nơi thầy giáo trẻ Nguyễn Tất Thành thường đọc sách báo, soạn bài trong những tháng dạy học tại Dục Thanh — tiếp nối một không gian vốn đã mang hồn cốt của một nhà nho yêu nước từ ba mươi năm trước đó."},{"t":"Có một mạch nối âm thầm giữa ba thế hệ trong gian nhà nhỏ này. Nguyễn Thông, nhà nho từng làm quan rồi lui về ở ẩn, dựng Ngọa Du Sào để tìm một chốn riêng đọc sách, ngẫm sự đời theo lối người xưa. Con trai ông, Nguyễn Trọng Lội và Nguyễn Quý Anh, lại mang tinh thần Duy Tân, biến gian nhà của cha thành thư viện công cộng cho một ngôi trường dạy chữ Quốc ngữ. Rồi đến lượt một thầy giáo trẻ từ xứ Nghệ vào, ngồi đọc sách trong chính gian nhà ấy, để chỉ ít năm sau chọn một con đường cứu nước khác hẳn hai thế hệ trước — không phải ở ẩn, không dừng ở Duy Tân trong nước, mà ra đi khắp năm châu tìm đường giải phóng dân tộc."},{"t":"Nhà Ngọa Du Sào, cùng lớp học và nhà Ngư, được trùng tu từ tháng 11/1978 đến tháng 12/1980 theo đúng dáng xưa, nằm trong khu di tích được xếp hạng lịch sử – văn hóa cấp quốc gia năm 1986. Chiếc phản gỗ minh họa trong gian nhà nhỏ ấy, vì thế, là một cách để khách tham quan hôm nay hình dung lại không gian sống giản dị mà thâm trầm của một ngôi nhà nho từng nuôi dưỡng cả một thế hệ Duy Tân ở Phan Thiết."},{"t":"Bạn có biết? Tên gọi “Ngọa Du Sào” theo âm Hán Việt nghĩa là “cái tổ để nằm mà ngao du” — nơi nhà thơ Nguyễn Thông chọn để sống những năm cuối đời (VnExpress)."}],"ban_co_biet":"Tên gọi “Ngọa Du Sào” theo âm Hán Việt nghĩa là “cái tổ để nằm mà ngao du” — nơi nhà thơ Nguyễn Thông chọn để sống những năm cuối đời (VnExpress)."},{"id":"table@25.6,-11.5","x":25.55,"y":0.66,"z":-11.5,"loai":"table","ten":"Bàn đọc sách","tieu_de":"Thư viện nhỏ của một ngôi trường Duy Tân","text":"Trong gian nhà Ngọa Du Sào yên tĩnh, tách khỏi tiếng học trò ê a đọc bài bên lớp học chính, chiếc bàn đọc sách này là nơi thầy giáo Nguyễn Tất Thành ngồi lại sau mỗi buổi lên lớp. Theo tư liệu của khu di tích, đây chính là nơi thầy thường đọc sách báo và soạn bài trong gần nửa năm dạy học tại Trường Dục Thanh, từ tháng 9/1910 đến tháng 2/1911.\n\nNgọa Du Sào vốn là ngôi nhà riêng do nhà thơ, nhà yêu nước Nguyễn Thông dựng từ năm 1880; khi con trai ông là Nguyễn Trọng Lội và Nguyễn Quý Anh cùng các đồng sự lập nên Trường Dục Thanh năm 1907, ngôi nhà nhỏ ấy được chuyển thành thư viện của trường. Với một ngôi trường chỉ có dăm sáu chục học trò như Dục Thanh, việc có riêng một gian thư viện là điều không tầm thường, cho thấy những người sáng lập trường rất coi trọng việc đọc sách, tự học ngoài giờ lên lớp chính khóa.\n\nCác nhà Duy Tân đầu thế kỷ hai mươi, trong đó có những người đứng sau Trường Dục Thanh, đặc biệt coi trọng “tân thư” — loại sách báo mới giới thiệu tư tưởng, học thuật phương Tây cùng các cuộc duy tân đang diễn ra ở Nhật Bản, Trung Hoa. Ngồi bên chiếc bàn này, thầy giáo hai mươi tuổi hẳn đã có dịp tiếp xúc với luồng tư tưởng mới ấy, bên cạnh việc soạn từng bài giảng chữ Quốc ngữ, chữ Hán cho học trò lớp nhì vào sáng hôm sau — những giờ tự học âm thầm nhưng có thể đã góp phần nuôi lớn dần câu hỏi về vận mệnh đất nước trong lòng người thanh niên ấy.\n\nMột ngôi trường được nuôi bằng lợi nhuận nghề làm nước mắm của hội buôn Liên Thành mà vẫn giữ riêng một gian thư viện cho thầy giáo tự học, tưới đẫm chút gì tương tự với những gì các nhà Duy Tân theo đuổi: dùng công việc làm ăn cụ thể để nuôi những giá trị lâu dài hơn — tri thức, chữ nghĩa. Thói quen ngồi đọc, ngồi viết bên một chiếc bàn nhỏ mà thầy Thành có được ở Ngọa Du Sào, về sau đi theo suốt cuộc đời hoạt động của Người, từ những trang báo viết ở Pháp đến những trang văn kiện soạn thảo trong rừng Việt Bắc nhiều năm sau đó.\n\nViệc dạy học, đọc sách dường như cũng là một mạch nối trong chính gia đình thầy Thành. Cha ông, cụ Phó bảng Nguyễn Sinh Sắc, sau khi rời quan trường vì một vụ án liên quan đến cường hào ở Bình Khê, đã vào Nam Kỳ sinh sống bằng nghề bốc thuốc và dạy học, cho đến khi mất năm 1929 tại Cao Lãnh, nay thuộc tỉnh Đồng Tháp. Người cha từng dạy chữ Hán cho con trai mình ở quê nhà Nghệ An, đến lượt người con, lại trở thành thầy giáo dạy chữ Quốc ngữ cho lớp trẻ Phan Thiết, trước khi tiếp tục con đường học hỏi không ngừng nghỉ suốt cả cuộc đời sau này.\n\nTháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn, khép lại những buổi đọc sách bên chiếc bàn nhỏ trong Ngọa Du Sào để bắt đầu chặng đường mới. Ngôi nhà thư viện ấy, cùng lớp học và nhà Ngư, được trùng tu năm 1978–1980 theo dáng xưa, nằm trong khu di tích xếp hạng quốc gia năm 1986. Khách đến thăm Trường Dục Thanh hôm nay vẫn có thể bước vào Ngọa Du Sào, đứng trước chiếc bàn ấy để hình dung những giờ tự học lặng lẽ của một người thầy trẻ, trước khi trở thành người dẫn đường cho cả một dân tộc.","nguon":"Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành; VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết; Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","doc":[{"t":"Thư viện nhỏ của một ngôi trường Duy Tân. Trong gian nhà Ngọa Du Sào yên tĩnh, tách khỏi tiếng học trò ê a đọc bài bên lớp học chính, chiếc bàn đọc sách này là nơi thầy giáo Nguyễn Tất Thành ngồi lại sau mỗi buổi lên lớp. Theo tư liệu của khu di tích, đây chính là nơi thầy thường đọc sách báo và soạn bài trong gần nửa năm dạy học tại Trường Dục Thanh, từ tháng 9/1910 đến tháng 2/1911."},{"t":"Ngọa Du Sào vốn là ngôi nhà riêng do nhà thơ, nhà yêu nước Nguyễn Thông dựng từ năm 1880; khi con trai ông là Nguyễn Trọng Lội và Nguyễn Quý Anh cùng các đồng sự lập nên Trường Dục Thanh năm 1907, ngôi nhà nhỏ ấy được chuyển thành thư viện của trường. Với một ngôi trường chỉ có dăm sáu chục học trò như Dục Thanh, việc có riêng một gian thư viện là điều không tầm thường, cho thấy những người sáng lập trường rất coi trọng việc đọc sách, tự học ngoài giờ lên lớp chính khóa."},{"t":"Các nhà Duy Tân đầu thế kỷ hai mươi, trong đó có những người đứng sau Trường Dục Thanh, đặc biệt coi trọng “tân thư” — loại sách báo mới giới thiệu tư tưởng, học thuật phương Tây cùng các cuộc duy tân đang diễn ra ở Nhật Bản, Trung Hoa. Ngồi bên chiếc bàn này, thầy giáo hai mươi tuổi hẳn đã có dịp tiếp xúc với luồng tư tưởng mới ấy, bên cạnh việc soạn từng bài giảng chữ Quốc ngữ, chữ Hán cho học trò lớp nhì vào sáng hôm sau — những giờ tự học âm thầm nhưng có thể đã góp phần nuôi lớn dần câu hỏi về vận mệnh đất nước trong lòng người thanh niên ấy."},{"t":"Một ngôi trường được nuôi bằng lợi nhuận nghề làm nước mắm của hội buôn Liên Thành mà vẫn giữ riêng một gian thư viện cho thầy giáo tự học, tưới đẫm chút gì tương tự với những gì các nhà Duy Tân theo đuổi: dùng công việc làm ăn cụ thể để nuôi những giá trị lâu dài hơn — tri thức, chữ nghĩa. Thói quen ngồi đọc, ngồi viết bên một chiếc bàn nhỏ mà thầy Thành có được ở Ngọa Du Sào, về sau đi theo suốt cuộc đời hoạt động của Người, từ những trang báo viết ở Pháp đến những trang văn kiện soạn thảo trong rừng Việt Bắc nhiều năm sau đó."},{"t":"Việc dạy học, đọc sách dường như cũng là một mạch nối trong chính gia đình thầy Thành. Cha ông, cụ Phó bảng Nguyễn Sinh Sắc, sau khi rời quan trường vì một vụ án liên quan đến cường hào ở Bình Khê, đã vào Nam Kỳ sinh sống bằng nghề bốc thuốc và dạy học, cho đến khi mất năm 1929 tại Cao Lãnh, nay thuộc tỉnh Đồng Tháp. Người cha từng dạy chữ Hán cho con trai mình ở quê nhà Nghệ An, đến lượt người con, lại trở thành thầy giáo dạy chữ Quốc ngữ cho lớp trẻ Phan Thiết, trước khi tiếp tục con đường học hỏi không ngừng nghỉ suốt cả cuộc đời sau này."},{"t":"Tháng 2/1911, thầy Thành rời Dục Thanh vào Sài Gòn, khép lại những buổi đọc sách bên chiếc bàn nhỏ trong Ngọa Du Sào để bắt đầu chặng đường mới. Ngôi nhà thư viện ấy, cùng lớp học và nhà Ngư, được trùng tu năm 1978–1980 theo dáng xưa, nằm trong khu di tích xếp hạng quốc gia năm 1986. Khách đến thăm Trường Dục Thanh hôm nay vẫn có thể bước vào Ngọa Du Sào, đứng trước chiếc bàn ấy để hình dung những giờ tự học lặng lẽ của một người thầy trẻ, trước khi trở thành người dẫn đường cho cả một dân tộc."},{"t":"Bạn có biết? Ngọa Du Sào được dùng làm thư viện của Trường Dục Thanh ngay từ khi trường hoạt động, dù ngôi nhà đã có từ trước đó gần ba mươi năm (Báo Cần Thơ)."}],"ban_co_biet":"Ngọa Du Sào được dùng làm thư viện của Trường Dục Thanh ngay từ khi trường hoạt động, dù ngôi nhà đã có từ trước đó gần ba mươi năm (Báo Cần Thơ)."},{"id":"well@-9.0,10.0","x":-9,"y":0.29,"z":10,"loai":"well","ten":"Giếng nước","tieu_de":"Chiếc giếng gạch và cây khế","text":"Chiếc giếng gạch nằm giữa sân Trường Dục Thanh là nguồn nước sinh hoạt của cả thầy lẫn trò trong những tháng năm 1910–1911. Nước giếng dùng để nấu ăn, tắm giặt cho thầy trò sống nội trú trong khuôn viên trường, và cũng là nguồn nước tưới cho khu vườn nhỏ quanh nhà Ngọa Du Sào cùng lớp học.\n\nNhững học trò ở xa ăn ở tại Nhà Ngư — ngôi nhà dựng năm 1906 vốn để chứa ngư cụ, sau cải làm nơi nội trú cho thầy và trò — hằng ngày cũng ra chính chiếc giếng này gánh nước, dùng chung với thầy giáo của mình. Một chiếc giếng nhỏ giữa sân trường, vì thế, không chỉ phục vụ việc tưới cây, mà còn là nơi thầy trò gặp nhau mỗi sớm mỗi chiều, ngoài những giờ lên lớp có bảng đen, phấn trắng.\n\nTheo tư liệu của khu di tích, thầy giáo trẻ Nguyễn Tất Thành dùng nước giếng này hằng ngày, và thường tự tay múc nước tưới cho một cây khế trồng gần đó — cây khế do chính phu nhân cụ Nguyễn Thông trồng từ khi ông còn dựng Ngọa Du Sào, đến nay đã hơn một trăm năm tuổi. Một chi tiết nhỏ như vậy — một người thầy trẻ chăm chút cho một gốc cây trong sân trường — cho thấy nếp sống giản dị, gắn bó với cảnh vật xung quanh của thầy Thành trong quãng thời gian ở Phan Thiết.\n\nThói quen ấy dường như đi theo Người suốt cuộc đời. Cuối tháng 11/1959, Chủ tịch Hồ Chí Minh viết bài “Tết trồng cây” đăng trên báo Nhân Dân, kêu gọi toàn dân trồng cây gây rừng; từ mùa xuân năm 1960, Tết trồng cây trở thành một phong tục đẹp mỗi dịp đầu năm ở nước ta. Nhìn lại, gốc khế nhỏ trong sân Dục Thanh mà người thầy giáo hai mươi tuổi từng ngày ngày tưới nước, có thể xem là một trong những hình ảnh sớm nhất của mối gắn bó ấy với cây cối, ruộng vườn.\n\nTrường Dục Thanh nằm bên bờ sông Cà Ty, con sông chảy qua lòng thị xã Phan Thiết rồi đổ ra biển; trên sông ngày ấy là những chiếc thuyền nan, thuyền thúng của ngư dân qua lại. Sân giếng, gốc khế, dòng sông gần đó hợp thành một khung cảnh làng quê ven biển miền Trung bình dị, nơi một thanh niên hai mươi tuổi vừa đứng lớp dạy chữ, vừa sống cuộc sống thường nhật như bao người dân nơi đây, trước khi bước vào một hành trình lớn hơn nhiều của cả dân tộc.\n\nTháng 2/1911, khi thầy Thành rời Dục Thanh vào Sài Gòn, giếng nước và cây khế vẫn ở lại, tiếp tục phục vụ những thế hệ thầy trò sau này cho đến khi trường ngừng hoạt động. Khu di tích được trùng tu năm 1978–1980, xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986; chiếc giếng gạch cùng cây khế cổ thụ vẫn được giữ nguyên trong sân, trở thành một trong những điểm dừng chân quen thuộc của khách tham quan khi tìm về Trường Dục Thanh. Người Việt có câu “uống nước nhớ nguồn”; đứng trước chiếc giếng nhỏ và gốc khế già ấy, nhiều người tìm về Dục Thanh hôm nay vẫn lặng người nghĩ đến những ngày bình dị của một thầy giáo hai mươi tuổi, trước khi anh mang tên Nguyễn Ái Quốc rồi Hồ Chí Minh.","nguon":"Dân Việt – Trường Dục Thanh, nơi thầy giáo Nguyễn Tất Thành dạy học hơn 110 năm trước; Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành; Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận","doc":[{"t":"Chiếc giếng gạch và cây khế. Chiếc giếng gạch nằm giữa sân Trường Dục Thanh là nguồn nước sinh hoạt của cả thầy lẫn trò trong những tháng năm 1910–1911. Nước giếng dùng để nấu ăn, tắm giặt cho thầy trò sống nội trú trong khuôn viên trường, và cũng là nguồn nước tưới cho khu vườn nhỏ quanh nhà Ngọa Du Sào cùng lớp học."},{"t":"Những học trò ở xa ăn ở tại Nhà Ngư — ngôi nhà dựng năm 1906 vốn để chứa ngư cụ, sau cải làm nơi nội trú cho thầy và trò — hằng ngày cũng ra chính chiếc giếng này gánh nước, dùng chung với thầy giáo của mình. Một chiếc giếng nhỏ giữa sân trường, vì thế, không chỉ phục vụ việc tưới cây, mà còn là nơi thầy trò gặp nhau mỗi sớm mỗi chiều, ngoài những giờ lên lớp có bảng đen, phấn trắng."},{"t":"Theo tư liệu của khu di tích, thầy giáo trẻ Nguyễn Tất Thành dùng nước giếng này hằng ngày, và thường tự tay múc nước tưới cho một cây khế trồng gần đó — cây khế do chính phu nhân cụ Nguyễn Thông trồng từ khi ông còn dựng Ngọa Du Sào, đến nay đã hơn một trăm năm tuổi. Một chi tiết nhỏ như vậy — một người thầy trẻ chăm chút cho một gốc cây trong sân trường — cho thấy nếp sống giản dị, gắn bó với cảnh vật xung quanh của thầy Thành trong quãng thời gian ở Phan Thiết."},{"t":"Thói quen ấy dường như đi theo Người suốt cuộc đời. Cuối tháng 11/1959, Chủ tịch Hồ Chí Minh viết bài “Tết trồng cây” đăng trên báo Nhân Dân, kêu gọi toàn dân trồng cây gây rừng; từ mùa xuân năm 1960, Tết trồng cây trở thành một phong tục đẹp mỗi dịp đầu năm ở nước ta. Nhìn lại, gốc khế nhỏ trong sân Dục Thanh mà người thầy giáo hai mươi tuổi từng ngày ngày tưới nước, có thể xem là một trong những hình ảnh sớm nhất của mối gắn bó ấy với cây cối, ruộng vườn."},{"t":"Trường Dục Thanh nằm bên bờ sông Cà Ty, con sông chảy qua lòng thị xã Phan Thiết rồi đổ ra biển; trên sông ngày ấy là những chiếc thuyền nan, thuyền thúng của ngư dân qua lại. Sân giếng, gốc khế, dòng sông gần đó hợp thành một khung cảnh làng quê ven biển miền Trung bình dị, nơi một thanh niên hai mươi tuổi vừa đứng lớp dạy chữ, vừa sống cuộc sống thường nhật như bao người dân nơi đây, trước khi bước vào một hành trình lớn hơn nhiều của cả dân tộc."},{"t":"Tháng 2/1911, khi thầy Thành rời Dục Thanh vào Sài Gòn, giếng nước và cây khế vẫn ở lại, tiếp tục phục vụ những thế hệ thầy trò sau này cho đến khi trường ngừng hoạt động. Khu di tích được trùng tu năm 1978–1980, xếp hạng di tích lịch sử – văn hóa cấp quốc gia năm 1986; chiếc giếng gạch cùng cây khế cổ thụ vẫn được giữ nguyên trong sân, trở thành một trong những điểm dừng chân quen thuộc của khách tham quan khi tìm về Trường Dục Thanh. Người Việt có câu “uống nước nhớ nguồn”; đứng trước chiếc giếng nhỏ và gốc khế già ấy, nhiều người tìm về Dục Thanh hôm nay vẫn lặng người nghĩ đến những ngày bình dị của một thầy giáo hai mươi tuổi, trước khi anh mang tên Nguyễn Ái Quốc rồi Hồ Chí Minh."},{"t":"Bạn có biết? Cây khế cổ thụ trong sân trường do phu nhân cụ Nguyễn Thông trồng, đến nay đã hơn một trăm năm tuổi; thầy Thành thường tưới nước, chăm sóc cây trong thời gian dạy học ở đây (Dân Việt)."}],"ban_co_biet":"Cây khế cổ thụ trong sân trường do phu nhân cụ Nguyễn Thông trồng, đến nay đã hơn một trăm năm tuổi; thầy Thành thường tưới nước, chăm sóc cây trong thời gian dạy học ở đây (Dân Việt)."}]};
